const LOCATION_LOG_THROTTLE_MS = 10 * 60 * 1000; // 10 minutes

export const locationApi = {
    // Public visitor IP/location logging (no auth header; the API endpoint is anonymous).
    // Same pattern as before on the old site: the browser looks up its own IP + location
    // (ipwho.is, see utils/visitorGeo.js), then sends the IP and all the details to the API.
    // The API is called only when the IP changed or 10 minutes have passed, and the throttle
    // record is saved only after a successful call. Never throws: best-effort logging.
    getLocation: async (url) => {
        try {
            const geo = await getVisitorGeo();
            const currentIp = geo?.ip || null;

            let lastData = null;
            let lastTime = null;
            try {
                lastData = JSON.parse(localStorage.getItem("locationApiData") || "null");
                lastTime = JSON.parse(localStorage.getItem("locationApiTime") || "null");
            } catch {
                localStorage.removeItem("locationApiData");
                localStorage.removeItem("locationApiTime");
            }

            const now = Date.now();
            const shouldCallApi =
                !lastData ||
                !lastTime ||
                lastData.ip !== currentIp ||
                (now - lastTime.time) >= LOCATION_LOG_THROTTLE_MS;

            if (!shouldCallApi) {
                return null;
            }

            const params = new URLSearchParams({ url: url || "" });
            if (geo) {
                Object.entries({
                    ip: geo.ip,
                    country: geo.country,
                    countryCode: geo.countryCode,
                    region: geo.region,
                    city: geo.city,
                    timezone: geo.timezone,
                    isp: geo.isp,
                }).forEach(([key, value]) => { if (value) params.append(key, value); });
            }

            const response = await fetch(`${API_BASE_URL}/location/Get?${params.toString()}`);
            if (!response.ok) {
                throw new Error(`API failed with status ${response.status}`);
            }

            // Save only after a successful API call
            localStorage.setItem("locationApiData", JSON.stringify({ url, ip: currentIp }));
            localStorage.setItem("locationApiTime", JSON.stringify({ time: now }));

            return response.json();
        } catch (error) {
            console.error("Location API Error:", error);
            return null;
        }
    },
    // Permanent (hard) delete of the selected IP log rows
    deleteIpLogs: async (ids) => {
        const response = await authFetch(`${API_BASE_URL}/location/ip-logs`, {
            method: 'DELETE',
            headers: { 'Content-Type': 'application/json', 'accept': 'text/plain' },
            body: JSON.stringify(ids)
        });
        return parseJson(response);
    },
    getIpLogs: async (page = 1, pageSize = 20, search = '', deviceType = '') => {
        const response = await authFetch(`${API_BASE_URL}/location/ip-logs?${listQuery(page, pageSize, { search, deviceType })}`, {
            method: 'GET',
            headers: { 'accept': 'text/plain' }
        });
        return parseJson(response);
    }
};

