// Visitor IP + location, looked up in the browser via ipwho.is (free, HTTPS, CORS-enabled).
// The free ip-api.com can't be used here: it has no HTTPS ("SSL unavailable for this endpoint")
// and browsers block HTTP calls from this HTTPS site.
//
// The result is sent to our API by the visitor logger and the cookie-consent record. It is cached
// for 10 minutes and concurrent callers share one request. Never throws: returns null on failure
// (ad-blocker, offline, provider down) so the page is never affected.

const CACHE_KEY = 'visitorGeo';
const CACHE_MS = 10 * 60 * 1000; // 10 minutes
let inFlight = null;

const readCache = () => {
    try {
        const cached = JSON.parse(localStorage.getItem(CACHE_KEY) || 'null');
        if (cached && cached.data && Date.now() - cached.time < CACHE_MS) return cached.data;
    } catch {
        localStorage.removeItem(CACHE_KEY);
    }
    return null;
};

const normalise = (r) => ({
    ip: r.ip || null,
    country: r.country || null,
    countryCode: r.country_code || null,
    region: r.region || null,
    city: r.city || null,
    timezone: (r.timezone && r.timezone.id) || null,
    isp: (r.connection && (r.connection.isp || r.connection.org)) || null,
});

export async function getVisitorGeo() {
    const cached = readCache();
    if (cached) return cached;
    if (inFlight) return inFlight;

    inFlight = (async () => {
        try {
            const response = await fetch('https://ipwho.is/');
            if (!response.ok) throw new Error(`ipwho.is responded ${response.status}`);
            const result = await response.json();
            if (!result || result.success !== true) throw new Error(result?.message || 'ipwho.is lookup failed');

            const data = normalise(result);
            try {
                localStorage.setItem(CACHE_KEY, JSON.stringify({ data, time: Date.now() }));
            } catch {
                // storage full/blocked: still return the data
            }
            return data;
        } catch (error) {
            console.error('Visitor location lookup failed:', error);
            return null;
        } finally {
            inFlight = null;
        }
    })();
    return inFlight;
}
