import React, { useEffect, useState } from 'react';
import { jobApi } from '../services/api';
import { useScraperRuns } from '../context/ScraperRunsContext';
import { Rocket, Loader2, CheckCircle2, XCircle, Mail, Clock, Square, Ban, ShieldAlert } from 'lucide-react';

const SCRAPERS = [
    { key: 'indeed', label: 'Indeed', color: '#2557a7', action: jobApi.indeedJob },
    { key: 'linkedin', label: 'LinkedIn', color: '#0a66c2', action: jobApi.linkedInJob },
    { key: 'naukri', label: 'Naukri', color: '#4a90d9', action: jobApi.naukriJob },
    { key: 'apna', label: 'Apna', color: '#6c3ef5', action: jobApi.apnaJob },
    { key: 'glassdoor', label: 'Glassdoor', color: '#0caa41', action: jobApi.glassdoorJob },
    { key: 'foundit', label: 'Foundit', color: '#f26522', action: jobApi.founditJob },
    { key: 'internshala', label: 'Internshala', color: '#00abaa', action: jobApi.internshalaJob },
    { key: 'shine', label: 'Shine', color: '#f5a623', action: jobApi.shineJob },
    { key: 'freshersworld', label: 'Freshersworld', color: '#e91e63', action: jobApi.freshersworldJob },
    { key: 'hirect', label: 'Hirect', color: '#7c4dff', action: jobApi.hirectJob },
];

const formatTime = (date) => {
    if (!date) return '';
    const d = date instanceof Date ? date : new Date(date);
    return d.toLocaleString('en-IN', { day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit', second: '2-digit' });
};

const formatElapsed = (from, now) => {
    if (!from) return '';
    const secs = Math.max(0, Math.floor((now - from.getTime()) / 1000));
    const m = Math.floor(secs / 60);
    const s = secs % 60;
    return m > 0 ? `${m}m ${String(s).padStart(2, '0')}s` : `${s}s`;
};

// Live progress while a scraper runs: a bar for searches completed (query x location
// combinations) and a running count of jobs collected so far.
function ScraperProgress({ state }) {
    const total = state.searchesTotal || 0;
    const done = Math.min(state.searchesDone || 0, total);
    const percent = total > 0 ? Math.round((done / total) * 100) : 0;
    const preparing = total === 0;

    return (
        <div className="scraper-progress" aria-live="polite">
            <div className="scraper-progress-head">
                <span className="scraper-progress-jobs">
                    <strong>{state.jobsFound || 0}</strong> job{state.jobsFound === 1 ? '' : 's'} found
                </span>
                <span className="scraper-progress-percent">{preparing ? 'Starting…' : `${percent}%`}</span>
            </div>
            <div
                className={`scraper-progress-track ${preparing ? 'is-indeterminate' : ''}`}
                role="progressbar"
                aria-label="Scraper progress"
                aria-valuemin={0}
                aria-valuemax={100}
                aria-valuenow={preparing ? undefined : percent}
            >
                <div className="scraper-progress-fill" style={{ width: preparing ? undefined : `${Math.max(percent, 3)}%` }} />
            </div>
            {!preparing && (
                <div className="scraper-progress-detail" title={state.currentSearch || ''}>
                    Search {Math.min(done + 1, total)} of {total}
                    {state.currentSearch ? ` · ${state.currentSearch}` : ''}
                    {state.currentPage ? ` · page ${state.currentPage}` : ''}
                </div>
            )}
        </div>
    );
}

export default function ScrapersManagement() {
    const { runState, runScraper, cancelScraper, refreshStatus, anyActive, error, clearError } = useScraperRuns();
    const [now, setNow] = useState(Date.now());

    // Load the server's run status on open/refresh, so a running scraper still shows as running
    useEffect(() => {
        refreshStatus();
    }, [refreshStatus]);

    // Tick the elapsed-time label while something runs
    useEffect(() => {
        if (!anyActive) return;
        const timer = setInterval(() => setNow(Date.now()), 1000);
        return () => clearInterval(timer);
    }, [anyActive]);

    const runningScraper = SCRAPERS.find(s => ['running', 'cancelling'].includes(runState[s.key]?.status));

    const handleCancel = (scraper) => {
        if (window.confirm(`Cancel the ${scraper.label} scraper? Jobs collected so far will still be saved.`)) {
            cancelScraper(scraper);
        }
    };

    return (
        <section className="container admin-container">
            <div className="page-header">
                <div className="page-icon">
                    <Rocket size={20} />
                </div>
                <h2>Job Scrapers</h2>
            </div>

            <p style={{ color: 'var(--text-secondary)', fontSize: '14px', marginBottom: '16px', maxWidth: '720px' }}>
                Trigger a scraper on demand. Each run launches a real browser session and can take a
                minute or more per source. Runs continue on the server, so you can refresh or leave this
                page; the status stays here until the run completes or you cancel it. One scraper runs at a time.
                When new jobs are found, an email alert is sent to the admin inbox (if enabled).
            </p>

            {error && (
                <div className="scraper-alert" role="alert">
                    <XCircle size={16} />
                    <span>{error}</span>
                    <button type="button" className="link-btn" onClick={clearError} aria-label="Dismiss">Dismiss</button>
                </div>
            )}

            <div className="scraper-grid">
                {SCRAPERS.map(scraper => {
                    const state = runState[scraper.key] || { status: 'idle' };
                    const isRunning = state.status === 'running';
                    const isCancelling = state.status === 'cancelling';
                    const isActive = isRunning || isCancelling;
                    const blockedByOther = !!runningScraper && runningScraper.key !== scraper.key;

                    return (
                        <div className={`scraper-card ${isActive ? 'scraper-card-active' : ''}`} key={scraper.key}>
                            <div className="scraper-card-top">
                                <span className="scraper-dot" style={{ background: scraper.color }} />
                                <h3>{scraper.label}</h3>
                            </div>

                            {isActive ? (
                                <div className="scraper-actions">
                                    <button className="apply-btn" disabled style={{ flex: 1 }}>
                                        <Loader2 size={16} className="spin" />
                                        {isCancelling ? 'Cancelling...' : 'Running...'}
                                    </button>
                                    <button
                                        type="button"
                                        className="btn-secondary scraper-cancel-btn"
                                        onClick={() => handleCancel(scraper)}
                                        disabled={isCancelling}
                                        title={`Cancel ${scraper.label}`}
                                    >
                                        <Square size={14} /> Cancel
                                    </button>
                                </div>
                            ) : (
                                <button
                                    className="apply-btn"
                                    onClick={() => runScraper(scraper)}
                                    disabled={blockedByOther}
                                    title={blockedByOther ? `${runningScraper.label} is running` : `Run ${scraper.label}`}
                                    style={{ width: '100%' }}
                                >
                                    <Rocket size={16} /> Run Now
                                </button>
                            )}

                            {isActive && state.awaitingVerification && (
                                <div className="scraper-verify-notice" role="status">
                                    <ShieldAlert size={16} />
                                    <span>
                                        <strong>Human verification needed.</strong> Solve the captcha in the {scraper.label} browser
                                        window on the server. The run continues automatically (waits up to 3 min).
                                    </span>
                                </div>
                            )}

                            {isActive && (
                                <ScraperProgress state={state} />
                            )}

                            {isActive && (
                                <div className="scraper-result scraper-result-muted">
                                    <Clock size={12} />
                                    <span>
                                        Started {formatTime(state.startedAt)} · {formatElapsed(state.startedAt, now)}
                                        {state.startedBy ? ` · by ${state.startedBy}` : ''}
                                    </span>
                                </div>
                            )}

                            {!isActive && state.status === 'success' && (
                                <div className="scraper-result scraper-result-success">
                                    <CheckCircle2 size={14} />
                                    <span>{state.message}{typeof state.count === 'number' ? ` (${state.count})` : ''}</span>
                                </div>
                            )}

                            {!isActive && state.status === 'error' && (
                                <div className="scraper-result scraper-result-error">
                                    <XCircle size={14} />
                                    <span>{state.message}</span>
                                </div>
                            )}

                            {!isActive && state.status === 'cancelled' && (
                                <div className="scraper-result scraper-result-muted">
                                    <Ban size={14} />
                                    <span>{state.message}</span>
                                </div>
                            )}

                            {!isActive && state.finishedAt && (
                                <div className="scraper-result scraper-result-muted">
                                    <Clock size={12} />
                                    <span>Last run: {formatTime(state.finishedAt)}</span>
                                </div>
                            )}

                            {!isActive && state.status === 'success' && typeof state.count === 'number' && state.count > 0 && (
                                <div className="scraper-result scraper-result-muted">
                                    <Mail size={12} />
                                    <span>Admin notified by email</span>
                                </div>
                            )}
                        </div>
                    );
                })}
            </div>
        </section>
    );
}
