import React, { useState, useEffect } from 'react';
import { HashRouter as Router, Routes, Route, Link, Navigate, useLocation } from 'react-router-dom';
import { LayoutDashboard, LogIn } from 'lucide-react';
import Home from './pages/Home';
import AdminDashboard from './pages/AdminDashboard';
import BriefcaseIcon from './components/BriefcaseIcon';
import Sidebar from './components/Sidebar'; // ✅ Make sure to import the Sidebar
import Footer from './components/Footer';
import Login from './pages/Login';
import ForgetPassword from './pages/ForgetPassword';
import ContactUs from './pages/ContactUs';
import PrivacyPolicy from './pages/PrivacyPolicy';
import './App.css';
import { jobApi } from '../src/services/api';
import ApiDocs from './pages/ApiDocs';
import MasterManagement from './pages/MasterManagement';
import MasterDetailsManagement from './pages/MasterDetailsManagement';
import ChangePasswordModal from './components/ChangePasswordModal';
import AdminNavbar from './components/AdminNavbar';
import JobsManagement from './pages/JobsManagement';
import ContactUsManagement from './pages/ContactUsManagement';
import IpLogsManagement from './pages/IpLogsManagement';
import ErrorLogsManagement from './pages/ErrorLogsManagement';
import SecuritySettings from './pages/SecuritySettings';
import ScrapersManagement from './pages/ScrapersManagement';
import AdminUsersManagement from './pages/AdminUsersManagement';
import SqlConsole from './pages/SqlConsole';
import NotificationsPage from './pages/NotificationsPage';
import CookieBanner from './components/CookieBanner';
import CookieConsentManagement from './pages/CookieConsentManagement';
import { ScraperRunsProvider } from './context/ScraperRunsContext';

const ProtectedRoute = ({ children }) => {
    const token = localStorage.getItem("token");

    if (!token) {
        return <Navigate to="/login" replace />;
    }

    return children;
};

// ✅ Naya Layout Wrapper Component banaya gaya hai jisme useLocation() chal sake
const AppLayout = ({ isAuthenticated, setIsAuthenticated, handleLogout, theme, toggleTheme }) => {
    const location = useLocation();
    const isAdminRoute = location.pathname.startsWith('/admin');
    
    // Sidebar toggle state
    const [isSidebarOpen, setIsSidebarOpen] = useState(() => {
        try {
            const savedState = localStorage.getItem('isSidebarOpen');
            // No saved preference: start closed on phones, where the sidebar is a full-screen overlay
            return savedState !== null ? JSON.parse(savedState) : window.innerWidth > 768;
        } catch (e) {
            return window.innerWidth > 768;
        }
    });

    useEffect(() => {
        localStorage.setItem('isSidebarOpen', JSON.stringify(isSidebarOpen));
    }, [isSidebarOpen]);

    const toggleSidebar = () => setIsSidebarOpen(prev => !prev);

    return (
        <div className={isAdminRoute ? "admin-layout-wrapper" : ""}>
            <ChangePasswordModal />
            {/* --- ADMIN LAYOUT: Left Sidebar (Sirf tab dikhega jab user /admin par hoga) --- */}
            {isAdminRoute && isAuthenticated && (
                <>
                    <Sidebar
                        handleLogout={handleLogout}
                        isOpen={isSidebarOpen}
                        toggleSidebar={toggleSidebar}
                    />
                    {/* Tap-outside-to-close backdrop; only visible on mobile widths via CSS */}
                    {isSidebarOpen && (
                        <div className="sidebar-backdrop" onClick={() => setIsSidebarOpen(false)} />
                    )}
                </>
            )}

            <div className={isAdminRoute ? "admin-content-wrapper" : "public-content-wrapper"} style={isAdminRoute ? { flex: 1, display: 'flex', flexDirection: 'column', overflow: 'hidden' } : {}}>
                {/* --- PUBLIC LAYOUT: Top Navbar (Admin pages par hide ho jayega) --- */}
                {!isAdminRoute && (
                    <nav className="navbar">
                        <Link to="/" className="brand-logo">
                            <BriefcaseIcon className="brand-icon" />
                            <div className="brand-text">
                                <span className="brand-title">JobPortal</span>
                                <span className="brand-subtitle">Find Your Dream Job</span>
                            </div>
                        </Link>

                        {/* Portal container for the scrolled search box */}
                        <div id="navbar-search-portal" className="navbar-search-portal"></div>

                        <ul>
                            <li>
                                <button onClick={toggleTheme} className="theme-toggle-btn" title="Toggle Theme" aria-label={theme === 'light' ? 'Switch to dark mode' : 'Switch to light mode'}>
                                    {theme === 'light' ? '🌙' : '☀️'}
                                </button>
                            </li>
                            {isAuthenticated ? (
                                <>
                                    {/* Agar logged in hai, to Dashboard jane ka link dikhaye */}
                                    <li><Link to="/admin" title="Admin Dashboard" aria-label="Admin Dashboard"><LayoutDashboard size={20} /></Link></li>
                                    <li>
                                        <button onClick={handleLogout} className="logout-btn">
                                            Logout
                                        </button>
                                    </li>
                                </>
                            ) : (
                                <li><Link to="/login" className="login-icon-link" title="Admin Login"><LogIn size={20} /></Link></li>
                            )}
                        </ul>
                    </nav>
                )}

                {/* --- ADMIN LAYOUT: Top Navbar --- */}
                {isAdminRoute && isAuthenticated && (
                    <AdminNavbar handleLogout={handleLogout} theme={theme} toggleTheme={toggleTheme} toggleSidebar={toggleSidebar} isSidebarOpen={isSidebarOpen} />
                )}

                {/* --- MAIN CONTENT AREA --- */}
                <main className={isAdminRoute ? "admin-main-content" : ""}>
                    <Routes>
                    <Route path="/" element={<Home />} />
                    <Route path="/login" element={<Login setIsAuthenticated={setIsAuthenticated} />} />
                    <Route path="/forget" element={<ForgetPassword />} />
                    <Route path="/contact-us" element={<ContactUs />} />
                    <Route path="/privacy-policy" element={<PrivacyPolicy />} />

                    {/* ✅ ONLY ONE ADMIN ROUTE */}
                    <Route path="/admin" element={<ProtectedRoute><AdminDashboard /></ProtectedRoute>} />
                    
                    {/* ✅ Jobs Management Route */}
                    <Route path="/admin/jobs" element={<ProtectedRoute><JobsManagement /></ProtectedRoute>} />

                    {/* ✅ Job Scrapers Route */}
                    <Route path="/admin/scrapers" element={<ProtectedRoute><ScrapersManagement /></ProtectedRoute>} />

                    {/* ✅ Notifications Route */}
                    <Route path="/admin/notifications" element={<ProtectedRoute><NotificationsPage /></ProtectedRoute>} />

                    {/* ✅ Settings: Admin (users) */}
                    <Route path="/admin/settings/users" element={<ProtectedRoute><AdminUsersManagement /></ProtectedRoute>} />

                    {/* ✅ Settings: Two-Factor Auth */}
                    <Route path="/admin/settings/security" element={<ProtectedRoute><SecuritySettings /></ProtectedRoute>} />

                    {/* ✅ Settings: SQL Console */}
                    <Route path="/admin/settings/sql-console" element={<ProtectedRoute><SqlConsole /></ProtectedRoute>} />

                    {/* ✅ Master Management Route */}
                    <Route path="/admin/master" element={<ProtectedRoute><MasterManagement /></ProtectedRoute>} />
                    
                    {/* ✅ Master Details Management Route */}
                    <Route path="/admin/master-details" element={<ProtectedRoute><MasterDetailsManagement /></ProtectedRoute>} />

                    {/* ✅ Contact Us Management Route */}
                    <Route path="/admin/contact-us" element={<ProtectedRoute><ContactUsManagement /></ProtectedRoute>} />

                    {/* ✅ IP Logs Management Route */}
                    <Route path="/admin/ip-logs" element={<ProtectedRoute><IpLogsManagement /></ProtectedRoute>} />

                    {/* ✅ Error Logs Management Route */}
                    <Route path="/admin/error-logs" element={<ProtectedRoute><ErrorLogsManagement /></ProtectedRoute>} />

                    {/* ✅ Cookie Consent records */}
                    <Route path="/admin/cookie-consent" element={<ProtectedRoute><CookieConsentManagement /></ProtectedRoute>} />

                    {/* ✅ NEW API Docs Route */}
                    <Route
                        path="/admin/api-docs"
                        element={
                            <ProtectedRoute>
                                <ApiDocs />
                            </ProtectedRoute>
                        }
                    />
                </Routes>
                </main>
                {!isAdminRoute && <Footer />}
                {!isAdminRoute && <CookieBanner />}
            </div>
        </div>
    );
};

function App() {
    // Read the token synchronously so a refresh on /admin doesn't render one frame without the Sidebar/AdminNavbar
    const [isAuthenticated, setIsAuthenticated] = useState(() => !!localStorage.getItem("token"));
    const [theme, setTheme] = useState(localStorage.getItem('theme') || 'light');

    // ✅ Apply theme to root document
    useEffect(() => {
        document.documentElement.setAttribute('data-theme', theme);
        localStorage.setItem('theme', theme);
    }, [theme]);

    const toggleTheme = () => {
        setTheme(prev => prev === 'light' ? 'dark' : 'light');
    };

    // ✅ Keep auth state in sync when the session is cleared elsewhere
    // (failed token refresh in api.js, or logout in another tab)
    useEffect(() => {
        const syncAuth = () => setIsAuthenticated(!!localStorage.getItem("token"));
        window.addEventListener("auth-logout", syncAuth);
        window.addEventListener("storage", syncAuth);
        return () => {
            window.removeEventListener("auth-logout", syncAuth);
            window.removeEventListener("storage", syncAuth);
        };
    }, []);

    const handleLogout = () => {
        // Grab the tokens before clearing — the logout call needs them
        const token = localStorage.getItem("token");
        const refreshToken = localStorage.getItem("refreshToken");

        // ✅ clear frontend auth first, so the UI logs out instantly even if the API is slow
        localStorage.removeItem("token");
        localStorage.removeItem("refreshToken");
        localStorage.removeItem("username");
        localStorage.removeItem("role");

        setIsAuthenticated(false);
        // Let session-scoped state (e.g. scraper run status) clear itself
        window.dispatchEvent(new Event("auth-logout"));
        window.location.hash = "#/login";

        jobApi.logoutApi(token, refreshToken).catch(error => {
            console.error("Logout API error:", error);
        });
    };

    return (
        <Router>
            {/* AppLayout ko yahan call kiya gaya hai */}
            <ScraperRunsProvider>
                <AppLayout
                    isAuthenticated={isAuthenticated}
                    setIsAuthenticated={setIsAuthenticated}
                    handleLogout={handleLogout}
                    theme={theme}
                    toggleTheme={toggleTheme}
                />
            </ScraperRunsProvider>
        </Router>
    );
}

export default App;