import React, { useEffect, useState } from 'react';
import { jobApi, usersApi } from '../services/api';
import { ShieldCheck, ShieldOff, KeyRound, Copy, CheckCircle2, Loader2 } from 'lucide-react';

export default function SecuritySettings() {
    const [loading, setLoading] = useState(true);
    const [isTotpEnabled, setIsTotpEnabled] = useState(false);

    const [setupData, setSetupData] = useState(null); // { otpAuthUri, qrCodeBase64 }
    const [settingUp, setSettingUp] = useState(false);
    const [enableCode, setEnableCode] = useState('');
    const [disableCode, setDisableCode] = useState('');
    const [showDisableForm, setShowDisableForm] = useState(false);
    const [copied, setCopied] = useState(false);

    const [error, setError] = useState('');
    // If the status can't be loaded we must not render "2FA Disabled" — clicking
    // "Set Up" on that screen would replace a working authenticator
    const [loadError, setLoadError] = useState('');
    const [message, setMessage] = useState('');
    const [submitting, setSubmitting] = useState(false);

    const loadStatus = async () => {
        setLoading(true);
        try {
            const result = await usersApi.getMe();
            if (result?.statusCode === 200 && result?.data) {
                setIsTotpEnabled(!!result.data.isTotpEnabled);
                setLoadError('');
            } else {
                setLoadError('Could not load your 2FA status. Reload the page to try again.');
            }
        } catch (err) {
            console.error("Error loading security status:", err);
            setLoadError('Could not load your 2FA status. Reload the page to try again.');
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        loadStatus();
    }, []);

    const startSetup = async () => {
        setSettingUp(true);
        setError('');
        setMessage('');
        try {
            const result = await jobApi.setup2FaApi();
            if (result?.statusCode === 200 && result?.data) {
                setSetupData(result.data);
            } else {
                setError(result?.message || 'Failed to start 2FA setup.');
            }
        } catch (err) {
            console.error("Error starting 2FA setup:", err);
            setError('Server error. Please try again.');
        } finally {
            setSettingUp(false);
        }
    };

    const handleEnable = async (e) => {
        e.preventDefault();
        if (submitting) return;
        if (enableCode.length !== 6) {
            setError('Enter the 6-digit code from your authenticator app.');
            return;
        }
        setSubmitting(true);
        setError('');
        setMessage('');
        try {
            const result = await jobApi.enable2FaApi(enableCode);
            if (result?.statusCode === 200) {
                setMessage(result.message || 'Two-factor authentication enabled.');
                setIsTotpEnabled(true);
                setSetupData(null);
                setEnableCode('');
            } else {
                setError(result?.message || 'Invalid code. Please try again.');
            }
        } catch (err) {
            console.error("Error enabling 2FA:", err);
            setError('Server error. Please try again.');
        } finally {
            setSubmitting(false);
        }
    };

    const handleDisable = async (e) => {
        e.preventDefault();
        if (submitting) return;
        if (disableCode.length !== 6) {
            setError('Enter the 6-digit code from your authenticator app.');
            return;
        }
        setSubmitting(true);
        setError('');
        setMessage('');
        try {
            const result = await jobApi.disable2FaApi(disableCode);
            if (result?.statusCode === 200) {
                setMessage(result.message || 'Two-factor authentication disabled.');
                setIsTotpEnabled(false);
                setShowDisableForm(false);
                setDisableCode('');
            } else {
                setError(result?.message || 'Invalid code. Please try again.');
            }
        } catch (err) {
            console.error("Error disabling 2FA:", err);
            setError('Server error. Please try again.');
        } finally {
            setSubmitting(false);
        }
    };

    // Authenticator apps expect the base32 secret for manual entry, not the full otpauth:// URI
    const setupKey = (() => {
        try {
            return new URL(setupData?.otpAuthUri).searchParams.get('secret') || setupData?.otpAuthUri;
        } catch {
            return setupData?.otpAuthUri;
        }
    })();

    const handleCopyUri = () => {
        if (!setupKey) return;
        navigator.clipboard.writeText(setupKey).then(() => {
            setCopied(true);
            setTimeout(() => setCopied(false), 2000);
        }).catch(() => setError('Could not copy. Select the key and copy it manually.'));
    };

    const cancelSetup = () => {
        setSetupData(null);
        setEnableCode('');
        setError('');
    };

    if (loading) {
        return <div className="container admin-container" style={{ textAlign: 'center', padding: '50px' }}>Loading security settings...</div>;
    }

    if (loadError) {
        return <div className="container admin-container" style={{ textAlign: 'center', padding: '50px' }}><p className="error-text">{loadError}</p></div>;
    }

    return (
        <section className="container admin-container">
            <div className="page-header">
                <div className="page-icon">
                    <KeyRound size={20} />
                </div>
                <h2>Security</h2>
            </div>

            {error && <p className="error-text">{error}</p>}
            {message && (
                <p style={{ color: 'var(--success)', marginBottom: '15px', fontWeight: '500', display: 'flex', alignItems: 'center', gap: '6px' }}>
                    <CheckCircle2 size={16} /> {message}
                </p>
            )}

            <div className="security-card">
                <div className="security-card-header">
                    <div className={`status-badge ${isTotpEnabled ? 'status-badge-success' : 'status-badge-muted'}`}>
                        {isTotpEnabled ? <ShieldCheck size={16} /> : <ShieldOff size={16} />}
                        <span>{isTotpEnabled ? '2FA Enabled' : '2FA Disabled'}</span>
                    </div>
                </div>

                <h3 style={{ marginTop: '16px' }}>Two-Factor Authentication (TOTP)</h3>
                <p style={{ color: 'var(--text-secondary)', fontSize: '14px', maxWidth: '560px' }}>
                    Add an extra layer of security to your account. Once enabled, you'll need a 6-digit
                    code from an authenticator app (Google Authenticator, Authy, etc.) every time you log in.
                </p>

                {/* --- Disabled state: either idle or mid-setup --- */}
                {!isTotpEnabled && !setupData && (
                    <button className="apply-btn" onClick={startSetup} disabled={settingUp} style={{ marginTop: '16px' }}>
                        {settingUp ? <><Loader2 size={16} className="spin" style={{ marginRight: '8px' }} />Preparing...</> : 'Set Up Authenticator'}
                    </button>
                )}

                {!isTotpEnabled && setupData && (
                    <div className="setup-2fa-panel">
                        <div className="qr-code-box">
                            <img
                                src={`data:image/png;base64,${setupData.qrCodeBase64}`}
                                alt="Scan this QR code with your authenticator app"
                            />
                        </div>

                        <div style={{ flex: 1, minWidth: 'min(260px, 100%)' }}>
                            <p style={{ fontSize: '14px', color: 'var(--text-secondary)' }}>
                                1. Scan the QR code with your authenticator app.<br />
                                2. Or paste this setup key manually:
                            </p>
                            <div className="copy-field">
                                <code>{setupKey}</code>
                                <button type="button" onClick={handleCopyUri} title="Copy" aria-label="Copy setup key">
                                    {copied ? <CheckCircle2 size={16} /> : <Copy size={16} />}
                                </button>
                            </div>

                            <form onSubmit={handleEnable} className="admin-form" style={{ marginTop: '16px' }}>
                                <input
                                    type="text"
                                    inputMode="numeric"
                                    className="otp-input"
                                    placeholder="000000"
                                    aria-label="Authentication code"
                                    maxLength={6}
                                    value={enableCode}
                                    onChange={(e) => setEnableCode(e.target.value.replace(/\D/g, '').slice(0, 6))}
                                    required
                                />
                                <div style={{ display: 'flex', gap: '10px' }}>
                                    <button type="submit" className="apply-btn" disabled={submitting}>
                                        {submitting ? "Verifying..." : "Verify & Enable"}
                                    </button>
                                    <button type="button" className="link-btn" onClick={cancelSetup}>
                                        Cancel
                                    </button>
                                </div>
                            </form>
                        </div>
                    </div>
                )}

                {/* --- Enabled state --- */}
                {isTotpEnabled && !showDisableForm && (
                    <button className="apply-btn btn-danger" style={{ marginTop: '16px' }} onClick={() => setShowDisableForm(true)}>
                        Disable 2FA
                    </button>
                )}

                {isTotpEnabled && showDisableForm && (
                    <form onSubmit={handleDisable} className="admin-form" style={{ maxWidth: '320px', marginTop: '16px' }}>
                        <p style={{ fontSize: '14px', color: 'var(--text-secondary)', margin: 0 }}>
                            Enter a current code from your authenticator app to confirm disabling 2FA.
                        </p>
                        <input
                            type="text"
                            inputMode="numeric"
                            className="otp-input"
                            placeholder="000000"
                            aria-label="Authentication code"
                            maxLength={6}
                            value={disableCode}
                            onChange={(e) => setDisableCode(e.target.value.replace(/\D/g, '').slice(0, 6))}
                            required
                        />
                        <div style={{ display: 'flex', gap: '10px' }}>
                            <button type="submit" className="apply-btn btn-danger" disabled={submitting}>
                                {submitting ? "Disabling..." : "Confirm Disable"}
                            </button>
                            <button type="button" className="link-btn" onClick={() => { setShowDisableForm(false); setDisableCode(''); }}>
                                Cancel
                            </button>
                        </div>
                    </form>
                )}
            </div>
        </section>
    );
}
