import React, { createContext, useCallback, useContext, useEffect, useRef, useState } from 'react';
import { jobApi } from '../services/api';

// Scraper runs live on the server (ScraperRunService): starting one returns immediately and the
// run continues in the background. This provider mirrors the server's status, so a page refresh,
// a menu switch or a second admin all see the same "running" state until the run completes or
// is cancelled. It polls only while something is running.
const ScraperRunsContext = createContext(null);
const POLL_MS = 2000;

const toState = (statuses) => {
    const map = {};
    (statuses || []).forEach(s => {
        map[s.key] = {
            status: s.status,
            message: s.message,
            count: typeof s.count === 'number' ? s.count : undefined,
            startedAt: s.startedAt ? new Date(s.startedAt) : null,
            finishedAt: s.finishedAt ? new Date(s.finishedAt) : null,
            startedBy: s.startedBy,
            // live progress while running
            searchesDone: s.searchesDone || 0,
            searchesTotal: s.searchesTotal || 0,
            jobsFound: s.jobsFound || 0,
            currentSearch: s.currentSearch || null,
            currentPage: s.currentPage || null,
            awaitingVerification: !!s.awaitingVerification
        };
    });
    return map;
};

export function ScraperRunsProvider({ children }) {
    const [runState, setRunState] = useState({});
    const [error, setError] = useState('');
    const pollTimer = useRef(null);

    const anyActive = Object.values(runState).some(s => s.status === 'running' || s.status === 'cancelling');

    const refreshStatus = useCallback(async () => {
        // Never call the admin API without a session (it would bounce the visitor to /login)
        if (!localStorage.getItem('token')) return;
        try {
            const result = await jobApi.scraperStatus();
            if (result?.statusCode === 200) {
                setRunState(toState(result.data));
            }
        } catch (err) {
            console.error('Error loading scraper status:', err);
        }
    }, []);

    // Keep polling while a run is active (also after navigating away from the page)
    useEffect(() => {
        clearTimeout(pollTimer.current);
        if (anyActive) {
            pollTimer.current = setTimeout(refreshStatus, POLL_MS);
        }
        return () => clearTimeout(pollTimer.current);
    }, [anyActive, runState, refreshStatus]);

    const runScraper = useCallback(async (scraper) => {
        setError('');
        try {
            const result = await scraper.action();
            if (result?.statusCode !== 200) {
                setError(result?.message || `Could not start ${scraper.label}.`);
            }
        } catch (err) {
            console.error(`Error starting ${scraper.label} scraper:`, err);
            setError(`Could not start ${scraper.label}. Check the API.`);
        }
        await refreshStatus();
    }, [refreshStatus]);

    const cancelScraper = useCallback(async (scraper) => {
        setError('');
        try {
            const result = await jobApi.cancelScraper(scraper.key);
            if (result?.statusCode !== 200) {
                setError(result?.message || `Could not cancel ${scraper.label}.`);
            }
        } catch (err) {
            console.error(`Error cancelling ${scraper.label} scraper:`, err);
            setError(`Could not cancel ${scraper.label}.`);
        }
        await refreshStatus();
    }, [refreshStatus]);

    // Clear everything on logout
    useEffect(() => {
        const reset = () => { if (!localStorage.getItem('token')) setRunState({}); };
        window.addEventListener('auth-logout', reset);
        window.addEventListener('storage', reset);
        return () => {
            window.removeEventListener('auth-logout', reset);
            window.removeEventListener('storage', reset);
        };
    }, []);

    return (
        <ScraperRunsContext.Provider value={{ runState, runScraper, cancelScraper, refreshStatus, anyActive, error, clearError: () => setError('') }}>
            {children}
        </ScraperRunsContext.Provider>
    );
}

export function useScraperRuns() {
    const ctx = useContext(ScraperRunsContext);
    if (!ctx) {
        throw new Error('useScraperRuns must be used within a ScraperRunsProvider');
    }
    return ctx;
}
