import React, { useState, useEffect } from "react";
import { masterApi } from "../services/api";
import { Database, Eye, Download, ToggleLeft, ToggleRight } from "lucide-react";
import { exportToExcel } from "../utils/exportUtils";
import FilterBar from '../components/FilterBar';
import Pagination from '../components/Pagination';

export default function MasterManagement() {
    const [masters, setMasters] = useState([]);
    const [loading, setLoading] = useState(false);
    const [selectedMasters, setSelectedMasters] = useState([]);

    // Pagination State
    const [rowsPerPage, setRowsPerPage] = useState(20);

    // Filters (client-side: the full list is already loaded)
    const [search, setSearch] = useState("");
    const [statusFilter, setStatusFilter] = useState("");
    const [currentPage, setCurrentPage] = useState(1);

    const [isFormOpen, setIsFormOpen] = useState(false);
    const [editingMaster, setEditingMaster] = useState(null);
    const [viewingMaster, setViewingMaster] = useState(null);
    const [formData, setFormData] = useState({
        id: 0,
        masterName: "",
        description: "",
        status: true,
    });

    useEffect(() => {
        fetchMasters();
    }, []);

    const fetchMasters = async () => {
        setLoading(true);
        try {
            const result = await masterApi.getAll();
            if (result && result.statusCode === 200 && result.data) {
                setMasters(result.data);
                setSelectedMasters([]);
            } else {
                setMasters([]);
            }
        } catch (error) {
            console.error("Error loading masters:", error);
            setMasters([]);
        }
        setLoading(false);
    };

    const handleInputChange = (e) => {
        const { name, value, type, checked } = e.target;
        setFormData({
            ...formData,
            [name]: type === "checkbox" ? checked : value,
        });
    };

    const openCreateForm = () => {
        setEditingMaster(null);
        setFormData({ id: 0, masterName: "", description: "", status: true });
        setIsFormOpen(true);
    };

    const openEditForm = (master) => {
        setEditingMaster(master);
        setFormData({
            id: master.id,
            masterName: master.masterName || "",
            description: master.description || "",
            status: master.status,
        });
        setIsFormOpen(true);
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        try {
            if (editingMaster) {
                const result = await masterApi.update(formData);
                // The API reports failures in the body's statusCode, not the HTTP status
                if (result?.statusCode !== 200) { alert(result?.message || "Request failed."); return; }
            } else {
                const result = await masterApi.insert(formData);
                // The API reports failures in the body's statusCode, not the HTTP status
                if (result?.statusCode !== 200) { alert(result?.message || "Request failed."); return; }
            }
            setIsFormOpen(false);
            fetchMasters();
        } catch (error) {
            console.error("Error saving master", error);
            alert("Failed to save master.");
        }
    };

    const handleDelete = async (id) => {
        if (window.confirm("Are you sure you want to delete this master?")) {
            try {
                const result = await masterApi.delete(id);
                // The API reports failures in the body's statusCode, not the HTTP status
                if (result?.statusCode !== 200) { alert(result?.message || "Request failed."); return; }
                fetchMasters();
            } catch (error) {
                console.error("Error deleting master", error);
                alert("Failed to delete master.");
            }
        }
    };

    const handleToggleStatus = async (master) => {
        if (
            window.confirm(
                `Are you sure you want to change the status to ${master.status ? "Inactive" : "Active"
                }?`,
            )
        ) {
            try {
                const result = await masterApi.updateStatus([master.id], !master.status);
                // The API reports failures in the body's statusCode, not the HTTP status
                if (result?.statusCode !== 200) { alert(result?.message || "Request failed."); return; }
                fetchMasters();
            } catch (error) {
                console.error("Error toggling status", error);
                alert("Failed to change status.");
            }
        }
    };

    const handleDeleteSelected = async () => {
        if (window.confirm(`Are you sure you want to delete ${selectedMasters.length} selected masters?`)) {
            try {
                const result = await masterApi.delete(selectedMasters);
                // The API reports failures in the body's statusCode, not the HTTP status
                if (result?.statusCode !== 200) { alert(result?.message || "Request failed."); return; }
                alert(`Deleted ${selectedMasters.length} masters.`);
                setSelectedMasters([]);
                fetchMasters();
            } catch (error) {
                console.error("Error deleting selected masters", error);
                alert("Failed to delete selected masters.");
            }
        }
    };

    const handleChangeStatusSelected = async (status) => {
        const statusText = status ? "Active" : "Inactive";
        if (window.confirm(`Are you sure you want to change the status of ${selectedMasters.length} masters to ${statusText}?`)) {
            try {
                const result = await masterApi.updateStatus(selectedMasters, status);
                // The API reports failures in the body's statusCode, not the HTTP status
                if (result?.statusCode !== 200) { alert(result?.message || "Request failed."); return; }
                alert(`Status of ${selectedMasters.length} masters changed to ${statusText}.`);
                setSelectedMasters([]);
                fetchMasters();
            } catch (error) {
                console.error("Error changing status", error);
                alert("Failed to change status.");
            }
        }
    };


    const searchTerm = search.trim().toLowerCase();
    const filteredMasters = masters.filter((m) =>
        (!searchTerm
            || (m.masterName || "").toLowerCase().includes(searchTerm)
            || (m.description || "").toLowerCase().includes(searchTerm))
        && (statusFilter === "" || (statusFilter === "active") === !!m.status)
    );
    // Any filter change starts again from page 1 with nothing selected
    const changeFilter = (setter) => (value) => {
        setter(value);
        setCurrentPage(1);
        setSelectedMasters([]);
    };

    // Pagination Logic
    const total = filteredMasters.length;
    const totalPages = Math.ceil(total / rowsPerPage);

    const handleNext = () => {
        if (currentPage < totalPages) {
            setSelectedMasters([]);
            setCurrentPage((prev) => prev + 1);
        }
    };

    const handlePrev = () => {
        if (currentPage > 1) {
            setSelectedMasters([]);
            setCurrentPage((prev) => prev - 1);
        }
    };

    const handleExport = () => {
        exportToExcel(filteredMasters, 'masters');
    };

    const paginatedMasters = filteredMasters.slice(
        (currentPage - 1) * rowsPerPage,
        currentPage * rowsPerPage,
    );

    const handleSelectAll = (e) => {
        if (e.target.checked) {
            const allMasterIds = paginatedMasters.map(m => m.id);
            setSelectedMasters(allMasterIds);
        } else {
            setSelectedMasters([]);
        }
    };

    const handleSelect = (e, masterId) => {
        if (e.target.checked) {
            setSelectedMasters([...selectedMasters, masterId]);
        } else {
            setSelectedMasters(selectedMasters.filter(id => id !== masterId));
        }
    };

    return (
        <section className="container admin-container">
            <div
                className="admin-header"
                style={{
                    display: "flex",
                    justifyContent: "space-between",
                    alignItems: "center",
                    flexWrap: "wrap",
                    gap: "15px",
                }}
            >
                <div className="page-header" style={{ marginBottom: 0 }}>
                    <div className="page-icon">
                        <Database size={20} />
                    </div>
                    <h2>Master Management</h2>
                </div>
                <div
                    style={{
                        display: "flex",
                        alignItems: "center",
                        gap: "15px",
                        flexWrap: "wrap",
                    }}
                >
                    <button
                        className="apply-btn"
                        onClick={openCreateForm}
                        style={{ margin: 0, whiteSpace: "nowrap" }}
                    >
                        + Add New Master
                    </button>
                    <button className="btn-secondary" onClick={handleExport} title="Export to Excel">
                        <Download size={15} />
                        Export
                    </button>
                </div>
            </div>

            <FilterBar
                search={search}
                onSearchChange={changeFilter(setSearch)}
                placeholder="Search master name or description..."
                selects={[{
                    key: "status",
                    label: "Status",
                    value: statusFilter,
                    onChange: changeFilter(setStatusFilter),
                    options: [
                            { value: "", label: "All statuses" },
                            { value: "active", label: "Active" },
                            { value: "inactive", label: "Inactive" },
                        ],
                }]}
                onClear={() => { setSearch(""); setStatusFilter(""); setCurrentPage(1); setSelectedMasters([]); }}
            />

            {selectedMasters.length > 0 && (
                <div className="bulk-actions" style={{ display: 'flex', gap: '10px', alignItems: 'center', padding: '10px', background: 'var(--input-bg)', border: '1px solid var(--input-border)', borderRadius: '8px', marginBottom: '5px' }}>
                    <span style={{ fontWeight: 'bold', color: 'var(--text-primary)' }}>{selectedMasters.length} selected</span>
                    <button onClick={handleDeleteSelected} className="icon-btn btn-danger" title="Delete selected" aria-label="Delete selected">
                        {/* Trash/Delete Icon */}
                        <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                            <polyline points="3 6 5 6 21 6"></polyline>
                            <path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"></path>
                            <line x1="10" y1="11" x2="10" y2="17"></line>
                            <line x1="14" y1="11" x2="14" y2="17"></line>
                        </svg>
                    </button>
                    <button onClick={() => handleChangeStatusSelected(true)} className="apply-btn btn-success" style={{ whiteSpace: 'nowrap', display: 'flex', alignItems: 'center', gap: '5px' }}>
                        <ToggleRight size={18} />
                        <span>Activate</span>
                    </button>
                    <button onClick={() => handleChangeStatusSelected(false)} className="apply-btn btn-warning" style={{ whiteSpace: 'nowrap', display: 'flex', alignItems: 'center', gap: '5px' }}>
                        <ToggleLeft size={18} />
                        <span>Deactivate</span>
                    </button>
                </div>
            )}

            <div className="table-wrapper">
                {loading ? (
                    <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>
                ) : (
                    <table>
                        <thead>
                            <tr>
                                <th style={{ width: '50px' }}>
                                    <input
                                        type="checkbox"
                                        checked={selectedMasters.length === paginatedMasters.length && paginatedMasters.length > 0}
                                        onChange={handleSelectAll}
                                        style={{ verticalAlign: 'middle' }}
                                    />
                                </th>
                                <th>ID</th>
                                <th>Name</th>
                                <th>Description</th>
                                <th>Status</th>
                                <th>Created On</th>
                                <th className="col-actions">Actions</th>
                            </tr>
                        </thead>
                        <tbody>
                            {paginatedMasters.length === 0 ? (
                                <tr>
                                    <td colSpan="7" style={{ textAlign: "center" }}>
                                        No masters found.
                                    </td>
                                </tr>
                            ) : (
                                paginatedMasters.map((master) => (
                                    <tr key={master.id} className={selectedMasters.includes(master.id) ? 'selected-row' : ''}>
                                        <td>
                                            <input
                                                type="checkbox"
                                                checked={selectedMasters.includes(master.id)}
                                                onChange={(e) => handleSelect(e, master.id)}
                                                style={{ verticalAlign: 'middle' }}
                                            />
                                        </td>
                                        <td>{master.id}</td>
                                        <td>{master.masterName}</td>
                                        <td>
                                            <div className="truncate-text" title={master.description}>
                                                {master.description || "-"}
                                            </div>
                                        </td>
                                        <td>{master.status ? "Active" : "Inactive"}</td>
                                        <td>
                                            {master.createdOn
                                                ? new Date(master.createdOn).toLocaleString()
                                                : "-"}
                                        </td>
                                        <td>
                                            <div className="action-buttons">
                                                <button
                                                    className="icon-btn view-btn"
                                                    onClick={() => setViewingMaster(master)}
                                                    title="View"
                                                >
                                                    <Eye size={18} />
                                                </button>
                                                <button
                                                    className={`icon-btn ${master.status ? "active-btn" : "inactive-btn"}`}
                                                    onClick={() => handleToggleStatus(master)}
                                                    title={master.status ? "Deactivate" : "Activate"}
                                                >
                                                    {master.status ? (
                                                        <svg
                                                            xmlns="http://www.w3.org/2000/svg"
                                                            width="18"
                                                            height="18"
                                                            viewBox="0 0 24 24"
                                                            fill="none"
                                                            stroke="currentColor"
                                                            strokeWidth="2"
                                                            strokeLinecap="round"
                                                            strokeLinejoin="round"
                                                        >
                                                            <rect width="20" height="14" x="2" y="5" rx="7" />
                                                            <circle cx="16" cy="12" r="3" />
                                                        </svg>
                                                    ) : (
                                                        <svg
                                                            xmlns="http://www.w3.org/2000/svg"
                                                            width="18"
                                                            height="18"
                                                            viewBox="0 0 24 24"
                                                            fill="none"
                                                            stroke="currentColor"
                                                            strokeWidth="2"
                                                            strokeLinecap="round"
                                                            strokeLinejoin="round"
                                                        >
                                                            <rect width="20" height="14" x="2" y="5" rx="7" />
                                                            <circle cx="8" cy="12" r="3" />
                                                        </svg>
                                                    )}
                                                </button>
                                                <button
                                                    className="icon-btn edit-btn"
                                                    onClick={() => openEditForm(master)}
                                                    title="Edit"
                                                >
                                                    <svg
                                                        xmlns="http://www.w3.org/2000/svg"
                                                        width="18"
                                                        height="18"
                                                        viewBox="0 0 24 24"
                                                        fill="none"
                                                        stroke="currentColor"
                                                        strokeWidth="2"
                                                        strokeLinecap="round"
                                                        strokeLinejoin="round"
                                                    >
                                                        <path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"></path>
                                                        <path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"></path>
                                                    </svg>
                                                </button>
                                                <button
                                                    className="icon-btn delete-btn"
                                                    onClick={() => handleDelete(master.id)}
                                                    title="Delete"
                                                >
                                                    <svg
                                                        xmlns="http://www.w3.org/2000/svg"
                                                        width="18"
                                                        height="18"
                                                        viewBox="0 0 24 24"
                                                        fill="none"
                                                        stroke="currentColor"
                                                        strokeWidth="2"
                                                        strokeLinecap="round"
                                                        strokeLinejoin="round"
                                                    >
                                                        <polyline points="3 6 5 6 21 6"></polyline>
                                                        <path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"></path>
                                                        <line x1="10" y1="11" x2="10" y2="17"></line>
                                                        <line x1="14" y1="11" x2="14" y2="17"></line>
                                                    </svg>
                                                </button>
                                            </div>
                                        </td>
                                    </tr>
                                ))
                            )}
                        </tbody>
                    </table>
                )}
            </div>

            {/* Pagination Controls */}
            {!loading && masters.length > 0 && (
                <Pagination
                    currentPage={currentPage}
                    pageSize={rowsPerPage}
                    total={total}
                    itemCount={paginatedMasters.length}
                    onPrev={handlePrev}
                    onNext={handleNext}
                    canNext={currentPage < totalPages}
                    onPageSizeChange={(size) => { setRowsPerPage(size); setSelectedMasters([]); setCurrentPage(1); }}
                />
            )}

            {/* View Details Modal */}
            {viewingMaster && (
                <div className="modal active">
                    <div
                        className="modal-content"
                        style={{ maxWidth: "600px", width: "90%" }}
                    >
                        <button type="button" className="close" aria-label="Close" onClick={() => setViewingMaster(null)} style={{ background: 'none', border: 0, padding: 0 }}>
                            &times;
                        </button>
                        <h2>Master Details</h2>
                        <div
                            style={{
                                marginTop: "20px",
                                display: "flex",
                                flexDirection: "column",
                                gap: "15px",
                            }}
                        >
                            <div>
                                <strong>ID:</strong> {viewingMaster.id}
                            </div>
                            <div>
                                <strong>Name:</strong> {viewingMaster.masterName}
                            </div>
                            <div>
                                <strong>Description:</strong>
                                <div
                                    style={{
                                        background: "var(--bg-secondary)",
                                        padding: "10px",
                                        borderRadius: "5px",
                                        whiteSpace: "pre-wrap",
                                        marginTop: "5px",
                                    }}
                                >
                                    {viewingMaster.description || "-"}
                                </div>
                            </div>
                            <div>
                                <strong>Status:</strong>{" "}
                                {viewingMaster.status ? "Active" : "Inactive"}
                            </div>
                            <div>
                                <strong>Created On:</strong>{" "}
                                {viewingMaster.createdOn
                                    ? new Date(viewingMaster.createdOn).toLocaleString()
                                    : "-"}
                            </div>
                        </div>
                    </div>
                </div>
            )}

            {isFormOpen && (
                <div className="modal active">
                    <div className="modal-content">
                        <button type="button" className="close" aria-label="Close" onClick={() => setIsFormOpen(false)} style={{ background: 'none', border: 0, padding: 0 }}>
                            &times;
                        </button>
                        <h2>{editingMaster ? "Edit Master" : "Add New Master"}</h2>
                        <form onSubmit={handleSubmit} className="admin-form">
                            <input
                                name="masterName"
                                placeholder="Master Name" aria-label="Master Name"
                                value={formData.masterName}
                                onChange={handleInputChange}
                                required
                            />
                            <textarea
                                name="description"
                                placeholder="Description" aria-label="Description"
                                value={formData.description}
                                onChange={handleInputChange}
                                rows="3"
                            />
                            <label
                                style={{
                                    display: "flex",
                                    alignItems: "center",
                                    gap: "8px",
                                    cursor: "pointer",
                                    color: "var(--text-primary)",
                                }}
                            >
                                <input
                                    type="checkbox"
                                    name="status"
                                    checked={formData.status}
                                    onChange={handleInputChange}
                                    style={{ width: "auto", display: "inline-block" }}
                                />
                                Active
                            </label>
                            <button type="submit" className="apply-btn">
                                {editingMaster ? "Update Master" : "Save Master"}
                            </button>
                        </form>
                    </div>
                </div>
            )}
        </section>
    );
}
