import React from 'react';

const DEFAULT_PAGE_SIZES = [20, 50, 100, 150];

// One pagination bar for every list page:
//   [Show Rows: (50 v)]        Page 1 - 50 of 196        [<] [>]
// The rows selector is shown only when onPageSizeChange is passed.
export default function Pagination({
    currentPage,
    pageSize,
    total,
    itemCount,
    onPrev,
    onNext,
    canNext,
    onPageSizeChange,
    pageSizeOptions = DEFAULT_PAGE_SIZES
}) {
    const start = total > 0 ? (currentPage - 1) * pageSize + 1 : 0;
    // itemCount (rows actually on this page) keeps the range right on a short last page
    const end = total > 0 ? Math.min((currentPage - 1) * pageSize + (itemCount ?? pageSize), total) : 0;
    const nextEnabled = canNext ?? currentPage * pageSize < total;

    // Keep the current size selectable even if a page starts with a value outside the list
    const sizes = pageSizeOptions.includes(pageSize)
        ? pageSizeOptions
        : [...pageSizeOptions, pageSize].sort((a, b) => a - b);

    return (
        <nav className="custom-pagination" aria-label="Pagination">
            <div className="rows-select">
                {onPageSizeChange && (
                    <label>
                        Show Rows:
                        <select value={pageSize} onChange={(e) => onPageSizeChange(Number(e.target.value))}>
                            {sizes.map(size => <option key={size} value={size}>{size}</option>)}
                        </select>
                    </label>
                )}
            </div>
            <div className="page-info" aria-live="polite">
                Page {start} - {end} of {total || 0}
            </div>
            <div className="arrow-controls">
                <button type="button" disabled={currentPage <= 1} onClick={onPrev} aria-label="Previous page">◀</button>
                <button type="button" disabled={!nextEnabled} onClick={onNext} aria-label="Next page">▶</button>
            </div>
        </nav>
    );
}
