import React, { useState, useEffect } from 'react';
import { dashboardApi } from '../services/api';
import { LayoutDashboard, Briefcase, Phone, History, Users, Database, Server } from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import '../index.css';

export default function AdminDashboard() {
    const navigate = useNavigate();
    const [counts, setCounts] = useState(null);
    const [loading, setLoading] = useState(true);

    // Enter/Space on a focused card follows it, like a link
    const onCardKey = (e, path) => {
        if (e.key === 'Enter' || e.key === ' ') {
            e.preventDefault();
            navigate(path);
        }
    };

    useEffect(() => {
        const fetchCounts = async () => {
            try {
                const response = await dashboardApi.getCounts();
                if (response.statusCode === 200 && response.data) {
                    setCounts(response.data);
                }
            } catch (error) {
                console.error("Error fetching dashboard counts:", error);
            } finally {
                setLoading(false);
            }
        };

        fetchCounts();
    }, []);

    if (loading) {
        return <div className="container admin-container" style={{ textAlign: 'center', padding: '50px' }}>Loading Dashboard...</div>;
    }

    return (
        <section className="container admin-container">
            <div className="page-header">
                <div className="page-icon">
                    <LayoutDashboard size={20} />
                </div>
                <h2>Dashboard Overview</h2>
            </div>

            {counts ? (
                <div className="dashboard-grid">
                    <div className="dashboard-card" onClick={() => navigate('/admin/jobs')} onKeyDown={(e) => onCardKey(e, '/admin/jobs')} role="link" tabIndex={0} style={{ cursor: 'pointer' }}>
                        <div className="dashboard-card-icon" style={{ background: 'rgba(59, 130, 246, 0.1)', color: '#3b82f6' }}>
                            <Briefcase size={24} />
                        </div>
                        <div className="dashboard-card-info">
                            <h3>Total Jobs</h3>
                            <p className="dashboard-card-value">{counts.totalJobs}</p>
                        </div>
                    </div>

                    <div className="dashboard-card">
                        <div className="dashboard-card-icon" style={{ background: 'rgba(16, 185, 129, 0.1)', color: '#10b981' }}>
                            <Users size={24} />
                        </div>
                        <div className="dashboard-card-info">
                            <h3>Users</h3>
                            <p className="dashboard-card-value">{counts.usersTotal}</p>
                        </div>
                    </div>

                    <div className="dashboard-card" onClick={() => navigate('/admin/master')} onKeyDown={(e) => onCardKey(e, '/admin/master')} role="link" tabIndex={0} style={{ cursor: 'pointer' }}>
                        <div className="dashboard-card-icon" style={{ background: 'rgba(245, 158, 11, 0.1)', color: '#f59e0b' }}>
                            <Database size={24} />
                        </div>
                        <div className="dashboard-card-info">
                            <h3>Masters Total</h3>
                            <p className="dashboard-card-value">{counts.mastersTotal}</p>
                        </div>
                    </div>

                    <div className="dashboard-card" onClick={() => navigate('/admin/master-details')} onKeyDown={(e) => onCardKey(e, '/admin/master-details')} role="link" tabIndex={0} style={{ cursor: 'pointer' }}>
                        <div className="dashboard-card-icon" style={{ background: 'rgba(239, 68, 68, 0.1)', color: 'var(--danger)' }}>
                            <Database size={24} />
                        </div>
                        <div className="dashboard-card-info">
                            <h3>Master Details Total</h3>
                            <p className="dashboard-card-value">{counts.mastersDetailsTotal}</p>
                        </div>
                    </div>

                    <div className="dashboard-card" onClick={() => navigate('/admin/contact-us')} onKeyDown={(e) => onCardKey(e, '/admin/contact-us')} role="link" tabIndex={0} style={{ cursor: 'pointer' }}>
                        <div className="dashboard-card-icon" style={{ background: 'rgba(139, 92, 246, 0.1)', color: '#8b5cf6' }}>
                            <Phone size={24} />
                        </div>
                        <div className="dashboard-card-info">
                            <h3>Contact Us Total</h3>
                            <p className="dashboard-card-value">{counts.contactUsTotal}</p>
                        </div>
                    </div>

                    <div className="dashboard-card" onClick={() => navigate('/admin/ip-logs')} onKeyDown={(e) => onCardKey(e, '/admin/ip-logs')} role="link" tabIndex={0} style={{ cursor: 'pointer' }}>
                        <div className="dashboard-card-icon" style={{ background: 'rgba(236, 72, 153, 0.1)', color: '#ec4899' }}>
                            <Server size={24} />
                        </div>
                        <div className="dashboard-card-info">
                            <h3>IP Logs Total</h3>
                            <p className="dashboard-card-value">{counts.ipLogsTotal}</p>
                        </div>
                    </div>

                    <div className="dashboard-card" onClick={() => navigate('/admin/error-logs')} onKeyDown={(e) => onCardKey(e, '/admin/error-logs')} role="link" tabIndex={0} style={{ cursor: 'pointer' }}>
                        <div className="dashboard-card-icon" style={{ background: 'rgba(99, 102, 241, 0.1)', color: '#6366f1' }}>
                            <History size={24} />
                        </div>
                        <div className="dashboard-card-info">
                            <h3>Error Logs Total</h3>
                            <p className="dashboard-card-value">{counts.logsTotal}</p>
                        </div>
                    </div>
                </div>
            ) : (
                <div style={{ textAlign: 'center', padding: '20px' }}>Failed to load data.</div>
            )}
            
            {counts && counts.jobPublishers && (
                <div className="dashboard-publishers">
                    <h3 style={{ marginBottom: '16px', marginTop: '32px' }}>Jobs by Publisher</h3>
                    <div className="dashboard-grid">
                        {Object.entries(counts.jobPublishers).map(([publisher, count]) => (
                            <div className="dashboard-card" key={publisher}>
                                <div className="dashboard-card-info">
                                    <h4 style={{ color: 'var(--text-secondary)', marginBottom: '8px' }}>{publisher}</h4>
                                    <p className="dashboard-card-value" style={{ fontSize: '20px' }}>{count}</p>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            )}
        </section>
    );
}
