import React, { useState, useEffect, useRef } from 'react';
import { jobApi } from '../services/api';
import BriefcaseIcon from '../components/BriefcaseIcon';
import { Eye, Download, ToggleLeft, ToggleRight, Trash2, Loader2 } from 'lucide-react';
import { exportToExcel } from '../utils/exportUtils';
import Pagination from '../components/Pagination';
import FilterBar from '../components/FilterBar';


// Scraped data: never render a javascript:/data: URL as a link
const safeHttpUrl = (url) => {
    try {
        const parsed = new URL(url);
        return parsed.protocol === 'http:' || parsed.protocol === 'https:' ? parsed.href : null;
    } catch {
        return null;
    }
};

export default function JobsManagement() {
    const [jobs, setJobs] = useState([]);
    const [total, setTotal] = useState(0);
    const [loading, setLoading] = useState(false);
    const [selectedJobs, setSelectedJobs] = useState([]);
    const [deletingOldJobs, setDeletingOldJobs] = useState(false);


    // Pagination & Search State
    const [searchTerm, setSearchTerm] = useState("");
    const [rowsPerPage, setRowsPerPage] = useState(20);
    const [currentPage, setCurrentPage] = useState(1);

    // Cursor State for Pagination
    const [lastId, setLastId] = useState(null);
    const [lastPostedAt, setLastPostedAt] = useState(null);
    const [paginationStack, setPaginationStack] = useState([]);

    // Form State
    const [isFormOpen, setIsFormOpen] = useState(false);
    const [editingJob, setEditingJob] = useState(null);
    const [viewingJob, setViewingJob] = useState(null);
    const [formData, setFormData] = useState({
        jobTitle: '',
        companyName: '',
        jobLocation: '',
        jobDescription: '',
        jobApplyLink: '',
        jobPublisher: ''
    });

    // Search is debounced into its own state; only a changed filter resets the cursor.
    // (Previously the effect also depended on lastId and reset pagination whenever a
    // search term was set, so ▶ could never leave page 1 while searching.)
    const [debouncedSearch, setDebouncedSearch] = useState("");
    // Bumped to refetch the current page after a create/update/delete
    const [reloadKey, setReloadKey] = useState(0);
    const reload = () => setReloadKey(k => k + 1);
    // Only the latest request may update the table
    const requestIdRef = useRef(0);

    useEffect(() => {
        const delaySearch = setTimeout(() => {
            const next = searchTerm.trim();
            if (next !== debouncedSearch) {
                resetPagination();
                setDebouncedSearch(next);
            }
        }, 500); // 500ms debounce
        return () => clearTimeout(delaySearch);
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [searchTerm, debouncedSearch]);

    useEffect(() => {
        const requestId = ++requestIdRef.current;
        const load = async () => {
            setLoading(true);
            try {
                const result = await jobApi.getJobs(rowsPerPage, debouncedSearch, lastId, lastPostedAt);
                if (requestId !== requestIdRef.current) return;

                if (result && result.statusCode === 200 && result.data) {
                    setJobs(result.data.jobs || []);
                    setTotal(result.data.count || 0);
                    setSelectedJobs([]); // Reset selection on new data
                } else {
                    setJobs([]);
                    setTotal(0);
                }
            } catch (error) {
                if (requestId !== requestIdRef.current) return;
                console.error("Error loading jobs:", error);
                setJobs([]);
            }
            setLoading(false);
        };
        load();
    }, [debouncedSearch, rowsPerPage, lastId, lastPostedAt, reloadKey]);

    /* --- Pagination Logic --- */
    const resetPagination = () => {
        setCurrentPage(1);
        setLastId(null);
        setLastPostedAt(null);
        setPaginationStack([]);
    };

    const handleNext = () => {
        if (jobs.length > 0) {
            const lastJob = jobs[jobs.length - 1];
            setPaginationStack([...paginationStack, { id: lastId, date: lastPostedAt }]);
            setLastId(lastJob.id);
            setLastPostedAt(lastJob.lastPostedAt);
            setCurrentPage(prev => prev + 1);
        }
    };

    const handlePrev = () => {
        if (currentPage > 1) {
            const stackCopy = [...paginationStack];
            const prevCursors = stackCopy.pop();
            setPaginationStack(stackCopy);
            setLastId(prevCursors.id);
            setLastPostedAt(prevCursors.date);
            setCurrentPage(prev => prev - 1);
        }
    };

    const totalPages = Math.ceil(total / rowsPerPage);

    /* --- Selection Logic --- */
    const handleSelectAll = (e) => {
        if (e.target.checked) {
            const allJobIds = jobs.map(job => job.id);
            setSelectedJobs(allJobIds);
        } else {
            setSelectedJobs([]);
        }
    };

    const handleSelect = (e, jobId) => {
        if (e.target.checked) {
            setSelectedJobs([...selectedJobs, jobId]);
        } else {
            setSelectedJobs(selectedJobs.filter(id => id !== jobId));
        }
    };

    /* --- Form & CRUD Handlers --- */
    const handleInputChange = (e) => {
        setFormData({ ...formData, [e.target.name]: e.target.value });
    };

    const openCreateForm = () => {
        setEditingJob(null);
        setFormData({
            jobTitle: '', companyName: '', jobLocation: '',
            jobDescription: '', jobApplyLink: '', jobPublisher: ''
        });
        setIsFormOpen(true);
    };

    const openEditForm = (job) => {
        setEditingJob(job);
        // Nullable API fields would make these inputs uncontrolled
        setFormData({
            jobTitle: job.jobTitle ?? '',
            companyName: job.companyName ?? '',
            jobLocation: job.jobLocation ?? '',
            jobDescription: job.jobDescription ?? '',
            jobApplyLink: job.jobApplyLink ?? '',
            jobPublisher: job.jobPublisher ?? ''
        });
        setIsFormOpen(true);
    };

    // The API reports failures in the body's statusCode (HTTP is usually 200), so check it
    const isOk = (result) => result?.statusCode === 200;

    const handleSubmit = async (e) => {
        e.preventDefault();
        try {
            const result = editingJob
                ? await jobApi.updateJob(editingJob.id, formData)
                : await jobApi.createJob(formData);
            if (!isOk(result)) {
                alert(result?.message || "Failed to save job.");
                return;
            }
            setIsFormOpen(false);
            resetPagination(); // Reset karke fresh data load karo
            reload();
        } catch (error) {
            console.error("Error saving job", error);
            alert("Failed to save job.");
        }
    };

    const handleExport = async () => {
        if (!total) return;
        try {
            const allJobs = await jobApi.getJobs(total, '', null, null);
            if (isOk(allJobs) && allJobs.data?.jobs) {
                exportToExcel(allJobs.data.jobs, 'jobs');
            } else {
                alert(allJobs?.message || "Failed to export jobs.");
            }
        } catch (error) {
            console.error("Error exporting jobs:", error);
            alert("Failed to export jobs.");
        }
    };

    // After a delete empties a page past the first, step back instead of stranding the user
    const reloadAfterRemoving = (count) => {
        if (count >= jobs.length && currentPage > 1) {
            handlePrev();
        } else {
            reload();
        }
    };

    const handleDelete = async (id) => {
        if (window.confirm("Are you sure you want to delete this job?")) {
            try {
                const result = await jobApi.deleteJobs([id]);
                if (!isOk(result)) {
                    alert(result?.message || "Failed to delete job.");
                    return;
                }
                reloadAfterRemoving(1);
            } catch (error) {
                console.error("Error deleting job", error);
                alert("Failed to delete job.");
            }
        }
    };

    const handleDeleteSelected = async () => {
        if (window.confirm(`Are you sure you want to delete ${selectedJobs.length} selected jobs?`)) {
            try {
                const result = await jobApi.deleteJobs(selectedJobs);
                if (!isOk(result)) {
                    alert(result?.message || "Failed to delete selected jobs.");
                    return;
                }
                const count = selectedJobs.length;
                setSelectedJobs([]);
                reloadAfterRemoving(count);
            } catch (error) {
                console.error("Error deleting selected jobs", error);
                alert("Failed to delete selected jobs.");
            }
        }
    };

    const handleChangeStatusSelected = async (status) => {
        const isStatusTrue = status === 'active';
        if (window.confirm(`Are you sure you want to change the status of ${selectedJobs.length} jobs to ${status}?`)) {
            try {
                const result = await jobApi.updateJobsStatus(selectedJobs, isStatusTrue);
                if (!isOk(result)) {
                    alert(result?.message || "Failed to change status.");
                    return;
                }
                alert(`Status of ${selectedJobs.length} jobs changed to ${status}.`);
                setSelectedJobs([]);
                reload(); // Refetch data to show changes
            } catch (error) {
                console.error("Error changing status", error);
                alert("Failed to change status.");
            }
        }
    };

    const handleDeleteOldJobs = async () => {
        if (deletingOldJobs) return;
        if (!window.confirm("This permanently deletes ALL stale jobs across every publisher, not just the current page. Continue?")) {
            return;
        }
        setDeletingOldJobs(true);
        try {
            const result = await jobApi.deleteOldJobs();
            if (!isOk(result)) {
                alert(result?.message || "Failed to delete old jobs.");
                return;
            }
            alert(result?.message || "Old jobs cleanup completed.");
            resetPagination();
            reload();
        } catch (error) {
            console.error("Error deleting old jobs", error);
            alert("Failed to delete old jobs.");
        } finally {
            setDeletingOldJobs(false);
        }
    };


    return (
        <section className="container admin-container">
            {/* Header: Title and actions */}
            <div className="admin-header" style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '15px' }}>

                {/* Left Side: Icon & Title */}
                <div className="page-header" style={{ marginBottom: 0 }}>
                    <BriefcaseIcon className="page-icon" />
                    <h2>Jobs Management</h2>
                </div>

                {/* Right Side: actions */}
                <div style={{ display: 'flex', alignItems: 'center', gap: '15px', flexWrap: 'wrap', minWidth: 0 }}>
                    <button className="apply-btn" onClick={openCreateForm} style={{ margin: 0, whiteSpace: 'nowrap' }}>
                        + Add New Job
                    </button>

                    <button className="btn-secondary" onClick={handleExport} title="Export to Excel">
                        <Download size={15} />
                        Export
                    </button>

                    <button
                        className="apply-btn btn-danger"
                        onClick={handleDeleteOldJobs}
                        disabled={deletingOldJobs}
                        title="Permanently deletes stale jobs across all publishers"
                        style={{ margin: 0, whiteSpace: 'nowrap', display: 'flex', alignItems: 'center', gap: '8px' }}
                    >
                        {deletingOldJobs ? <Loader2 size={18} className="spin" /> : <Trash2 size={18} />}
                        {deletingOldJobs ? "Cleaning up..." : "Delete Old Jobs"}
                    </button>
                </div>
            </div>

            <FilterBar
                search={searchTerm}
                onSearchChange={setSearchTerm}
                placeholder="Search title, company or location..."
                onClear={() => setSearchTerm('')}
            />

            {/* Bulk Actions */}
            {selectedJobs.length > 0 && (
                <div className="bulk-actions" style={{ display: 'flex', gap: '10px', alignItems: 'center', padding: '10px', background: 'var(--input-bg)', border: '1px solid var(--input-border)', borderRadius: '8px', marginBottom: '5px' }}>
                    <span style={{ fontWeight: 'bold', color: 'var(--text-primary)' }}>{selectedJobs.length} selected</span>
                    <button onClick={handleDeleteSelected} className="icon-btn btn-danger" title="Delete selected" aria-label="Delete selected">
                        {/* Trash/Delete Icon */}
                        <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                            <polyline points="3 6 5 6 21 6"></polyline>
                            <path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"></path>
                            <line x1="10" y1="11" x2="10" y2="17"></line>
                            <line x1="14" y1="11" x2="14" y2="17"></line>
                        </svg>
                    </button>
                    <button onClick={() => handleChangeStatusSelected('active')} className="apply-btn btn-success" style={{ whiteSpace: 'nowrap', display: 'flex', alignItems: 'center', gap: '5px' }}>
                        <ToggleRight size={18} />
                        <span>Activate</span>
                    </button>
                    <button onClick={() => handleChangeStatusSelected('inactive')} className="apply-btn btn-warning" style={{ whiteSpace: 'nowrap', display: 'flex', alignItems: 'center', gap: '5px' }}>
                        <ToggleLeft size={18} />
                        <span>Deactivate</span>
                    </button>
                </div>
            )}


            {/* Table Area */}
            <div className="table-wrapper">
                {loading ? (
                    <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>
                ) : (
                    <table>
                        <thead>
                            <tr>
                                <th style={{ width: '50px' }}>
                                    <input
                                        type="checkbox"
                                        checked={selectedJobs.length === jobs.length && jobs.length > 0}
                                        onChange={handleSelectAll}
                                        style={{ verticalAlign: 'middle' }}
                                    />
                                </th>
                                <th>Title</th>
                                <th>Company</th>
                                <th>Location</th>
                                <th>PostedAt</th>
                                <th className="col-actions">Actions</th>
                            </tr>
                        </thead>
                        <tbody>
                            {jobs.length === 0 ? (
                                <tr><td colSpan="6" style={{ textAlign: 'center' }}>No jobs found.</td></tr>
                            ) : (
                                jobs.map(job => (
                                    <tr key={job.id} className={selectedJobs.includes(job.id) ? 'selected-row' : ''}>
                                        <td>
                                            <input
                                                type="checkbox"
                                                checked={selectedJobs.includes(job.id)}
                                                onChange={(e) => handleSelect(e, job.id)}
                                                style={{ verticalAlign: 'middle' }}
                                            />
                                        </td>
                                        <td><div className="truncate-text" title={job.jobTitle}>{job.jobTitle}</div></td>
                                        <td><div className="truncate-text" title={job.companyName}>{job.companyName}</div></td>
                                        <td><div className="truncate-text" title={job.jobLocation}>{job.jobLocation}</div></td>
                                        <td>{job.jobPostedAt}</td>
                                        <td>
                                            <div className="action-buttons">
                                                <button
                                                    className="icon-btn view-btn"
                                                    onClick={() => setViewingJob(job)}
                                                    title="View"
                                                >
                                                    <Eye size={18} />
                                                </button>
                                                <button
                                                    className="icon-btn edit-btn"
                                                    onClick={() => openEditForm(job)}
                                                    title="Edit"
                                                >
                                                    {/* Pencil Icon */}
                                                    <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                                                        <path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"></path>
                                                        <path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"></path>
                                                    </svg>
                                                </button>

                                                <button
                                                    className="icon-btn delete-btn"
                                                    onClick={() => handleDelete(job.id)}
                                                    title="Delete"
                                                >
                                                    {/* Trash/Delete Icon */}
                                                    <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                                                        <polyline points="3 6 5 6 21 6"></polyline>
                                                        <path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"></path>
                                                        <line x1="10" y1="11" x2="10" y2="17"></line>
                                                        <line x1="14" y1="11" x2="14" y2="17"></line>
                                                    </svg>
                                                </button>
                                            </div>
                                        </td>
                                    </tr>
                                ))
                            )}
                        </tbody>
                    </table>
                )}
            </div>

            {/* Pagination Controls */}
            {!loading && (jobs.length > 0 || currentPage > 1) && (
                <Pagination
                    currentPage={currentPage}
                    pageSize={rowsPerPage}
                    total={total}
                    itemCount={jobs.length}
                    onPrev={handlePrev}
                    onNext={handleNext}
                    canNext={currentPage < totalPages && jobs.length >= rowsPerPage}
                    onPageSizeChange={(size) => { setRowsPerPage(size); resetPagination(); }}
                />
            )}

            {/* Form Modal */}
            {isFormOpen && (
                <div className="modal active">
                    <div className="modal-content">
                        <button type="button" className="close" aria-label="Close" onClick={() => setIsFormOpen(false)} style={{ background: 'none', border: 0, padding: 0 }}>&times;</button>
                        <h2>{editingJob ? "Edit Job" : "Add New Job"}</h2>
                        <form onSubmit={handleSubmit} className="admin-form">
                            <input name="jobTitle" placeholder="Job Title" aria-label="Job Title" value={formData.jobTitle} onChange={handleInputChange} required />
                            <input name="companyName" placeholder="Company Name" aria-label="Company Name" value={formData.companyName} onChange={handleInputChange} required />
                            <input name="jobLocation" placeholder="Location" aria-label="Location" value={formData.jobLocation} onChange={handleInputChange} required />
                            <input name="jobPublisher" placeholder="Publisher" aria-label="Publisher" value={formData.jobPublisher} onChange={handleInputChange} />
                            <input name="jobApplyLink" placeholder="Application URL" aria-label="Application URL" value={formData.jobApplyLink} onChange={handleInputChange} />
                            <textarea name="jobDescription" placeholder="Job Description" aria-label="Job Description" value={formData.jobDescription} onChange={handleInputChange} required rows="5" />
                            <button type="submit" className="apply-btn">
                                {editingJob ? "Update Job" : "Save Job"}
                            </button>
                        </form>
                    </div>
                </div>
            )}

            {/* View Details Modal */}
            {viewingJob && (
                <div className="modal active">
                    <div className="modal-content" style={{ maxWidth: '600px', width: '90%' }}>
                        <button type="button" className="close" aria-label="Close" onClick={() => setViewingJob(null)} style={{ background: 'none', border: 0, padding: 0 }}>&times;</button>
                        <h2>Job Details</h2>
                        <div style={{ marginTop: '20px', display: 'flex', flexDirection: 'column', gap: '15px' }}>
                            <div><strong>Title:</strong> {viewingJob.jobTitle}</div>
                            <div><strong>Company:</strong> {viewingJob.companyName}</div>
                            <div><strong>Location:</strong> {viewingJob.jobLocation}</div>
                            <div><strong>Publisher:</strong> {viewingJob.jobPublisher || '-'}</div>
                            <div><strong>Posted At:</strong> {viewingJob.jobPostedAt}</div>
                            <div>
                                <strong>Description:</strong>
                                <div style={{ background: 'var(--bg-secondary)', padding: '10px', borderRadius: '5px', whiteSpace: 'pre-wrap', marginTop: '5px', maxHeight: '200px', overflowY: 'auto' }}>
                                    {viewingJob.jobDescription || '-'}
                                </div>
                            </div>
                            {safeHttpUrl(viewingJob.jobApplyLink) && <a href={safeHttpUrl(viewingJob.jobApplyLink)} target="_blank" rel="noopener noreferrer" className="apply-btn" style={{ textDecoration: 'none', textAlign: 'center' }}>Apply Now</a>}
                        </div>
                    </div>
                </div>
            )}
        </section>
    );
}