import React, { useState, useEffect, useCallback, useRef } from 'react';
import { createPortal } from 'react-dom';
import { jobApi, locationApi } from '../services/api';
import BriefcaseIcon from '../components/BriefcaseIcon';
import Pagination from '../components/Pagination';

// Smooth scrolling is motion; honour the OS "reduce motion" setting
const scrollBehavior = () =>
    window.matchMedia?.('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth';

// Apply links are scraped from third-party sites — only open real http(s) URLs,
// and never hand the new tab a window.opener handle back to this page
const openExternal = (url) => {
    try {
        const parsed = new URL(url);
        if (parsed.protocol === 'http:' || parsed.protocol === 'https:') {
            window.open(parsed.href, '_blank', 'noopener,noreferrer');
        }
    } catch {
        // malformed URL — ignore
    }
};

export default function Home() {
    // Fire-and-forget visitor IP/location logging — no loading state or UI
    // impact. locationApi.getLocation handles its own throttling/errors.
    useEffect(() => {
        locationApi.getLocation(window.location.href);
    }, []);

    const [jobs, setJobs] = useState([]);
    const [total, setTotal] = useState(0);
    // Starts true so the first debounced fetch doesn't flash "No jobs available."
    const [loading, setLoading] = useState(true);
    const [isScrolled, setIsScrolled] = useState(false);
    const [selectedJob, setSelectedJob] = useState(null);

    // Search
    const [searchTerm, setSearchTerm] = useState('');

    // Cursor-based pagination (mirrors the admin Jobs Management page — the
    // API only supports sequential next/prev, not jumping to an arbitrary page).
    const rowsPerPage = 20;
    const [currentPage, setCurrentPage] = useState(1);
    const [lastId, setLastId] = useState(null);
    const [lastPostedAt, setLastPostedAt] = useState(null);
    const [paginationStack, setPaginationStack] = useState([]);

    // Only the latest request may update state, so a slow older search/page
    // response can't overwrite the results of a newer one
    const requestIdRef = useRef(0);

    const fetchJobs = useCallback(async (search, cursorId, cursorDate) => {
        const requestId = ++requestIdRef.current;
        setLoading(true);
        try {
            const result = await jobApi.getJobs(rowsPerPage, search.trim(), cursorId, cursorDate);
            if (requestId !== requestIdRef.current) return;
            if (result?.statusCode === 200 && result?.data) {
                setJobs(result.data.jobs || []);
                setTotal(result.data.count || 0);
            } else {
                setJobs([]);
                setTotal(0);
            }
        } catch (err) {
            if (requestId !== requestIdRef.current) return;
            console.error('Error loading jobs:', err);
            setJobs([]);
            setTotal(0);
        }
        setLoading(false);
    }, []);

    // Close the job modal with Escape
    useEffect(() => {
        if (!selectedJob) return;
        const onKeyDown = (e) => { if (e.key === 'Escape') setSelectedJob(null); };
        window.addEventListener('keydown', onKeyDown);
        return () => window.removeEventListener('keydown', onKeyDown);
    }, [selectedJob]);

    const resetPagination = () => {
        setCurrentPage(1);
        setLastId(null);
        setLastPostedAt(null);
        setPaginationStack([]);
    };

    // ─── Debounced search (also covers the initial load) ─────────────────────
    useEffect(() => {
        const timer = setTimeout(() => {
            resetPagination();
            fetchJobs(searchTerm, null, null);
        }, 500);
        return () => clearTimeout(timer);
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [searchTerm, fetchJobs]);

    const totalPages = Math.ceil(total / rowsPerPage);

    const handleNextPage = () => {
        if (jobs.length === 0) return;
        const lastJob = jobs[jobs.length - 1];
        setPaginationStack(prev => [...prev, { id: lastId, date: lastPostedAt }]);
        setLastId(lastJob.id);
        setLastPostedAt(lastJob.lastPostedAt);
        setCurrentPage(prev => prev + 1);
        fetchJobs(searchTerm, lastJob.id, lastJob.lastPostedAt);
        window.scrollTo({ top: document.getElementById('jobs-section')?.offsetTop - 70 || 0, behavior: scrollBehavior() });
    };

    const handlePrevPage = () => {
        if (currentPage <= 1) return;
        const stackCopy = [...paginationStack];
        const prevCursor = stackCopy.pop();
        setPaginationStack(stackCopy);
        setLastId(prevCursor.id);
        setLastPostedAt(prevCursor.date);
        setCurrentPage(prev => prev - 1);
        fetchJobs(searchTerm, prevCursor.id, prevCursor.date);
        window.scrollTo({ top: document.getElementById('jobs-section')?.offsetTop - 70 || 0, behavior: scrollBehavior() });
    };

    // ─── Scroll: navbar search visibility only (no more infinite scroll) ─────
    useEffect(() => {
        const handleScroll = () => setIsScrolled(window.scrollY > 250);
        window.addEventListener('scroll', handleScroll);
        return () => window.removeEventListener('scroll', handleScroll);
    }, []);

    // ─── Helpers ──────────────────────────────────────────────────────────────
    const clearSearch = () => setSearchTerm('');

    const handleNavSearch = (e) => {
        setSearchTerm(e.target.value);
        if (window.innerWidth > 768) {
            const section = document.getElementById('jobs-section');
            if (section) {
                const y = section.getBoundingClientRect().top + window.scrollY - 70;
                window.scrollTo({ top: y, behavior: scrollBehavior() });
            }
        }
    };

    // ─── Render ───────────────────────────────────────────────────────────────
    return (
        <div>
            {/* Navbar portal search (appears when scrolled) */}
            {isScrolled &&
                document.getElementById('navbar-search-portal') &&
                createPortal(
                    <div className="nav-search-animated">
                        <input
                            type="text"
                            placeholder="Search jobs..."
                            aria-label="Search jobs"
                            value={searchTerm}
                            onChange={handleNavSearch}
                        />
                        {searchTerm && (
                            <button
                                type="button"
                                className="search-clear"
                                onClick={clearSearch}
                                title="Clear search"
                                aria-label="Clear search"
                            >
                                &times;
                            </button>
                        )}
                    </div>,
                    document.getElementById('navbar-search-portal')
                )}

            {/* Hero */}
            <section className="hero">
                <div className="page-header center-header">
                    <BriefcaseIcon className="page-icon hero-icon" />
                    <h1>Find Your Dream Job Today</h1>
                </div>

                <div style={{ position: 'relative', display: 'inline-block', width: '100%', maxWidth: '540px', marginTop: '10px' }}>
                    <input
                        type="text"
                        placeholder="Search by title, company, location..."
                        aria-label="Search jobs by title, company or location"
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                        style={{ marginTop: 0, paddingRight: searchTerm ? '40px' : '24px' }}
                    />
                    {searchTerm && (
                        <button
                            type="button"
                            onClick={clearSearch}
                            className="search-clear"
                            title="Clear search"
                            aria-label="Clear search"
                        >
                            &times;
                        </button>
                    )}
                </div>

                <div className="scroll-down-box">
                    <span></span>
                    <span></span>
                    <span></span>
                </div>
            </section>

            {/* Jobs section */}
            <section id="jobs-section" className="container home-card" style={{ minHeight: '50vh' }} aria-labelledby="jobs-heading">
                <h2 id="jobs-heading" className="visually-hidden">Job listings</h2>

                {/* Total count */}
                {/* {!loading && total > 0 && (
                    <div style={{ marginBottom: '16px', color: 'var(--text-secondary)', fontSize: '14px', fontWeight: '500' }}>
                        Showing {Math.min(jobs.length, total)} of {total} jobs
                        {searchTerm && <span> for "<strong>{searchTerm}</strong>"</span>}
                    </div>
                )} */}

                {/* Initial load spinner */}
                {loading && (
                    <div style={{ textAlign: 'center', padding: '40px', color: 'var(--text-secondary)' }}>
                        Loading jobs...
                    </div>
                )}

                {/* Job grid */}
                {!loading && (
                    <div className="job-grid">
                        {jobs.length === 0 ? (
                            <div className="no-jobs">
                                {searchTerm ? `No jobs found for "${searchTerm}".` : 'No jobs available.'}
                            </div>
                        ) : (
                            jobs.map((job) => (
                                <div
                                    className="job-card"
                                    key={job.id}
                                    onClick={() => setSelectedJob(job)}
                                    style={{ cursor: 'pointer' }}
                                >
                                    <div className="card-content">
                                        <h3 className="card-title">{job.jobTitle}</h3>
                                        <div className="card-company">{job.companyName}</div>
                                        <div className="card-location">{job.jobLocation}</div>
                                        <div className="card-meta">
                                            {job.jobPublisher ? `${job.jobPublisher} • ` : ''}
                                            {job.jobPostedAt}
                                        </div>
                                        <div
                                            className="card-actions"
                                            style={{ justifyContent: job.jobApplyLink ? 'space-between' : 'flex-end' }}
                                        >
                                            {job.jobApplyLink && (
                                                <button
                                                    className="direct-apply-btn"
                                                    onClick={(e) => { e.stopPropagation(); openExternal(job.jobApplyLink); }}
                                                    title={`Apply directly via ${job.jobPublisher || 'source site'}`}
                                                >
                                                    Apply via {job.jobPublisher || 'Source'}
                                                </button>
                                            )}
                                            <button
                                                className="apply-btn"
                                                onClick={(e) => { e.stopPropagation(); setSelectedJob(job); }}
                                            >
                                                View
                                            </button>
                                        </div>
                                    </div>
                                </div>
                            ))
                        )}
                    </div>
                )}

                {/* Pagination */}
                {!loading && jobs.length > 0 && (
                    <Pagination
                        currentPage={currentPage}
                        pageSize={rowsPerPage}
                        total={total}
                        itemCount={jobs.length}
                        onPrev={handlePrevPage}
                        onNext={handleNextPage}
                        canNext={currentPage < totalPages}
                    />
                )}
            </section>

            {/* Job detail modal */}
            {selectedJob && (
                <div className="modal active" onClick={() => setSelectedJob(null)}>
                    <div className="modal-content" role="dialog" aria-modal="true" aria-labelledby="job-modal-title" onClick={(e) => e.stopPropagation()}>
                        <button type="button" className="close" aria-label="Close" onClick={() => setSelectedJob(null)} style={{ background: 'none', border: 0, padding: 0 }}>&times;</button>
                        <h2 id="job-modal-title">{selectedJob.jobTitle}</h2>
                        <p><strong>Company:</strong> {selectedJob.companyName}</p>
                        <p><strong>Location:</strong> {selectedJob.jobLocation}</p>
                        <br />
                        <p><strong>Description:</strong> {selectedJob.jobDescription}</p>
                        <br />
                        <div style={{ display: 'flex', flexWrap: 'wrap', gap: '10px', justifyContent: 'space-between', alignItems: 'center', marginTop: '20px', width: '100%' }}>
                            {selectedJob.jobApplyLink && (
                                <button
                                    className="apply-btn"
                                    onClick={() => openExternal(selectedJob.jobApplyLink)}
                                >
                                    Apply via {selectedJob.jobPublisher || 'Source'}
                                </button>
                            )}
                            <button
                                className="apply-btn btn-danger"
                                onClick={() => setSelectedJob(null)}
                            >
                                Close
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
}