import React, { useState, useEffect, useRef } from "react";
import { contactUsApi } from "../services/api";
import { Mail, Eye, Download } from "lucide-react";
import { exportToExcel } from "../utils/exportUtils";
import Pagination from '../components/Pagination';
import FilterBar, { useDebouncedValue } from '../components/FilterBar';

export default function ContactUsManagement() {
    const [contacts, setContacts] = useState([]);
    const [loading, setLoading] = useState(false);
    const [selectedContacts, setSelectedContacts] = useState([]);

    // Pagination State (Server-side)
    const [currentPage, setCurrentPage] = useState(1);
    const [totalItems, setTotalItems] = useState(0);
    const [pageSize, setPageSize] = useState(20);

    // Filters (server-side; search is debounced so typing doesn't fire a request per key)
    const [search, setSearch] = useState("");
    const debouncedSearch = useDebouncedValue(search.trim());
    // Only the latest request may update the table
    const requestIdRef = useRef(0);

    // Modal State
    const [selectedContact, setSelectedContact] = useState(null);

    useEffect(() => {
        fetchContacts(currentPage, pageSize);
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [currentPage, pageSize, debouncedSearch]);

    const fetchContacts = async (page, limit) => {
        const requestId = ++requestIdRef.current;
        setLoading(true);
        try {
            const result = await contactUsApi.getContactUs(page, limit, debouncedSearch);
            if (requestId !== requestIdRef.current) return;
            if (result && result.statusCode === 200 && result.data) {
                setContacts(result.data.items || []);
                setTotalItems(result.data.total || 0);
                setSelectedContacts([]);
            } else {
                setContacts([]);
                setTotalItems(0);
            }
        } catch (error) {
            console.error("Error loading contact us data:", error);
            setContacts([]);
            setTotalItems(0);
        }
        setLoading(false);
    };


    const totalPages = Math.ceil(totalItems / pageSize);

    const handleNext = () => {
        if (currentPage < totalPages) {
            setCurrentPage((prev) => prev + 1);
        }
    };

    const handlePrev = () => {
        if (currentPage > 1) {
            setCurrentPage((prev) => prev - 1);
        }
    };

    const handleExport = async () => {
        try {
            // The API caps a page at 500 rows, so walk every page to export them all
            const all = [];
            for (let page = 1; ; page++) {
                const result = await contactUsApi.getContactUs(page, 500, debouncedSearch);
                const items = result?.statusCode === 200 ? result.data?.items || [] : [];
                all.push(...items);
                if (items.length < 500 || all.length >= (result.data?.total || 0)) break;
            }
            if (all.length) {
                exportToExcel(all, 'contact-us');
            }
        } catch (error) {
            console.error("Error exporting contact us data:", error);
        }
    };

    const handleSelectAll = (e) => {
        if (e.target.checked) {
            const allContactIds = contacts.map(c => c.id);
            setSelectedContacts(allContactIds);
        } else {
            setSelectedContacts([]);
        }
    };

    const handleSelect = (e, contactId) => {
        if (e.target.checked) {
            setSelectedContacts([...selectedContacts, contactId]);
        } else {
            setSelectedContacts(selectedContacts.filter(id => id !== contactId));
        }
    };

    return (
        <section className="container admin-container">
            <div
                className="admin-header"
                style={{
                    display: "flex",
                    justifyContent: "space-between",
                    alignItems: "center",
                    flexWrap: "wrap",
                    gap: "15px",
                }}
            >
                <div className="page-header" style={{ marginBottom: 0 }}>
                    <div className="page-icon">
                        <Mail size={20} />
                    </div>
                    <h2>Contact Us Queries</h2>
                </div>
                <button className="btn-secondary" onClick={handleExport} title="Export to Excel">
                    <Download size={15} />
                    Export
                </button>
            </div>

            <FilterBar
                search={search}
                onSearchChange={(v) => { setSearch(v); setCurrentPage(1); }}
                placeholder="Search name, email, subject or message..."
                onClear={() => { setSearch(""); setCurrentPage(1); }}
            />


            <div className="table-wrapper">
                {loading ? (
                    <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>
                ) : (
                    <table>
                        <thead>
                            <tr>
                                <th style={{ width: '50px' }}>
                                    <input
                                        type="checkbox"
                                        checked={selectedContacts.length === contacts.length && contacts.length > 0}
                                        onChange={handleSelectAll}
                                        style={{ verticalAlign: 'middle' }}
                                    />
                                </th>
                                <th>ID</th>
                                <th>Name</th>
                                <th>Email</th>
                                <th>Subject</th>
                                <th>Message</th>
                                <th>Created On</th>
                                <th className="col-actions">Actions</th>
                            </tr>
                        </thead>
                        <tbody>
                            {contacts.length === 0 ? (
                                <tr>
                                    <td colSpan="8" style={{ textAlign: "center" }}>
                                        No contact queries found.
                                    </td>
                                </tr>
                            ) : (
                                contacts.map((contact) => (
                                    <tr key={contact.id} className={selectedContacts.includes(contact.id) ? 'selected-row' : ''}>
                                        <td>
                                            <input
                                                type="checkbox"
                                                checked={selectedContacts.includes(contact.id)}
                                                onChange={(e) => handleSelect(e, contact.id)}
                                                style={{ verticalAlign: 'middle' }}
                                            />
                                        </td>
                                        <td>{contact.id}</td>
                                        <td>{contact.name}</td>
                                        <td><div className="truncate-text" title={contact.email}>{contact.email}</div></td>
                                        <td><div className="truncate-text" title={contact.subject}>{contact.subject}</div></td>
                                        <td>
                                            <div className="truncate-text" title={contact.message}>
                                                {contact.message}
                                            </div>
                                        </td>
                                        <td>
                                            {contact.createdOn
                                                ? new Date(contact.createdOn).toLocaleString()
                                                : "-"}
                                        </td>
                                        <td>
                                            <div className="action-buttons">
                                                <button
                                                    className="icon-btn view-btn"
                                                    onClick={() => setSelectedContact(contact)}
                                                    title="View Details"
                                                >
                                                    <Eye size={18} />
                                                </button>
                                            </div>
                                        </td>
                                    </tr>
                                ))
                            )}
                        </tbody>
                    </table>
                )}
            </div>

            {/* Pagination Controls */}
            {!loading && totalItems > 0 && (
                <Pagination
                    currentPage={currentPage}
                    pageSize={pageSize}
                    total={totalItems}
                    itemCount={contacts.length}
                    onPrev={handlePrev}
                    onNext={handleNext}
                    canNext={currentPage < totalPages}
                    onPageSizeChange={(size) => { setPageSize(size); setCurrentPage(1); }}
                />
            )}

            {/* Details Modal */}
            {selectedContact && (
                <div className="modal active">
                    <div
                        className="modal-content"
                        style={{ maxWidth: "600px", width: "90%" }}
                    >
                        <button type="button" className="close" aria-label="Close" onClick={() => setSelectedContact(null)} style={{ background: 'none', border: 0, padding: 0 }}>
                            &times;
                        </button>
                        <h2>Contact Us Details</h2>
                        <div
                            style={{
                                marginTop: "20px",
                                display: "flex",
                                flexDirection: "column",
                                gap: "15px",
                            }}
                        >
                            <div>
                                <strong>ID:</strong> {selectedContact.id}
                            </div>
                            <div>
                                <strong>Name:</strong> {selectedContact.name}
                            </div>
                            <div>
                                <strong>Email:</strong> {selectedContact.email}
                            </div>
                            <div>
                                <strong>Subject:</strong> {selectedContact.subject}
                            </div>
                            <div>
                                <strong>Created On:</strong>{" "}
                                {selectedContact.createdOn
                                    ? new Date(selectedContact.createdOn).toLocaleString()
                                    : "-"}
                            </div>
                            <div>
                                <strong>Message:</strong>
                                <div
                                    style={{
                                        background: "var(--bg-secondary)",
                                        padding: "10px",
                                        borderRadius: "5px",
                                        whiteSpace: "pre-wrap",
                                        marginTop: "5px",
                                    }}
                                >
                                    {selectedContact.message || "-"}
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            )}
        </section>
    );
}