import React, { useState, useEffect } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import BriefcaseIcon from '../components/BriefcaseIcon';
import { jobApi } from '../services/api';
import { Eye, EyeOff, ShieldCheck, ArrowLeft } from "lucide-react";

export default function Login({ setIsAuthenticated }) {
    const [credentials, setCredentials] = useState({ username: '', password: '' });
    const [error, setError] = useState('');
    const [loading, setLoading] = useState(false);
    const [showPassword, setShowPassword] = useState(false);

    // 2FA step state
    const [step, setStep] = useState('credentials'); // 'credentials' | 'totp'
    const [preAuthToken, setPreAuthToken] = useState('');
    const [totpCode, setTotpCode] = useState('');

    const navigate = useNavigate();

    const handleChange = (e) => {
        setCredentials({
            ...credentials,
            [e.target.name]: e.target.value
        });
    };

    useEffect(() => {
        const token = localStorage.getItem("token");
        if (token) {
            navigate("/admin");
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);

    const completeLogin = (data) => {
        localStorage.setItem('token', data.token);
        localStorage.setItem('refreshToken', data.refreshToken);
        localStorage.setItem('username', data.username);
        localStorage.setItem('role', data.role);
        setIsAuthenticated(true);
        navigate('/admin');
    };

    const handleLogin = async (e) => {
        e.preventDefault();

        if (loading) return;

        setLoading(true);
        setError("");

        try {
            if (!credentials.username || !credentials.password) {
                setError('Username and password are required');
                return;
            }

            const result = await jobApi.loginApi(credentials);

            if (result?.statusCode === 200 && result?.data?.token) {
                completeLogin(result.data);
            } else if (result?.statusCode === 206 && result?.data?.preAuthToken) {
                // Password was correct, but 2FA is enabled on this account.
                setPreAuthToken(result.data.preAuthToken);
                setStep('totp');
            } else {
                setError(result?.message || 'Invalid username or password');
            }

        } catch (err) {
            console.error("Login Error:", err);
            setError('Server error. Please try again.');
        } finally {
            setLoading(false);
        }
    };

    const handleVerifyTotp = async (e) => {
        e.preventDefault();

        if (loading) return;

        if (totpCode.length !== 6) {
            setError('Enter the 6-digit code from your authenticator app.');
            return;
        }

        setLoading(true);
        setError("");

        try {
            const result = await jobApi.verifyTotpApi({ preAuthToken, totpCode });

            if (result?.statusCode === 200 && result?.data?.token) {
                completeLogin(result.data);
            } else {
                setError(result?.message || 'Invalid or expired code. Please try again.');
            }
        } catch (err) {
            console.error("Verify TOTP Error:", err);
            setError('Server error. Please try again.');
        } finally {
            setLoading(false);
        }
    };

    const backToCredentials = () => {
        setStep('credentials');
        setTotpCode('');
        setPreAuthToken('');
        setError('');
    };

    return (
        <section className="login-container">
            <div className="login-box">
                {step === 'credentials' ? (
                    <>
                        <div className="page-header">
                            <BriefcaseIcon className="page-icon" />
                            <h2>Admin Login</h2>
                        </div>

                        {error && <p className="error-text">{error}</p>}

                        <form onSubmit={handleLogin} className="admin-form">
                            <input
                                type="text"
                                name="username" autoComplete="username" maxLength={50}
                                placeholder="Username" aria-label="Username"
                                value={credentials.username}
                                onChange={handleChange}
                                autoFocus
                                required
                            />

                            <div className="password-field">
                                <input
                                    type={showPassword ? "text" : "password"}
                                    name="password" autoComplete="current-password" maxLength={128}
                                    placeholder="Password" aria-label="Password"
                                    value={credentials.password}
                                    onChange={handleChange}
                                    required
                                />

                                <button type="button" className="password-toggle" onClick={() => setShowPassword(!showPassword)} aria-label={showPassword ? "Hide password" : "Show password"} aria-pressed={showPassword}>
                                    {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                                </button>
                            </div>

                            <div style={{ textAlign: 'left', marginTop: '-10px' }}>
                                <Link to="/forget" style={{ fontSize: '13px', color: 'var(--primary-color)', textDecoration: 'none' }}>
                                    Forgot password?
                                </Link>
                            </div>

                            <button type="submit" className="apply-btn" disabled={loading}>
                                {loading ? "Logging in..." : "Login"}
                            </button>
                        </form>
                    </>
                ) : (
                    <>
                        <div className="page-header">
                            <div className="page-icon">
                                <ShieldCheck size={22} />
                            </div>
                            <h2>Two-Factor Authentication</h2>
                        </div>

                        <p style={{ color: 'var(--text-secondary)', marginBottom: '20px', fontSize: '14px' }}>
                            Enter the 6-digit code from your authenticator app to finish signing in.
                        </p>

                        {error && <p className="error-text">{error}</p>}

                        <form onSubmit={handleVerifyTotp} className="admin-form">
                            <input
                                type="text"
                                inputMode="numeric"
                                autoComplete="one-time-code"
                                className="otp-input"
                                placeholder="000000" aria-label="6-digit code"
                                maxLength={6}
                                value={totpCode}
                                autoFocus
                                onChange={(e) => setTotpCode(e.target.value.replace(/\D/g, '').slice(0, 6))}
                                required
                            />

                            <button type="submit" className="apply-btn" disabled={loading}>
                                {loading ? "Verifying..." : "Verify & Sign In"}
                            </button>

                            <button
                                type="button"
                                onClick={backToCredentials}
                                className="link-btn"
                                style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '6px' }}
                            >
                                <ArrowLeft size={14} /> Back to login
                            </button>
                        </form>
                    </>
                )}
            </div>
        </section>
    );
}
