import React, { useState, useEffect, useRef, useCallback } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { Bell, User, ChevronDown, Moon, Sun, Key, LogOut, CheckCheck, ArrowRight, Menu } from 'lucide-react';
import { notificationApi } from '../services/api';
import { getNotificationIcon, formatRelativeTime } from '../utils/notificationUtils';

export default function AdminNavbar({ handleLogout, theme, toggleTheme, toggleSidebar, isSidebarOpen }) {
    const location = useLocation();
    const navigate = useNavigate();
    const [currentTime, setCurrentTime] = useState(new Date());
    const [isNotificationOpen, setIsNotificationOpen] = useState(false);
    const [isUserDropdownOpen, setIsUserDropdownOpen] = useState(false);
    const [notifications, setNotifications] = useState([]);
    const [unreadCount, setUnreadCount] = useState(0);
    const [loadingNotifications, setLoadingNotifications] = useState(false);

    const userDropdownRef = useRef(null);
    const notificationRef = useRef(null);

    const username = localStorage.getItem("username") || "Admin";

    // Update time every second
    useEffect(() => {
        const timer = setInterval(() => setCurrentTime(new Date()), 1000);
        return () => clearInterval(timer);
    }, []);

    // Close dropdowns when clicking outside
    useEffect(() => {
        const handleClickOutside = (event) => {
            if (userDropdownRef.current && !userDropdownRef.current.contains(event.target)) {
                setIsUserDropdownOpen(false);
            }
            if (notificationRef.current && !notificationRef.current.contains(event.target)) {
                setIsNotificationOpen(false);
            }
        };
        document.addEventListener("mousedown", handleClickOutside);
        return () => document.removeEventListener("mousedown", handleClickOutside);
    }, []);

    const fetchUnreadCount = useCallback(async () => {
        try {
            const result = await notificationApi.getUnreadCount();
            if (result?.statusCode === 200) {
                setUnreadCount(result.data || 0);
            }
        } catch (error) {
            console.error("Error fetching unread notification count:", error);
        }
    }, []);

    // Poll unread count every 30s so the badge stays current even without opening the bell
    useEffect(() => {
        fetchUnreadCount();
        const poller = setInterval(fetchUnreadCount, 30000);
        // The Notifications page fires this after read/unread changes, so the badge updates at once
        window.addEventListener('notifications-changed', fetchUnreadCount);
        return () => {
            clearInterval(poller);
            window.removeEventListener('notifications-changed', fetchUnreadCount);
        };
    }, [fetchUnreadCount]);

    const openNotifications = async () => {
        setIsNotificationOpen(true);
        setLoadingNotifications(true);
        try {
            const result = await notificationApi.getAll(1);
            if (result?.statusCode === 200 && result?.data) {
                setNotifications(result.data.items || []);
                setUnreadCount(result.data.unreadCount || 0);
            }
        } catch (error) {
            console.error("Error fetching notifications:", error);
        } finally {
            setLoadingNotifications(false);
        }
    };

    const handleMarkAsRead = async (notification) => {
        if (notification.isRead) return;
        setNotifications(prev => prev.map(n => n.id === notification.id ? { ...n, isRead: true } : n));
        setUnreadCount(prev => Math.max(0, prev - 1));
        try {
            await notificationApi.markAsRead(notification.id);
        } catch (error) {
            console.error("Error marking notification as read:", error);
        }
    };

    const handleMarkAllAsRead = async () => {
        setNotifications(prev => prev.map(n => ({ ...n, isRead: true })));
        setUnreadCount(0);
        try {
            await notificationApi.markAllAsRead();
        } catch (error) {
            console.error("Error marking all notifications as read:", error);
        }
    };

    const routeTitles = {
        '/admin': 'Admin Dashboard',
        '/admin/notifications': 'Notifications',
        '/admin/jobs': 'Jobs Management',
        '/admin/scrapers': 'Job Scrapers',
        '/admin/master': 'Master Management',
        '/admin/master-details': 'Master Details Management',
        '/admin/contact-us': 'Contact Us Queries',
        '/admin/ip-logs': 'IP Logs',
        '/admin/error-logs': 'Error Logs',
        '/admin/cookie-consent': 'Cookie Consent',
        '/admin/settings/users': 'Admin',
        '/admin/settings/security': 'Two-Factor Auth',
        '/admin/settings/sql-console': 'SQL Console',
        '/admin/api-docs': 'API Docs (Swagger)',
    };

    const currentTitle = routeTitles[location.pathname] || 'Admin Panel';

    const dateOptions = { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric', timeZone: 'Asia/Kolkata' };
    const timeOptions = { hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: true, timeZone: 'Asia/Kolkata' };

    const formattedDate = new Intl.DateTimeFormat('en-IN', dateOptions).format(currentTime);
    const formattedTime = new Intl.DateTimeFormat('en-IN', timeOptions).format(currentTime);

    return (
        <div className="admin-navbar">
            <div className="admin-navbar-left">
                {/* The only sidebar toggle: lives here so it stays visible while the sidebar is
                    fully hidden (desktop) or off-screen (mobile drawer). */}
                <button
                    className="sidebar-menu-toggle"
                    onClick={toggleSidebar}
                    title={isSidebarOpen ? 'Hide menu' : 'Show menu'}
                    aria-label={isSidebarOpen ? 'Hide menu' : 'Show menu'}
                    aria-expanded={isSidebarOpen}
                >
                    <Menu size={22} />
                </button>
                <div className="admin-navbar-titles">
                    <h1 className="admin-page-title">{currentTitle}</h1>
                    <div className="admin-datetime">
                        {formattedDate} | {formattedTime}
                    </div>
                </div>
            </div>

            <div className="admin-navbar-right">
                {/* Theme switch: one click in the navbar instead of inside the user menu */}
                <button
                    className="admin-icon-btn"
                    onClick={toggleTheme}
                    title={theme === 'light' ? 'Switch to dark mode' : 'Switch to light mode'}
                    aria-label={theme === 'light' ? 'Switch to dark mode' : 'Switch to light mode'}
                >
                    {theme === 'light' ? <Moon size={20} /> : <Sun size={20} />}
                </button>

                {/* Notification Bell */}
                <div className="admin-notification" ref={notificationRef}>
                    <button
                        className={`admin-icon-btn ${unreadCount > 0 ? 'has-unread' : ''}`}
                        onClick={() => (isNotificationOpen ? setIsNotificationOpen(false) : openNotifications())}
                        aria-label={unreadCount > 0 ? `Notifications, ${unreadCount} unread` : 'Notifications'}
                        aria-expanded={isNotificationOpen}
                        title={unreadCount > 0 ? `${unreadCount} unread notification${unreadCount > 1 ? 's' : ''}` : 'Notifications'}
                    >
                        <Bell size={20} className={unreadCount > 0 ? 'bell-ring' : ''} />
                        {unreadCount > 0 && (
                            <span className="notification-badge">
                                <span className="notification-badge-ping" />
                                <span className="notification-badge-count">{unreadCount > 99 ? '99+' : unreadCount}</span>
                            </span>
                        )}
                    </button>

                    {isNotificationOpen && (
                        <div className="notification-dropdown">
                            <div className="notification-dropdown-header">
                                <h3>Notifications</h3>
                                {unreadCount > 0 && (
                                    <button className="link-btn" onClick={handleMarkAllAsRead} style={{ display: 'flex', alignItems: 'center', gap: '4px' }}>
                                        <CheckCheck size={14} /> Mark all read
                                    </button>
                                )}
                            </div>
                            <div className="notification-list">
                                {loadingNotifications ? (
                                    <p style={{ color: 'var(--text-muted)', padding: '15px' }}>Loading...</p>
                                ) : notifications.length === 0 ? (
                                    <p style={{ color: 'var(--text-muted)', padding: '15px' }}>No notifications yet.</p>
                                ) : (
                                    notifications.map(notif => {
                                        const Icon = getNotificationIcon(notif.type);
                                        return (
                                            <div
                                                key={notif.id}
                                                className={`notification-item ${!notif.isRead ? 'notification-item-unread' : ''}`}
                                                onClick={() => handleMarkAsRead(notif)}
                                                onKeyDown={(e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); handleMarkAsRead(notif); } }}
                                                role="button"
                                                tabIndex={0}
                                            >
                                                <div className="notification-item-icon">
                                                    <Icon size={16} />
                                                </div>
                                                <div style={{ flex: 1, minWidth: 0 }}>
                                                    <p style={{ margin: 0, fontWeight: 600, color: 'var(--text-primary)', fontSize: '13.5px' }}>{notif.title}</p>
                                                    <p style={{ margin: '2px 0 4px', color: 'var(--text-secondary)', fontSize: '12.5px', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{notif.message}</p>
                                                    <span style={{ fontSize: '11px', color: 'var(--text-muted)' }}>{formatRelativeTime(notif.createdOn)}</span>
                                                </div>
                                                {!notif.isRead && <span className="notification-dot" />}
                                            </div>
                                        );
                                    })
                                )}
                            </div>
                            <button
                                className="notification-view-all"
                                onClick={() => { setIsNotificationOpen(false); navigate('/admin/notifications'); }}
                            >
                                View all notifications <ArrowRight size={14} />
                            </button>
                        </div>
                    )}
                </div>

                {/* User Dropdown */}
                <div className="admin-user-profile" ref={userDropdownRef}>
                    <div
                        className="user-profile-trigger"
                        onClick={() => setIsUserDropdownOpen(!isUserDropdownOpen)}
                        onKeyDown={(e) => {
                            if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); setIsUserDropdownOpen(!isUserDropdownOpen); }
                            if (e.key === 'Escape') setIsUserDropdownOpen(false);
                        }}
                        role="button"
                        tabIndex={0}
                        aria-haspopup="menu"
                        aria-expanded={isUserDropdownOpen}
                        aria-label="User menu"
                    >
                        <div className="user-avatar-small">
                            <User size={18} strokeWidth={2.5} />
                        </div>
                        <div className="user-info-small">
                            <span className="welcome-text">Welcome</span>
                            <span className="username-text" title={username}>{username}</span>
                        </div>
                        <ChevronDown
                            size={16}
                            style={{
                                color: 'var(--text-muted)',
                                transform: isUserDropdownOpen ? 'rotate(180deg)' : 'none',
                                transition: 'transform 0.2s'
                            }}
                        />
                    </div>

                    {isUserDropdownOpen && (
                        <div className="admin-dropdown-menu user-menu">
                            <button className="dropdown-menu-item" onClick={() => {
                                window.dispatchEvent(new Event('open-change-password'));
                                setIsUserDropdownOpen(false);
                            }}>
                                <Key size={16} />
                                <span>Change Password</span>
                            </button>
                            <button className="dropdown-menu-item logout" onClick={() => {
                                handleLogout();
                                setIsUserDropdownOpen(false);
                            }}>
                                <LogOut size={16} />
                                <span>Logout</span>
                            </button>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
}
