import React, { useState, useEffect, useRef } from 'react';
import { jobApi } from '../services/api';
import { Eye, EyeOff, MailCheck } from 'lucide-react';

export default function ChangePasswordModal() {
    const [isOpen, setIsOpen] = useState(false);
    const [step, setStep] = useState('request'); // 'request' | 'reset'
    const [otp, setOtp] = useState('');
    const [newPassword, setNewPassword] = useState('');
    const [confirmPassword, setConfirmPassword] = useState('');
    const [showPassword, setShowPassword] = useState(false);
    const [passwordError, setPasswordError] = useState('');
    const [passwordMessage, setPasswordMessage] = useState('');
    const [loading, setLoading] = useState(false);
    // Auto-close timer after a successful change; cleared on close/unmount so it
    // can't close the modal again if the user reopens it within the delay
    const closeTimerRef = useRef(null);

    useEffect(() => {
        const openModal = () => setIsOpen(true);
        window.addEventListener('open-change-password', openModal);
        return () => {
            window.removeEventListener('open-change-password', openModal);
            clearTimeout(closeTimerRef.current);
        };
    }, []);

    const username = localStorage.getItem("username") || '';

    const resetState = () => {
        setStep('request');
        setOtp('');
        setNewPassword('');
        setConfirmPassword('');
        setPasswordError('');
        setPasswordMessage('');
    };

    const handleClose = () => {
        clearTimeout(closeTimerRef.current);
        setIsOpen(false);
        resetState();
    };

    // Close with Escape
    useEffect(() => {
        if (!isOpen) return;
        const onKeyDown = (e) => { if (e.key === 'Escape') handleClose(); };
        window.addEventListener('keydown', onKeyDown);
        return () => window.removeEventListener('keydown', onKeyDown);
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [isOpen]);

    const handleRequestOtp = async (e) => {
        e.preventDefault();
        if (loading) return;
        setLoading(true);
        setPasswordError('');
        setPasswordMessage('');
        try {
            const result = await jobApi.forgotPasswordApi(username);
            // Don't advance to the OTP step (or show a raw server error) when sending failed
            if (result?.statusCode !== 200) {
                setPasswordError("Failed to send OTP. Please try again.");
                return;
            }
            setPasswordMessage(result?.message || 'An OTP has been sent to your registered email.');
            setStep('reset');
        } catch (error) {
            console.error("Error requesting OTP", error);
            setPasswordError("Failed to send OTP. Please try again.");
        } finally {
            setLoading(false);
        }
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        if (loading) return;
        setPasswordError('');
        setPasswordMessage('');

        if (otp.length !== 6) {
            setPasswordError("Enter the 6-digit OTP sent to your email.");
            return;
        }
        if (newPassword.length < 8) {
            setPasswordError("New password must be at least 8 characters.");
            return;
        }
        if (newPassword !== confirmPassword) {
            setPasswordError("New passwords do not match.");
            return;
        }

        setLoading(true);
        try {
            const result = await jobApi.resetPasswordApi({ username, otp, newPassword });
            if (result?.statusCode === 200) {
                setPasswordMessage(result.message || 'Password changed successfully.');
                closeTimerRef.current = setTimeout(handleClose, 2000);
            } else {
                setPasswordError(result?.message || 'Invalid or expired OTP.');
            }
        } catch (error) {
            console.error("Error changing password", error);
            setPasswordError("Failed to change password. Please try again.");
        } finally {
            setLoading(false);
        }
    };

    if (!isOpen) return null;

    return (
        <div className="modal active">
            <div className="modal-content" role="dialog" aria-modal="true" aria-labelledby="change-password-title">
                <button type="button" className="close" aria-label="Close" onClick={handleClose} style={{ background: 'none', border: 0, padding: 0 }}>&times;</button>
                <h2 id="change-password-title">Change Password</h2>

                {passwordError && <p className="error-text">{passwordError}</p>}
                {passwordMessage && (
                    <p style={{ color: 'var(--success)', marginBottom: '15px', fontWeight: '500', fontSize: '14px', display: 'flex', alignItems: 'center', gap: '6px' }}>
                        <MailCheck size={16} /> {passwordMessage}
                    </p>
                )}

                {step === 'request' ? (
                    <form onSubmit={handleRequestOtp} className="admin-form">
                        <p style={{ color: 'var(--text-secondary)', fontSize: '14px', margin: 0 }}>
                            We'll email a 6-digit OTP to <strong>{username}</strong>'s registered address to confirm this change.
                        </p>
                        <button type="submit" className="apply-btn" disabled={loading}>
                            {loading ? "Sending OTP..." : "Send OTP"}
                        </button>
                    </form>
                ) : (
                    <form onSubmit={handleSubmit} className="admin-form">
                        <input
                            type="text"
                            inputMode="numeric"
                            autoComplete="one-time-code"
                            className="otp-input"
                            placeholder="000000" aria-label="6-digit code"
                            maxLength={6}
                            value={otp}
                            autoFocus
                            onChange={(e) => setOtp(e.target.value.replace(/\D/g, '').slice(0, 6))}
                            required
                        />
                        <div className="password-field">
                            <input
                                type={showPassword ? "text" : "password"}
                                placeholder="New Password" aria-label="New Password"
                                value={newPassword}
                                onChange={(e) => setNewPassword(e.target.value)}
                                required
                            />
                            <button type="button" className="password-toggle" onClick={() => setShowPassword(!showPassword)} aria-label={showPassword ? "Hide password" : "Show password"} aria-pressed={showPassword}>
                                {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                            </button>
                        </div>
                        <input
                            type={showPassword ? "text" : "password"}
                            placeholder="Confirm New Password" aria-label="Confirm New Password"
                            value={confirmPassword}
                            onChange={(e) => setConfirmPassword(e.target.value)}
                            required
                        />
                        <button type="submit" className="apply-btn" disabled={loading}>
                            {loading ? "Saving..." : "Save Password"}
                        </button>
                        <button type="button" className="link-btn" onClick={() => setStep('request')}>
                            Resend OTP
                        </button>
                    </form>
                )}
            </div>
        </div>
    );
}
