import React, { useState, useEffect } from 'react';
import { masterApi, masterDetailsApi } from '../services/api';
import { Database, Eye, Download, ToggleLeft, ToggleRight } from 'lucide-react';
import { exportToExcel } from '../utils/exportUtils';
import Pagination from '../components/Pagination';
import FilterBar from '../components/FilterBar';

export default function MasterDetailsManagement() {
    const [masterDetails, setMasterDetails] = useState([]);
    const [masters, setMasters] = useState([]);
    const [loading, setLoading] = useState(false);
    const [selectedDetails, setSelectedDetails] = useState([]);

    // Pagination State
    const [rowsPerPage, setRowsPerPage] = useState(20);

    // Filters (client-side: the full list is already loaded)
    const [search, setSearch] = useState('');
    const [masterFilter, setMasterFilter] = useState('');
    const [statusFilter, setStatusFilter] = useState('');
    const [currentPage, setCurrentPage] = useState(1);

    const [isFormOpen, setIsFormOpen] = useState(false);
    const [editingDetail, setEditingDetail] = useState(null);
    const [viewDetail, setViewDetail] = useState(null);
    const [formData, setFormData] = useState({
        masterId: '',
        details: [
            { id: 0, masterDetailName: '', description: '', status: true, xref: '' }
        ]
    });

    useEffect(() => {
        fetchMasterDetails();
        fetchMasters();
    }, []);

    const fetchMasterDetails = async () => {
        setLoading(true);
        try {
            const result = await masterDetailsApi.getAll();
            if (result && result.statusCode === 200 && result.data) {
                setMasterDetails(result.data);
                setSelectedDetails([]);
            } else {
                setMasterDetails([]);
            }
        } catch (error) {
            console.error("Error loading master details:", error);
            setMasterDetails([]);
        }
        setLoading(false);
    };

    const fetchMasters = async () => {
        try {
            const result = await masterApi.getAll();
            if (result && result.statusCode === 200 && result.data) {
                setMasters(result.data);
            } else {
                setMasters([]);
            }
        } catch (error) {
            console.error("Error loading masters:", error);
            setMasters([]);
        }
    };

    const handleMasterIdChange = (e) => {
        setFormData(prev => ({ ...prev, masterId: e.target.value }));
    };

    const handleDetailChange = (index, e) => {
        const { name, value, type, checked } = e.target;
        const newDetails = [...formData.details];
        newDetails[index] = { ...newDetails[index], [name]: type === 'checkbox' ? checked : value };
        setFormData(prev => ({ ...prev, details: newDetails }));
    };

    const addDetailField = () => {
        setFormData(prev => ({
            ...prev,
            details: [...prev.details, { id: 0, masterDetailName: '', description: '', status: true, xref: '' }]
        }));
    };

    const removeDetailField = (index) => {
        const newDetails = [...formData.details];
        newDetails.splice(index, 1);
        setFormData(prev => ({ ...prev, details: newDetails }));
    };

    const openCreateForm = () => {
        setEditingDetail(null);
        setFormData({
            masterId: '',
            details: [{ id: 0, masterDetailName: '', description: '', status: true, xref: '' }]
        });
        setIsFormOpen(true);
    };

    const openEditForm = (detail) => {
        setEditingDetail(detail);
        setFormData({
            masterId: detail.masterId || '',
            details: [{
                id: detail.id,
                masterDetailName: detail.masterDetailName || '',
                description: detail.description || '',
                status: !!detail.status,
                xref: detail.xref || ''
            }]
        });
        setIsFormOpen(true);
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        try {
            const mId = parseInt(formData.masterId, 10);
            if (editingDetail) {
                const payload = {
                    ...formData.details[0],
                    masterId: mId
                };
                const result = await masterDetailsApi.update(payload);
                // The API reports failures in the body's statusCode, not the HTTP status
                if (result?.statusCode !== 200) { alert(result?.message || "Request failed."); return; }
            } else {
                // Send all details in a single bulk insert request
                const payloadArray = formData.details.map(detail => ({
                    ...detail,
                    masterId: mId
                }));
                const result = await masterDetailsApi.insert(payloadArray);
                // The API reports failures in the body's statusCode, not the HTTP status
                if (result?.statusCode !== 200) { alert(result?.message || "Request failed."); return; }
            }
            setIsFormOpen(false);
            fetchMasterDetails();
        } catch (error) {
            console.error("Error saving master detail", error);
            alert("Failed to save master detail.");
        }
    };

    const handleDelete = async (id) => {
        if (window.confirm("Are you sure you want to delete this master detail?")) {
            try {
                const result = await masterDetailsApi.delete(id);
                // The API reports failures in the body's statusCode, not the HTTP status
                if (result?.statusCode !== 200) { alert(result?.message || "Request failed."); return; }
                fetchMasterDetails();
            } catch (error) {
                console.error("Error deleting master detail", error);
                alert("Failed to delete master detail.");
            }
        }
    };

    const handleToggleStatus = async (detail) => {
        if (window.confirm(`Are you sure you want to change the status to ${detail.status ? 'Inactive' : 'Active'}?`)) {
            try {
                const result = await masterDetailsApi.updateStatus([detail.id], !detail.status);
                // The API reports failures in the body's statusCode, not the HTTP status
                if (result?.statusCode !== 200) { alert(result?.message || "Request failed."); return; }
                fetchMasterDetails();
            } catch (error) {
                console.error("Error toggling status", error);
                alert("Failed to change status.");
            }
        }
    };

    const handleDeleteSelected = async () => {
        if (window.confirm(`Are you sure you want to delete ${selectedDetails.length} selected items?`)) {
            try {
                const result = await masterDetailsApi.delete(selectedDetails);
                // The API reports failures in the body's statusCode, not the HTTP status
                if (result?.statusCode !== 200) { alert(result?.message || "Request failed."); return; }
                setSelectedDetails([]);
                fetchMasterDetails();
            } catch (error) {
                console.error("Error deleting selected items", error);
                alert("Failed to delete selected items.");
            }
        }
    };

    const handleChangeStatusSelected = async (status) => {
        const statusText = status ? "Active" : "Inactive";
        if (window.confirm(`Are you sure you want to change the status of ${selectedDetails.length} items to ${statusText}?`)) {
            try {
                const result = await masterDetailsApi.updateStatus(selectedDetails, status);
                // The API reports failures in the body's statusCode, not the HTTP status
                if (result?.statusCode !== 200) { alert(result?.message || "Request failed."); return; }
                setSelectedDetails([]);
                fetchMasterDetails();
            } catch (error) {
                console.error("Error changing status", error);
                alert("Failed to change status.");
            }
        }
    };

    const getMasterName = (masterId) => {
        const master = masters.find(m => m.id === masterId);
        return master ? master.masterName : masterId;
    };

    const searchTerm = search.trim().toLowerCase();
    const filteredDetails = masterDetails.filter(d =>
        (!searchTerm
            || (d.masterDetailName || '').toLowerCase().includes(searchTerm)
            || (d.xref || '').toLowerCase().includes(searchTerm)
            || (d.description || '').toLowerCase().includes(searchTerm))
        && (masterFilter === '' || String(d.masterId) === masterFilter)
        && (statusFilter === '' || (statusFilter === 'active') === !!d.status)
    );
    // Any filter change starts again from page 1 with nothing selected
    const changeFilter = (setter) => (value) => {
        setter(value);
        setCurrentPage(1);
        setSelectedDetails([]);
    };

    // Pagination Logic
    const total = filteredDetails.length;
    const totalPages = Math.ceil(total / rowsPerPage);

    const handleNext = () => {
        if (currentPage < totalPages) {
            setSelectedDetails([]);
            setCurrentPage(prev => prev + 1);
        }
    };

    const handlePrev = () => {
        if (currentPage > 1) {
            setSelectedDetails([]);
            setCurrentPage(prev => prev - 1);
        }
    };

    const handleExport = () => {
        exportToExcel(filteredDetails, 'master-details');
    };

    const paginatedMasterDetails = filteredDetails.slice((currentPage - 1) * rowsPerPage, currentPage * rowsPerPage);

    const handleSelectAll = (e) => {
        if (e.target.checked) {
            const allDetailIds = paginatedMasterDetails.map(d => d.id);
            setSelectedDetails(allDetailIds);
        } else {
            setSelectedDetails([]);
        }
    };

    const handleSelect = (e, detailId) => {
        if (e.target.checked) {
            setSelectedDetails([...selectedDetails, detailId]);
        } else {
            setSelectedDetails(selectedDetails.filter(id => id !== detailId));
        }
    };

    return (
        <section className="container admin-container">
            <div className="admin-header" style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '15px' }}>
                <div className="page-header" style={{ marginBottom: 0 }}>
                    <div className="page-icon">
                        <Database size={20} />
                    </div>
                    <h2>Master Details Management</h2>
                </div>
                <div style={{ display: 'flex', alignItems: 'center', gap: '15px', flexWrap: 'wrap' }}>
                    <button className="apply-btn" onClick={openCreateForm} style={{ margin: 0, whiteSpace: 'nowrap' }}>
                        + Add New Master Detail
                    </button>
                    <button className="btn-secondary" onClick={handleExport} title="Export to Excel">
                        <Download size={15} />
                        Export
                    </button>
                </div>
            </div>

            <FilterBar
                search={search}
                onSearchChange={changeFilter(setSearch)}
                placeholder="Search name, XRef or description..."
                selects={[
                    {
                        key: 'master',
                        label: 'Master',
                        value: masterFilter,
                        onChange: changeFilter(setMasterFilter),
                        options: [{ value: '', label: 'All masters' }, ...masters.map(m => ({ value: String(m.id), label: m.masterName }))],
                    },
                    {
                        key: 'status',
                        label: 'Status',
                        value: statusFilter,
                        onChange: changeFilter(setStatusFilter),
                        options: [
                            { value: '', label: 'All statuses' },
                            { value: 'active', label: 'Active' },
                            { value: 'inactive', label: 'Inactive' },
                        ],
                    },
                ]}
                onClear={() => { setSearch(''); setMasterFilter(''); setStatusFilter(''); setCurrentPage(1); setSelectedDetails([]); }}
            />

            {selectedDetails.length > 0 && (
                <div className="bulk-actions" style={{ display: 'flex', gap: '10px', alignItems: 'center', padding: '10px', background: 'var(--input-bg)', border: '1px solid var(--input-border)', borderRadius: '8px', marginBottom: '5px' }}>
                    <span style={{ fontWeight: 'bold', color: 'var(--text-primary)' }}>{selectedDetails.length} selected</span>
                    <button onClick={handleDeleteSelected} className="icon-btn btn-danger" title="Delete selected" aria-label="Delete selected">
                        {/* Trash/Delete Icon */}
                        <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                            <polyline points="3 6 5 6 21 6"></polyline>
                            <path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"></path>
                            <line x1="10" y1="11" x2="10" y2="17"></line>
                            <line x1="14" y1="11" x2="14" y2="17"></line>
                        </svg>
                    </button>
                    <button onClick={() => handleChangeStatusSelected(true)} className="apply-btn btn-success" style={{ whiteSpace: 'nowrap', display: 'flex', alignItems: 'center', gap: '5px' }}>
                        <ToggleRight size={18} />
                        <span>Activate</span>
                    </button>
                    <button onClick={() => handleChangeStatusSelected(false)} className="apply-btn btn-warning" style={{ whiteSpace: 'nowrap', display: 'flex', alignItems: 'center', gap: '5px' }}>
                        <ToggleLeft size={18} />
                        <span>Deactivate</span>
                    </button>
                </div>
            )}

            <div className="table-wrapper">
                {loading ? (
                    <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>
                ) : (
                    <table>
                        <thead>
                            <tr>
                                <th style={{ width: '50px' }}>
                                    <input
                                        type="checkbox"
                                        checked={selectedDetails.length === paginatedMasterDetails.length && paginatedMasterDetails.length > 0}
                                        onChange={handleSelectAll}
                                        style={{ verticalAlign: 'middle' }}
                                    />
                                </th>
                                <th>ID</th>
                                <th>Master</th>
                                <th>Detail Name</th>
                                <th>XRef</th>
                                <th>Description</th>
                                <th>Status</th>
                                <th>Created On</th>
                                <th className="col-actions">Actions</th>
                            </tr>
                        </thead>
                        <tbody>
                            {paginatedMasterDetails.length === 0 ? (
                                <tr><td colSpan="9" style={{ textAlign: 'center' }}>No master details found.</td></tr>
                            ) : (
                                paginatedMasterDetails.map(detail => (
                                    <tr key={detail.id} className={selectedDetails.includes(detail.id) ? 'selected-row' : ''}>
                                        <td>
                                            <input
                                                type="checkbox"
                                                checked={selectedDetails.includes(detail.id)}
                                                onChange={(e) => handleSelect(e, detail.id)}
                                                style={{ verticalAlign: 'middle' }}
                                            />
                                        </td>
                                        <td>{detail.id}</td>
                                        <td>{getMasterName(detail.masterId)}</td>
                                        <td><div className="truncate-text" title={detail.masterDetailName}>{detail.masterDetailName}</div></td>
                                        <td>{detail.xref || '-'}</td>
                                        <td><div className="truncate-text" title={detail.description}>{detail.description || '-'}</div></td>
                                        <td>{detail.status ? 'Active' : 'Inactive'}</td>
                                        <td>{detail.createdOn ? new Date(detail.createdOn).toLocaleString() : '-'}</td>
                                        <td>
                                            <div className="action-buttons">
                                                <button
                                                    className="icon-btn view-btn"
                                                    onClick={() => setViewDetail(detail)}
                                                    title="View Details"
                                                >
                                                    <Eye size={18} />
                                                </button>
                                                <button
                                                    className={`icon-btn ${detail.status ? 'active-btn' : 'inactive-btn'}`}
                                                    onClick={() => handleToggleStatus(detail)}
                                                    title={detail.status ? "Deactivate" : "Activate"}
                                                >
                                                    {detail.status ? (
                                                        <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                                                            <rect width="20" height="14" x="2" y="5" rx="7" />
                                                            <circle cx="16" cy="12" r="3" />
                                                        </svg>
                                                    ) : (
                                                        <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                                                            <rect width="20" height="14" x="2" y="5" rx="7" />
                                                            <circle cx="8" cy="12" r="3" />
                                                        </svg>
                                                    )}
                                                </button>
                                                <button className="icon-btn edit-btn" onClick={() => openEditForm(detail)} title="Edit">
                                                    <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                                                        <path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"></path>
                                                        <path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"></path>
                                                    </svg>
                                                </button>
                                                <button className="icon-btn delete-btn" onClick={() => handleDelete(detail.id)} title="Delete">
                                                    <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                                                        <polyline points="3 6 5 6 21 6"></polyline>
                                                        <path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"></path>
                                                        <line x1="10" y1="11" x2="10" y2="17"></line>
                                                        <line x1="14" y1="11" x2="14" y2="17"></line>
                                                    </svg>
                                                </button>
                                            </div>
                                        </td>
                                    </tr>
                                ))
                            )}
                        </tbody>
                    </table>
                )}
            </div>

            {/* Pagination Controls */}
            {!loading && masterDetails.length > 0 && (
                <Pagination
                    currentPage={currentPage}
                    pageSize={rowsPerPage}
                    total={total}
                    itemCount={paginatedMasterDetails.length}
                    onPrev={handlePrev}
                    onNext={handleNext}
                    canNext={currentPage < totalPages}
                    onPageSizeChange={(size) => { setRowsPerPage(size); setSelectedDetails([]); setCurrentPage(1); }}
                />
            )}

            {/* View Details Modal */}
            {viewDetail && (
                <div className="modal active">
                    <div className="modal-content" style={{ maxWidth: '600px', width: '90%' }}>
                        <button type="button" className="close" aria-label="Close" onClick={() => setViewDetail(null)} style={{ background: 'none', border: 0, padding: 0 }}>&times;</button>
                        <h2>Master Detail Info</h2>
                        <div style={{ marginTop: '20px', display: 'flex', flexDirection: 'column', gap: '15px' }}>
                            <div><strong>ID:</strong> {viewDetail.id}</div>
                            <div><strong>Master Name:</strong> {getMasterName(viewDetail.masterId)}</div>
                            <div><strong>Detail Name:</strong> {viewDetail.masterDetailName}</div>
                            <div><strong>XRef:</strong> {viewDetail.xref || '-'}</div>
                            <div><strong>Description:</strong> {viewDetail.description || '-'}</div>
                            <div><strong>Status:</strong> {viewDetail.status ? 'Active' : 'Inactive'}</div>
                            <div><strong>Created On:</strong> {viewDetail.createdOn ? new Date(viewDetail.createdOn).toLocaleString() : '-'}</div>
                            <div><strong>Updated On:</strong> {viewDetail.updatedOn ? new Date(viewDetail.updatedOn).toLocaleString() : '-'}</div>
                        </div>
                    </div>
                </div>
            )}

            {isFormOpen && (
                <div className="modal active">
                    <div className="modal-content">
                        <button type="button" className="close" aria-label="Close" onClick={() => setIsFormOpen(false)} style={{ background: 'none', border: 0, padding: 0 }}>&times;</button>
                        <h2>{editingDetail ? "Edit Master Detail" : "Add New Master Detail"}</h2>
                        <form onSubmit={handleSubmit} className="admin-form">
                            <select name="masterId" aria-label="Master" value={formData.masterId} onChange={handleMasterIdChange} required>
                                <option value="" disabled>Select Master</option>
                                {masters.map(master => (
                                    <option key={master.id} value={master.id}>{master.masterName}</option>
                                ))}
                            </select>
                            
                            {formData.details.map((detail, index) => (
                                <div key={index} style={{ padding: '15px', border: '1px solid var(--input-border)', borderRadius: '8px', position: 'relative', display: 'flex', flexDirection: 'column', gap: '15px', background: 'var(--bg-primary)' }}>
                                    {!editingDetail && formData.details.length > 1 && (
                                        <button type="button" className="close" onClick={() => removeDetailField(index)} style={{ top: '2px', right: '2px', color: 'var(--danger)' }} title="Remove detail" aria-label={`Remove detail ${index + 1}`}>&times;</button>
                                    )}
                                    <input name="masterDetailName" placeholder="Detail Name" aria-label="Detail Name" value={detail.masterDetailName} onChange={(e) => handleDetailChange(index, e)} required />
                                    <input name="xref" placeholder="XRef" aria-label="XRef" value={detail.xref} onChange={(e) => handleDetailChange(index, e)} />
                                    <textarea name="description" placeholder="Description" aria-label="Description" value={detail.description} onChange={(e) => handleDetailChange(index, e)} rows="2" />
                                    <label style={{ display: 'flex', alignItems: 'center', gap: '8px', cursor: 'pointer', color: 'var(--text-primary)' }}>
                                        <input type="checkbox" name="status" checked={detail.status} onChange={(e) => handleDetailChange(index, e)} style={{ width: 'auto', display: 'inline-block' }} />
                                        Active
                                    </label>
                                </div>
                            ))}

                            {!editingDetail && formData.details[formData.details.length - 1].masterDetailName.trim() !== '' && (
                                <button type="button" onClick={addDetailField} className="apply-btn btn-success" style={{ alignSelf: 'flex-start', marginTop: '-5px', display: 'flex', alignItems: 'center', gap: '5px' }}>
                                    <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><line x1="12" y1="5" x2="12" y2="19"></line><line x1="5" y1="12" x2="19" y2="12"></line></svg>
                                    Add Another Detail
                                </button>
                            )}

                            <button type="submit" className="apply-btn">
                                {editingDetail ? "Update Detail" : "Save Details"}
                            </button>
                        </form>
                    </div>
                </div>
            )}
        </section>
    );
}