import React, { useState, useEffect, useRef } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import BriefcaseIcon from '../components/BriefcaseIcon';
import { jobApi } from '../services/api';
import { Eye, EyeOff, ArrowLeft, MailCheck } from "lucide-react";

export default function ForgetPassword() {
    const [step, setStep] = useState('request'); // 'request' | 'reset'
    const [username, setUsername] = useState('');
    const [otp, setOtp] = useState('');
    const [newPassword, setNewPassword] = useState('');
    const [confirmPassword, setConfirmPassword] = useState('');
    const [showPassword, setShowPassword] = useState(false);

    const [message, setMessage] = useState('');
    const [error, setError] = useState('');
    const [loading, setLoading] = useState(false);

    const navigate = useNavigate();

    // Redirect timer after a successful reset; cancelled if the user leaves this page first
    const redirectTimerRef = useRef(null);
    useEffect(() => () => clearTimeout(redirectTimerRef.current), []);

    const handleRequestOtp = async (e) => {
        e.preventDefault();
        if (loading) return;

        if (!username.trim()) {
            setError('Username is required');
            return;
        }

        setLoading(true);
        setError('');
        setMessage('');

        try {
            const result = await jobApi.forgotPasswordApi(username.trim());
            // Backend returns a generic 200 for any username (to avoid leaking whether it
            // exists). Anything else is a real failure — its message may be a raw exception,
            // so don't display it and don't move on to the OTP step.
            if (result?.statusCode !== 200) {
                setError('Could not send the OTP. Please try again.');
                return;
            }
            setMessage(result?.message || 'If the account exists, an OTP has been sent to the registered email.');
            setStep('reset');
        } catch (err) {
            console.error("Forgot Password Error:", err);
            setError('Server error. Please try again.');
        } finally {
            setLoading(false);
        }
    };

    const handleResetPassword = async (e) => {
        e.preventDefault();
        if (loading) return;

        setError('');
        setMessage('');

        if (otp.length !== 6) {
            setError('Enter the 6-digit OTP sent to your email.');
            return;
        }
        if (newPassword.length < 8) {
            setError('New password must be at least 8 characters.');
            return;
        }
        if (newPassword !== confirmPassword) {
            setError('Passwords do not match.');
            return;
        }

        setLoading(true);

        try {
            const result = await jobApi.resetPasswordApi({ username: username.trim(), otp, newPassword });

            if (result?.statusCode === 200) {
                setMessage(result.message || 'Password reset successfully. Please log in with your new password.');
                redirectTimerRef.current = setTimeout(() => navigate('/login'), 2000);
            } else {
                setError(result?.message || 'Invalid or expired OTP.');
            }
        } catch (err) {
            console.error("Reset Password Error:", err);
            setError('Server error. Please try again.');
        } finally {
            setLoading(false);
        }
    };

    return (
        <section className="container login-container">
            <div className="login-box">
                <div className="page-header">
                    <BriefcaseIcon className="page-icon" />
                    <h2>Reset Password</h2>
                </div>

                {error && <p className="error-text">{error}</p>}
                {message && (
                    <p style={{ color: 'var(--success)', marginBottom: '15px', fontWeight: '500', display: 'flex', alignItems: 'center', gap: '6px', justifyContent: 'center' }}>
                        <MailCheck size={16} /> {message}
                    </p>
                )}

                {step === 'request' ? (
                    <form onSubmit={handleRequestOtp} className="admin-form">
                        <input
                            type="text"
                            name="username"
                            placeholder="Username" aria-label="Username"
                            value={username}
                            onChange={(e) => setUsername(e.target.value)}
                            autoFocus
                            required
                        />

                        <div style={{ textAlign: 'left', marginTop: '-10px' }}>
                            <Link to="/login" style={{ fontSize: '13px', color: 'var(--primary-color)', textDecoration: 'none' }}>
                                Back to Login
                            </Link>
                        </div>

                        <button type="submit" className="apply-btn" disabled={loading}>
                            {loading ? "Sending OTP..." : "Send OTP"}
                        </button>
                    </form>
                ) : (
                    <form onSubmit={handleResetPassword} className="admin-form">
                        <input
                            type="text"
                            inputMode="numeric"
                            autoComplete="one-time-code"
                            className="otp-input"
                            placeholder="000000" aria-label="6-digit code"
                            maxLength={6}
                            value={otp}
                            autoFocus
                            onChange={(e) => setOtp(e.target.value.replace(/\D/g, '').slice(0, 6))}
                            required
                        />

                        <div className="password-field">
                            <input
                                type={showPassword ? "text" : "password"}
                                placeholder="New Password" aria-label="New Password"
                                value={newPassword}
                                onChange={(e) => setNewPassword(e.target.value)}
                                required
                            />
                            <button type="button" className="password-toggle" onClick={() => setShowPassword(!showPassword)} aria-label={showPassword ? "Hide password" : "Show password"} aria-pressed={showPassword}>
                                {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                            </button>
                        </div>

                        <input
                            type={showPassword ? "text" : "password"}
                            placeholder="Confirm New Password" aria-label="Confirm New Password"
                            value={confirmPassword}
                            onChange={(e) => setConfirmPassword(e.target.value)}
                            required
                        />

                        <button type="submit" className="apply-btn" disabled={loading}>
                            {loading ? "Resetting..." : "Reset Password"}
                        </button>

                        <button
                            type="button"
                            className="link-btn"
                            style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '6px' }}
                            onClick={() => { setStep('request'); setOtp(''); setError(''); setMessage(''); }}
                        >
                            <ArrowLeft size={14} /> Use a different username / resend OTP
                        </button>
                    </form>
                )}
            </div>
        </section>
    );
}
