import React, { useState } from 'react';
import { contactUsApi } from '../services/api';
import { Mail, Phone, MapPin, Send, CheckCircle2 } from 'lucide-react';

export default function ContactUs() {
    const [formData, setFormData] = useState({ name: '', email: '', subject: '', message: '' });
    const [submitting, setSubmitting] = useState(false);
    const [submitted, setSubmitted] = useState(false);
    const [error, setError] = useState('');

    const handleChange = (e) => {
        setFormData({ ...formData, [e.target.name]: e.target.value });
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        if (submitting) return;

        setSubmitting(true);
        setError('');
        try {
            const result = await contactUsApi.submit(formData);
            if (result?.statusCode === 200) {
                setSubmitted(true);
                setFormData({ name: '', email: '', subject: '', message: '' });
            } else {
                setError(result?.message || 'Failed to send your message. Please try again.');
            }
        } catch (err) {
            console.error("Contact form error:", err);
            setError('Something went wrong. Please try again in a moment.');
        } finally {
            setSubmitting(false);
        }
    };

    return (
        <section className="container contact-page">
            <div className="contact-hero">
                <h1>Get in Touch</h1>
                <p>Have a question, found a bug, or want to suggest a job source? We'd love to hear from you.</p>
            </div>

            <div className="contact-layout">
                <div className="contact-info-card">
                    <div className="contact-info-item">
                        <div className="contact-info-icon"><Mail size={18} /></div>
                        <div>
                            <h4>Email</h4>
                            <p>rahulsagarmca@zohomail.in</p>
                        </div>
                    </div>
                    <div className="contact-info-item">
                        <div className="contact-info-icon"><Phone size={18} /></div>
                        <div>
                            <h4>Response Time</h4>
                            <p>We usually reply within 1-2 business days.</p>
                        </div>
                    </div>
                    <div className="contact-info-item">
                        <div className="contact-info-icon"><MapPin size={18} /></div>
                        <div>
                            <h4>Based in</h4>
                            <p>India</p>
                        </div>
                    </div>
                </div>

                <div className="contact-form-card">
                    {submitted ? (
                        <div className="contact-success">
                            <CheckCircle2 size={40} />
                            <h3>Message sent!</h3>
                            <p>Thanks for reaching out — we'll get back to you soon.</p>
                            <button className="apply-btn" onClick={() => setSubmitted(false)}>Send another message</button>
                        </div>
                    ) : (
                        <form onSubmit={handleSubmit} className="admin-form">
                            {error && <p className="error-text">{error}</p>}
                            <input
                                type="text"
                                name="name"
                                placeholder="Your Name" aria-label="Your Name" maxLength={100}
                                value={formData.name}
                                onChange={handleChange}
                                required
                            />
                            <input
                                type="email"
                                name="email"
                                placeholder="Your Email" aria-label="Your Email" maxLength={254}
                                value={formData.email}
                                onChange={handleChange}
                                required
                            />
                            <input
                                type="text"
                                name="subject"
                                placeholder="Subject" aria-label="Subject" maxLength={200}
                                value={formData.subject}
                                onChange={handleChange}
                                required
                            />
                            <textarea
                                name="message"
                                placeholder="Your Message" aria-label="Your Message" maxLength={4000}
                                rows="6"
                                value={formData.message}
                                onChange={handleChange}
                                required
                            />
                            <button type="submit" className="apply-btn" disabled={submitting} style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '8px' }}>
                                <Send size={16} /> {submitting ? "Sending..." : "Send Message"}
                            </button>
                        </form>
                    )}
                </div>
            </div>
        </section>
    );
}
