import React, { useEffect, useState } from 'react';
import { usersApi } from '../services/api';
import { Users, Lock, LockOpen, ShieldCheck, ShieldOff } from 'lucide-react';
import FilterBar from '../components/FilterBar';
import Pagination from '../components/Pagination';

export default function AdminUsersManagement() {
    const [users, setUsers] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState('');

    // Filters + pagination (client-side: the full user list is loaded)
    const [search, setSearch] = useState('');
    const [roleFilter, setRoleFilter] = useState('');
    const [statusFilter, setStatusFilter] = useState('');
    const [currentPage, setCurrentPage] = useState(1);
    const [pageSize, setPageSize] = useState(20);

    useEffect(() => {
        const fetchUsers = async () => {
            setLoading(true);
            setError('');
            try {
                const result = await usersApi.getAll();
                if (result?.statusCode === 200 && result?.data) {
                    setUsers(result.data);
                } else {
                    setError(result?.message || 'Failed to load users.');
                }
            } catch (err) {
                console.error("Error loading users:", err);
                setError('Failed to load users.');
            } finally {
                setLoading(false);
            }
        };
        fetchUsers();
    }, []);

    const searchTerm = search.trim().toLowerCase();
    const filteredUsers = users.filter(u =>
        (!searchTerm
            || (u.username || '').toLowerCase().includes(searchTerm)
            || (u.email || '').toLowerCase().includes(searchTerm))
        && (roleFilter === '' || u.role === roleFilter)
        && (statusFilter === ''
            || (statusFilter === 'active' && u.status)
            || (statusFilter === 'inactive' && !u.status)
            || (statusFilter === 'locked' && u.isLock))
    );
    const totalPages = Math.ceil(filteredUsers.length / pageSize);
    const pagedUsers = filteredUsers.slice((currentPage - 1) * pageSize, currentPage * pageSize);
    const roles = [...new Set(users.map(u => u.role).filter(Boolean))];
    const changeFilter = (setter) => (value) => { setter(value); setCurrentPage(1); };

    return (
        <section className="container admin-container">
            <div className="page-header">
                <div className="page-icon">
                    <Users size={20} />
                </div>
                <h2>Admin</h2>
            </div>

            <p style={{ color: 'var(--text-secondary)', fontSize: '14px', marginBottom: '20px', maxWidth: '720px' }}>
                All registered accounts and their current security state.
            </p>

            {error && <p className="error-text">{error}</p>}

            <FilterBar
                search={search}
                onSearchChange={changeFilter(setSearch)}
                placeholder="Search username or email..."
                selects={[
                    {
                        key: 'role',
                        label: 'Role',
                        value: roleFilter,
                        onChange: changeFilter(setRoleFilter),
                        options: [{ value: '', label: 'All roles' }, ...roles.map(r => ({ value: r, label: r }))],
                    },
                    {
                        key: 'status',
                        label: 'Status',
                        value: statusFilter,
                        onChange: changeFilter(setStatusFilter),
                        options: [
                            { value: '', label: 'All statuses' },
                            { value: 'active', label: 'Active' },
                            { value: 'inactive', label: 'Inactive' },
                            { value: 'locked', label: 'Locked' },
                        ],
                    },
                ]}
                onClear={() => { setSearch(''); setRoleFilter(''); setStatusFilter(''); setCurrentPage(1); }}
            />

            <div className="table-wrapper">
                {loading ? (
                    <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>
                ) : (
                    <table>
                        <thead>
                            <tr>
                                <th>Username</th>
                                <th>Email</th>
                                <th>Role</th>
                                <th>Wrong Attempts</th>
                                <th>Last Password Reset</th>
                                <th>Lock Status</th>
                                <th>Account Status</th>
                                <th>2FA</th>
                            </tr>
                        </thead>
                        <tbody>
                            {pagedUsers.length === 0 ? (
                                <tr><td colSpan="8" style={{ textAlign: 'center' }}>No users found.</td></tr>
                            ) : (
                                pagedUsers.map(user => (
                                    <tr key={user.id}>
                                        <td>{user.username}</td>
                                        <td>{user.email}</td>
                                        <td>{user.role}</td>
                                        <td>{user.wrongAttempts}</td>
                                        <td>{user.lastPwdReset ? new Date(user.lastPwdReset).toLocaleString() : '-'}</td>
                                        <td>
                                            <span className={`status-badge ${user.isLock ? 'status-badge-warning' : 'status-badge-success'}`}>
                                                {user.isLock ? <Lock size={13} /> : <LockOpen size={13} />}
                                                {user.isLock ? 'Locked' : 'Unlocked'}
                                            </span>
                                        </td>
                                        <td>
                                            <span className={`status-badge ${user.status ? 'status-badge-success' : 'status-badge-muted'}`}>
                                                {user.status ? 'Active' : 'Inactive'}
                                            </span>
                                        </td>
                                        <td>
                                            <span className={`status-badge ${user.isTotpEnabled ? 'status-badge-success' : 'status-badge-muted'}`}>
                                                {user.isTotpEnabled ? <ShieldCheck size={13} /> : <ShieldOff size={13} />}
                                                {user.isTotpEnabled ? 'Enabled' : 'Disabled'}
                                            </span>
                                        </td>
                                    </tr>
                                ))
                            )}
                        </tbody>
                    </table>
                )}
            </div>

            {!loading && filteredUsers.length > 0 && (
                <Pagination
                    currentPage={currentPage}
                    pageSize={pageSize}
                    total={filteredUsers.length}
                    itemCount={pagedUsers.length}
                    onPrev={() => setCurrentPage(p => Math.max(1, p - 1))}
                    onNext={() => setCurrentPage(p => Math.min(totalPages, p + 1))}
                    canNext={currentPage < totalPages}
                    onPageSizeChange={(size) => { setPageSize(size); setCurrentPage(1); }}
                />
            )}
        </section>
    );
}
