import React, { useEffect, useRef, useState } from 'react';
import { notificationApi } from '../services/api';
import { getNotificationIcon, formatRelativeTime } from '../utils/notificationUtils';
import { Bell, CheckCheck, Mail, MailOpen } from 'lucide-react';
import Pagination from '../components/Pagination';
import FilterBar from '../components/FilterBar';

// Lets the navbar bell refresh its unread badge immediately instead of on its 30s poll
const notifyUnreadChanged = () => window.dispatchEvent(new Event('notifications-changed'));

export default function NotificationsPage() {
    const [notifications, setNotifications] = useState([]);
    const [loading, setLoading] = useState(false);
    const [currentPage, setCurrentPage] = useState(1);
    const [totalItems, setTotalItems] = useState(0);
    const [unreadCount, setUnreadCount] = useState(0);
    const [pageSize, setPageSize] = useState(20);

    // Filters (server-side): read state ('' | 'unread' | 'read') and notification type
    const [readFilter, setReadFilter] = useState('');
    const [typeFilter, setTypeFilter] = useState('');
    const requestIdRef = useRef(0);

    useEffect(() => {
        fetchNotifications(currentPage, pageSize);
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [currentPage, pageSize, readFilter, typeFilter]);

    const fetchNotifications = async (page, size) => {
        const requestId = ++requestIdRef.current;
        setLoading(true);
        try {
            const result = await notificationApi.getAll(page, size, {
                isRead: readFilter === '' ? undefined : readFilter === 'read',
                type: typeFilter
            });
            if (requestId !== requestIdRef.current) return;
            if (result?.statusCode === 200 && result?.data) {
                setNotifications(result.data.items || []);
                setTotalItems(result.data.total || 0);
                setUnreadCount(result.data.unreadCount || 0);
            } else {
                setNotifications([]);
                setTotalItems(0);
            }
        } catch (error) {
            console.error("Error loading notifications:", error);
            setNotifications([]);
            setTotalItems(0);
        }
        setLoading(false);
    };

    const totalPages = Math.ceil(totalItems / pageSize);

    const handleNext = () => {
        if (currentPage < totalPages) setCurrentPage(prev => prev + 1);
    };
    const handlePrev = () => {
        if (currentPage > 1) setCurrentPage(prev => prev - 1);
    };

    // Optimistically flip one notification's read state; roll back if the server refuses
    const setReadState = async (notification, isRead) => {
        if (notification.isRead === isRead) return;
        const apply = (read) => {
            setNotifications(prev => prev.map(n => n.id === notification.id ? { ...n, isRead: read } : n));
            setUnreadCount(prev => Math.max(0, prev + (read ? -1 : 1)));
        };
        apply(isRead);
        try {
            const result = isRead
                ? await notificationApi.markAsRead(notification.id)
                : await notificationApi.markAsUnread(notification.id);
            if (result?.statusCode === 200) {
                notifyUnreadChanged();
            } else {
                apply(!isRead);
            }
        } catch (error) {
            console.error(`Error marking notification as ${isRead ? 'read' : 'unread'}:`, error);
            apply(!isRead);
        }
    };

    const handleMarkAllAsRead = async () => {
        setNotifications(prev => prev.map(n => ({ ...n, isRead: true })));
        setUnreadCount(0);
        try {
            const result = await notificationApi.markAllAsRead();
            // Failed: reload the real read/unread state instead of showing everything as read
            if (result?.statusCode !== 200) fetchNotifications(currentPage, pageSize);
            else notifyUnreadChanged();
        } catch (error) {
            console.error("Error marking all notifications as read:", error);
            fetchNotifications(currentPage, pageSize);
        }
    };

    return (
        <section className="container admin-container">
            <div
                className="admin-header"
                style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '15px' }}
            >
                <div className="page-header" style={{ marginBottom: 0 }}>
                    <div className="page-icon">
                        <Bell size={20} />
                    </div>
                    <h2>Notifications</h2>
                </div>

                {unreadCount > 0 && (
                    <button className="apply-btn" onClick={handleMarkAllAsRead} style={{ margin: 0, display: 'flex', alignItems: 'center', gap: '8px' }}>
                        <CheckCheck size={16} /> Mark all read ({unreadCount})
                    </button>
                )}
            </div>

            <FilterBar
                selects={[
                    {
                        key: 'read',
                        label: 'Status',
                        value: readFilter,
                        onChange: (v) => { setReadFilter(v); setCurrentPage(1); },
                        options: [
                            { value: '', label: 'All notifications' },
                            { value: 'unread', label: 'Unread' },
                            { value: 'read', label: 'Read' },
                        ],
                    },
                    {
                        key: 'type',
                        label: 'Type',
                        value: typeFilter,
                        onChange: (v) => { setTypeFilter(v); setCurrentPage(1); },
                        options: [
                            { value: '', label: 'All types' },
                            { value: 'JobScraper', label: 'Job scraper' },
                            { value: 'ContactUs', label: 'Contact us' },
                            { value: 'ErrorLog', label: 'Error log' },
                            { value: 'IpLog', label: 'IP log' },
                        ],
                    },
                ]}
                onClear={() => { setReadFilter(''); setTypeFilter(''); setCurrentPage(1); }}
            />

            <div className="table-wrapper" style={{ padding: 0 }}>
                {loading ? (
                    <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>
                ) : notifications.length === 0 ? (
                    <div style={{ textAlign: 'center', padding: '30px', color: 'var(--text-muted)' }}>{readFilter || typeFilter ? 'No notifications match these filters.' : 'No notifications yet.'}</div>
                ) : (
                    <div>
                        {notifications.map(notif => {
                            const Icon = getNotificationIcon(notif.type);
                            return (
                                <div
                                    key={notif.id}
                                    className={`notification-item ${!notif.isRead ? 'notification-item-unread' : ''}`}
                                    onClick={() => setReadState(notif, true)}
                                    onKeyDown={(e) => {
                                        if (e.target !== e.currentTarget) return;
                                        if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); setReadState(notif, true); }
                                    }}
                                    role="button"
                                    tabIndex={0}
                                    style={{ padding: '16px 20px', alignItems: 'center' }}
                                >
                                    <div className="notification-item-icon">
                                        <Icon size={16} />
                                    </div>
                                    <div style={{ flex: 1, minWidth: 0 }}>
                                        <p style={{ margin: 0, fontWeight: 600, color: 'var(--text-primary)', fontSize: '14.5px' }}>
                                            {!notif.isRead && <span className="notification-dot" style={{ display: 'inline-block', marginRight: '8px', verticalAlign: 'middle' }} />}
                                            {notif.title}
                                        </p>
                                        <p style={{ margin: '4px 0 6px', color: 'var(--text-secondary)', fontSize: '13.5px' }}>{notif.message}</p>
                                        <span style={{ fontSize: '12px', color: 'var(--text-muted)' }}>
                                            {formatRelativeTime(notif.createdOn)} · {new Date(notif.createdOn).toLocaleString()}
                                        </span>
                                    </div>
                                    {/* Per-item toggle: mark read or back to unread */}
                                    <button
                                        type="button"
                                        className="notif-toggle-btn"
                                        onClick={(e) => { e.stopPropagation(); setReadState(notif, !notif.isRead); }}
                                        title={notif.isRead ? 'Mark as unread' : 'Mark as read'}
                                        aria-label={`${notif.isRead ? 'Mark as unread' : 'Mark as read'}: ${notif.title}`}
                                    >
                                        {notif.isRead ? <Mail size={16} /> : <MailOpen size={16} />}
                                        <span>{notif.isRead ? 'Mark as unread' : 'Mark as read'}</span>
                                    </button>
                                </div>
                            );
                        })}
                    </div>
                )}
            </div>

            {!loading && totalItems > 0 && (
                <Pagination
                    currentPage={currentPage}
                    pageSize={pageSize}
                    total={totalItems}
                    itemCount={notifications.length}
                    onPrev={handlePrev}
                    onNext={handleNext}
                    canNext={currentPage < totalPages}
                    onPageSizeChange={(size) => { setPageSize(size); setCurrentPage(1); }}
                />
            )}
        </section>
    );
}
