import React, { useEffect, useState } from 'react';
import { databaseApi } from '../services/api';
import { Terminal, Table2, Cog, History, Play, Loader2, AlertTriangle, Clock, ChevronUp, ChevronDown } from 'lucide-react';

// Anything that can change data or schema asks for confirmation first. EXEC is included
// because a stored procedure (or dynamic SQL) can do any of the others.
const DESTRUCTIVE_PATTERN = /\b(DELETE|DROP|TRUNCATE|UPDATE|ALTER|GRANT|REVOKE|INSERT|MERGE|EXEC|EXECUTE|CREATE|INTO|SP_RENAME|DBCC|SHUTDOWN)\b/i;

// Rendering tens of thousands of <tr>s freezes the tab
const MAX_RENDERED_ROWS = 1000;

const TAB_LABELS = { tables: 'Tables', procedures: 'Procedures', history: 'History' };

export default function SqlConsole() {
    const [activeTab, setActiveTab] = useState('tables');
    // Independent of which tab is selected — an explicit control to collapse
    // the panel and reclaim vertical space for the editor, or bring it back.
    const [isPanelVisible, setIsPanelVisible] = useState(true);

    const [tables, setTables] = useState([]);
    const [procedures, setProcedures] = useState([]);
    const [history, setHistory] = useState([]);
    const [sidePanelLoading, setSidePanelLoading] = useState(false);

    const [query, setQuery] = useState('');
    const [running, setRunning] = useState(false);
    const [result, setResult] = useState(null);
    const [error, setError] = useState('');

    const [pendingQuery, setPendingQuery] = useState(null);
    const [confirmText, setConfirmText] = useState('');

    const loadSidePanelData = async (tab) => {
        setSidePanelLoading(true);
        try {
            if (tab === 'tables') {
                const res = await databaseApi.getTables();
                if (res?.statusCode === 200) setTables(res.data || []);
            } else if (tab === 'procedures') {
                const res = await databaseApi.getProcedures();
                if (res?.statusCode === 200) setProcedures(res.data || []);
            } else if (tab === 'history') {
                const res = await databaseApi.getHistory(1);
                if (res?.statusCode === 200) setHistory(res.data?.items || []);
            }
        } catch (err) {
            console.error(`Error loading ${tab}:`, err);
        } finally {
            setSidePanelLoading(false);
        }
    };

    useEffect(() => {
        if (isPanelVisible) {
            loadSidePanelData(activeTab);
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [activeTab, isPanelVisible]);

    const handleTabClick = (tab) => {
        setActiveTab(tab);
        // Picking a category implies wanting to see it, even if the panel was hidden.
        setIsPanelVisible(true);
    };

    const runQuery = async (sql) => {
        setRunning(true);
        setError('');
        setResult(null);
        try {
            const res = await databaseApi.execute(sql);
            if (res?.statusCode === 200) {
                setResult(res.data);
            } else {
                setError(res?.message || 'Query failed.');
            }
        } catch (err) {
            console.error("Error executing query:", err);
            setError('Request failed. Check the API is reachable.');
        } finally {
            setRunning(false);
            if (activeTab === 'history' && isPanelVisible) {
                loadSidePanelData('history');
            }
        }
    };

    const handleRunClick = () => {
        if (!query.trim() || running) return;
        if (DESTRUCTIVE_PATTERN.test(query)) {
            setPendingQuery(query);
            setConfirmText('');
        } else {
            runQuery(query);
        }
    };

    const confirmDestructiveRun = () => {
        if (confirmText !== 'CONFIRM') return;
        const sql = pendingQuery;
        setPendingQuery(null);
        setConfirmText('');
        runQuery(sql);
    };

    const handleEditorKeyDown = (e) => {
        if ((e.altKey) && (e.key === 'X' || (e.key === 'x'))) {
            e.preventDefault();
            handleRunClick();
        }
    };

    return (
        <section className="container admin-container">
            <div className="page-header">
                <div className="page-icon">
                    <Terminal size={20} />
                </div>
                <h2>SQL Console</h2>
            </div>

            <p style={{ color: 'var(--text-secondary)', fontSize: '14px', marginBottom: '20px', maxWidth: '760px' }}>
                Run SQL directly against the database — no need to open SSMS. Any statement runs
                (SELECT, INSERT, UPDATE, DELETE, DDL). Destructive-looking statements ask for a typed
                confirmation first. Every execution is recorded in the History tab, including failures.
            </p>

            <div className="sql-console-toolbar">
                <div className="sql-console-tabs">
                    <button className={activeTab === 'tables' ? 'active' : ''} onClick={() => handleTabClick('tables')}>
                        <Table2 size={14} /> Tables
                    </button>
                    <button className={activeTab === 'procedures' ? 'active' : ''} onClick={() => handleTabClick('procedures')}>
                        <Cog size={14} /> Procedures
                    </button>
                    <button className={activeTab === 'history' ? 'active' : ''} onClick={() => handleTabClick('history')}>
                        <History size={14} /> History
                    </button>
                </div>

                <button className="sql-console-toggle-btn" onClick={() => setIsPanelVisible(v => !v)}>
                    {isPanelVisible ? <><ChevronUp size={14} /> Hide {TAB_LABELS[activeTab]}</> : <><ChevronDown size={14} /> Show {TAB_LABELS[activeTab]}</>}
                </button>
            </div>

            <div className="sql-console-layout">
                {isPanelVisible && (
                <div className="sql-console-side">
                    <div className="sql-console-list">
                        {sidePanelLoading ? (
                            <p style={{ color: 'var(--text-muted)', padding: '15px', fontSize: '13px' }}>Loading...</p>
                        ) : activeTab === 'tables' ? (
                            tables.length === 0 ? <p style={{ color: 'var(--text-muted)', padding: '15px', fontSize: '13px' }}>No tables found.</p> :
                            tables.map(t => (
                                <div
                                    key={`${t.schemaName}.${t.tableName}`}
                                    className="sql-console-list-item"
                                    onClick={() => setQuery(`SELECT TOP 100 * FROM [${t.schemaName}].[${t.tableName}];`)}
                                    title="Click to insert a SELECT TOP 100 query"
                                >
                                    <span className="sql-console-list-title">{t.schemaName}.{t.tableName}</span>
                                    <span className="sql-console-list-meta">{t.rowCounts ?? 0} rows · {t.columnCount} cols</span>
                                </div>
                            ))
                        ) : activeTab === 'procedures' ? (
                            procedures.length === 0 ? <p style={{ color: 'var(--text-muted)', padding: '15px', fontSize: '13px' }}>No procedures found.</p> :
                            procedures.map(p => (
                                <div
                                    key={`${p.schemaName}.${p.procedureName}`}
                                    className="sql-console-list-item"
                                    onClick={() => setQuery(`EXEC [${p.schemaName}].[${p.procedureName}]`)}
                                    title="Click to insert an EXEC template"
                                >
                                    <span className="sql-console-list-title">{p.schemaName}.{p.procedureName}</span>
                                    {p.modifiedOn && <span className="sql-console-list-meta">Modified {new Date(p.modifiedOn).toLocaleDateString()}</span>}
                                </div>
                            ))
                        ) : (
                            history.length === 0 ? <p style={{ color: 'var(--text-muted)', padding: '15px', fontSize: '13px' }}>No queries run yet.</p> :
                            history.map(h => (
                                <div
                                    key={h.id}
                                    className="sql-console-list-item"
                                    onClick={() => setQuery(h.query)}
                                    title="Click to load this query back into the editor"
                                >
                                    <span className={`sql-console-list-title ${!h.success ? 'sql-console-history-failed' : ''}`} style={{ whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis', display: 'block' }}>
                                        {h.query}
                                    </span>
                                    <span className="sql-console-list-meta">
                                        {h.success ? `OK · ${h.rowsAffected ?? 0} rows` : 'Failed'} · {new Date(h.executedOn).toLocaleString()}
                                    </span>
                                </div>
                            ))
                        )}
                    </div>
                </div>
                )}

                <div className="sql-console-main">
                    <textarea
                        className="sql-editor"
                        placeholder="SELECT TOP 100 * FROM [dbo].[Users];" aria-label="SELECT TOP 100 * FROM [dbo].[Users];"
                        value={query}
                        onChange={(e) => setQuery(e.target.value)}
                        onKeyDown={handleEditorKeyDown}
                        spellCheck={false}
                    />

                    <div style={{ display: 'flex', alignItems: 'center', gap: '10px', marginTop: '12px' }}>
                        <button className="apply-btn" onClick={handleRunClick} disabled={running || !query.trim()} style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                            {running ? <><Loader2 size={16} className="spin" /> Running...</> : <><Play size={16} /> Run Query</>}
                        </button>
                        <span style={{ fontSize: '12px', color: 'var(--text-muted)' }}>Alt + X to run</span>
                    </div>

                    {error && (
                        <div className="scraper-result scraper-result-error" style={{ marginTop: '16px', fontSize: '13.5px' }}>
                            <AlertTriangle size={14} />
                            <span style={{ whiteSpace: 'pre-wrap' }}>{error}</span>
                        </div>
                    )}

                    {result && (
                        <div style={{ marginTop: '16px' }}>
                            <div style={{ display: 'flex', alignItems: 'center', gap: '12px', marginBottom: '10px', fontSize: '13px', color: 'var(--text-secondary)' }}>
                                <span className="status-badge status-badge-success">
                                    {result.isResultSet ? `${result.rows.length} row(s)` : `${result.rowsAffected ?? 0} row(s) affected`}
                                </span>
                                <span style={{ display: 'flex', alignItems: 'center', gap: '4px' }}>
                                    <Clock size={12} /> {result.durationMs}ms
                                </span>
                            </div>

                            {result.isResultSet && (
                                <div className="table-wrapper">
                                    <table>
                                        <thead>
                                            <tr>
                                                {/* Index keys: duplicate or unnamed columns (e.g. COUNT(*)) share a name */}
                                                {result.columns.map((col, i) => <th key={i}>{col}</th>)}
                                            </tr>
                                        </thead>
                                        <tbody>
                                            {result.rows.length === 0 ? (
                                                <tr><td colSpan={result.columns.length} style={{ textAlign: 'center' }}>No rows returned.</td></tr>
                                            ) : (
                                                result.rows.slice(0, MAX_RENDERED_ROWS).map((row, idx) => (
                                                    <tr key={idx}>
                                                        {result.columns.map((col, i) => (
                                                            <td key={i}>{row[col] == null ? <span style={{ color: 'var(--text-muted)' }}>NULL</span> : String(row[col])}</td>
                                                        ))}
                                                    </tr>
                                                ))
                                            )}
                                        </tbody>
                                    </table>
                                    {result.rows.length > MAX_RENDERED_ROWS && (
                                        <p style={{ padding: '10px', color: 'var(--text-muted)', fontSize: '13px' }}>
                                            Showing the first {MAX_RENDERED_ROWS} of {result.rows.length} rows. Add a TOP or WHERE clause to narrow the result.
                                        </p>
                                    )}
                                </div>
                            )}
                        </div>
                    )}
                </div>
            </div>

            {/* Destructive statement confirmation */}
            {pendingQuery && (
                <div className="modal active">
                    <div className="modal-content" style={{ maxWidth: '520px' }}>
                        <button type="button" className="close" aria-label="Close" onClick={() => setPendingQuery(null)} style={{ background: 'none', border: 0, padding: 0 }}>&times;</button>
                        <h2 style={{ display: 'flex', alignItems: 'center', gap: '8px', color: 'var(--danger)' }}>
                            <AlertTriangle size={20} /> Destructive statement
                        </h2>
                        <p>This query looks like it will modify or remove data/schema:</p>
                        <div style={{ background: 'var(--input-bg)', padding: '12px', borderRadius: '8px', fontFamily: 'monospace', fontSize: '13px', whiteSpace: 'pre-wrap', marginBottom: '16px', maxHeight: '150px', overflowY: 'auto' }}>
                            {pendingQuery}
                        </div>
                        <p>Type <strong>CONFIRM</strong> below to run it anyway.</p>
                        <div className="admin-form" style={{ marginTop: '12px' }}>
                            <input
                                type="text"
                                value={confirmText}
                                onChange={(e) => setConfirmText(e.target.value)}
                                placeholder="CONFIRM"
                                autoFocus
                            />
                            <div style={{ display: 'flex', gap: '10px' }}>
                                <button
                                    className="apply-btn btn-danger"
                                    disabled={confirmText !== 'CONFIRM'}
                                    onClick={confirmDestructiveRun}
                                >
                                    Run Anyway
                                </button>
                                <button type="button" className="link-btn" onClick={() => setPendingQuery(null)}>
                                    Cancel
                                </button>
                            </div>
                        </div>
                    </div>
                </div>
            )}
        </section>
    );
}
