import React, { useEffect, useRef, useState } from 'react';
import { cookieConsentApi } from '../services/api';
import { Cookie, Eye, Download } from 'lucide-react';
import { exportToExcel } from '../utils/exportUtils';
import Pagination from '../components/Pagination';
import FilterBar, { useDebouncedValue } from '../components/FilterBar';

// Server times are UTC; show them in IST like "02 Oct 2026, 09:50:52 IST"
const formatIst = (value) => {
    if (!value) return '-';
    const d = new Date(/[zZ]|[+-]\d\d:\d\d$/.test(value) ? value : `${value}Z`);
    if (isNaN(d)) return '-';
    const s = new Intl.DateTimeFormat('en-GB', {
        timeZone: 'Asia/Kolkata', day: '2-digit', month: 'short', year: 'numeric',
        hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false
    }).format(d);
    return `${s} IST`;
};

const ACTION_LABEL = { AcceptAll: 'Accepted all', RejectAll: 'Rejected all', Custom: 'Saved preferences' };
const Mark = ({ on }) => on ? <span className="consent-yes" aria-label="Yes">✓</span> : <span className="consent-no" aria-label="No">✗</span>;
const Field = ({ label, children }) => (
    <div className="consent-field">
        <span>{label}</span>
        <div>{children ?? '-'}</div>
    </div>
);

export default function CookieConsentManagement() {
    const [items, setItems] = useState([]);
    const [loading, setLoading] = useState(false);
    const [currentPage, setCurrentPage] = useState(1);
    const [pageSize, setPageSize] = useState(20);
    const [total, setTotal] = useState(0);

    const [search, setSearch] = useState('');
    const debouncedSearch = useDebouncedValue(search.trim());
    const [actionFilter, setActionFilter] = useState('');
    const requestIdRef = useRef(0);

    const [detail, setDetail] = useState(null);
    const [detailLoading, setDetailLoading] = useState(false);

    useEffect(() => {
        const load = async () => {
            const requestId = ++requestIdRef.current;
            setLoading(true);
            try {
                const result = await cookieConsentApi.getAll(currentPage, pageSize, debouncedSearch, actionFilter);
                if (requestId !== requestIdRef.current) return;
                if (result?.statusCode === 200 && result.data) {
                    setItems(result.data.items || []);
                    setTotal(result.data.total || 0);
                } else {
                    setItems([]);
                    setTotal(0);
                }
            } catch (err) {
                if (requestId !== requestIdRef.current) return;
                console.error('Error loading cookie consents:', err);
                setItems([]);
                setTotal(0);
            }
            setLoading(false);
        };
        load();
    }, [currentPage, pageSize, debouncedSearch, actionFilter]);

    // Close the detail modal with Escape
    useEffect(() => {
        if (!detail) return;
        const onKey = (e) => { if (e.key === 'Escape') setDetail(null); };
        window.addEventListener('keydown', onKey);
        return () => window.removeEventListener('keydown', onKey);
    }, [detail]);

    const totalPages = Math.ceil(total / pageSize);

    const openDetail = async (consentId) => {
        setDetailLoading(true);
        try {
            const result = await cookieConsentApi.get(consentId);
            if (result?.statusCode === 200) setDetail(result.data);
            else alert(result?.message || 'Could not load consent.');
        } catch (err) {
            console.error('Error loading consent detail:', err);
            alert('Could not load consent.');
        } finally {
            setDetailLoading(false);
        }
    };

    const handleExport = async () => {
        try {
            // API caps a page at 500 rows: walk every page with the active filters
            const all = [];
            for (let page = 1; ; page++) {
                const result = await cookieConsentApi.getAll(page, 500, debouncedSearch, actionFilter);
                const rows = result?.statusCode === 200 ? result.data?.items || [] : [];
                all.push(...rows);
                if (rows.length < 500 || all.length >= (result.data?.total || 0)) break;
            }
            if (all.length) exportToExcel(all, 'cookie-consents');
        } catch (err) {
            console.error('Error exporting cookie consents:', err);
        }
    };

    return (
        <section className="container admin-container">
            <div className="admin-header" style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <div className="page-header" style={{ marginBottom: 0 }}>
                    <div className="page-icon">
                        <Cookie size={20} />
                    </div>
                    <h2>Cookie Consent</h2>
                </div>
                <button className="btn-secondary" onClick={handleExport} title="Export to Excel">
                    <Download size={15} /> Export
                </button>
            </div>

            <FilterBar
                search={search}
                onSearchChange={(v) => { setSearch(v); setCurrentPage(1); }}
                placeholder="Search consent ID, country, city or browser..."
                selects={[{
                    key: 'action',
                    label: 'Action',
                    value: actionFilter,
                    onChange: (v) => { setActionFilter(v); setCurrentPage(1); },
                    options: [
                        { value: '', label: 'All actions' },
                        { value: 'AcceptAll', label: 'Accepted all' },
                        { value: 'RejectAll', label: 'Rejected all' },
                        { value: 'Custom', label: 'Custom preferences' },
                    ],
                }]}
                onClear={() => { setSearch(''); setActionFilter(''); setCurrentPage(1); }}
            />

            <div className="table-wrapper">
                {loading ? (
                    <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>
                ) : (
                    <table>
                        <thead>
                            <tr>
                                <th>Consent ID</th>
                                <th>Action</th>
                                <th>Preferences · Statistics · Marketing</th>
                                <th>Country</th>
                                <th>Device</th>
                                <th>Browser</th>
                                <th>Last Updated</th>
                                <th className="col-actions">Actions</th>
                            </tr>
                        </thead>
                        <tbody>
                            {items.length === 0 ? (
                                <tr><td colSpan="8" style={{ textAlign: 'center' }}>No cookie consents found.</td></tr>
                            ) : items.map(c => (
                                <tr key={c.consentId}>
                                    <td><span className="consent-id" title={c.consentId}>{c.consentId.slice(0, 12)}…</span></td>
                                    <td><span className={`consent-action consent-action-${c.action}`}>{ACTION_LABEL[c.action] || c.action}</span></td>
                                    <td>
                                        <span className="consent-choice">
                                            <Mark on={c.preferences} /> · <Mark on={c.statistics} /> · <Mark on={c.marketing} />
                                        </span>
                                    </td>
                                    <td>{c.country ? `${c.country}${c.countryCode ? ` (${c.countryCode})` : ''}` : '-'}</td>
                                    <td>{c.deviceType || '-'}</td>
                                    <td>{c.browser || '-'}</td>
                                    <td>{formatIst(c.updatedOn)}</td>
                                    <td>
                                        <div className="action-buttons">
                                            <button className="icon-btn view-btn" onClick={() => openDetail(c.consentId)} title="View details" aria-label="View details" disabled={detailLoading}>
                                                <Eye size={16} />
                                            </button>
                                        </div>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                )}
            </div>

            {!loading && total > 0 && (
                <Pagination
                    currentPage={currentPage}
                    pageSize={pageSize}
                    total={total}
                    itemCount={items.length}
                    onPrev={() => setCurrentPage(p => Math.max(1, p - 1))}
                    onNext={() => setCurrentPage(p => Math.min(totalPages, p + 1))}
                    canNext={currentPage < totalPages}
                    onPageSizeChange={(size) => { setPageSize(size); setCurrentPage(1); }}
                />
            )}

            {detail && (
                <div className="modal active" onClick={() => setDetail(null)}>
                    <div className="modal-content consent-detail" role="dialog" aria-modal="true" aria-labelledby="consent-detail-title" onClick={(e) => e.stopPropagation()}>
                        <button type="button" className="close" aria-label="Close" onClick={() => setDetail(null)}>&times;</button>
                        <h2 id="consent-detail-title">Consent Detail</h2>

                        <div className="consent-section">
                            <h3>Consent</h3>
                            <div className="consent-grid">
                                <Field label="Consent ID"><span className="consent-id">{detail.consentId}</span></Field>
                                <Field label="Action">{detail.action}</Field>
                                <Field label="First Recorded">{formatIst(detail.createdOn)}</Field>
                                <Field label="Last Updated">{formatIst(detail.updatedOn)}</Field>
                            </div>
                        </div>

                        <div className="consent-section">
                            <h3>Consent History</h3>
                            {(detail.history || []).map((h, i) => (
                                <div className="consent-history-item" key={i}>
                                    <strong>{ACTION_LABEL[h.action] || h.action}</strong>
                                    <time>{formatIst(h.createdOn)}</time>
                                    <div>
                                        Preferences <Mark on={h.preferences} /> · Statistics <Mark on={h.statistics} /> · Marketing <Mark on={h.marketing} />
                                    </div>
                                </div>
                            ))}
                        </div>

                        <div className="consent-section">
                            <h3>Consent Choices</h3>
                            <div className="consent-grid">
                                <Field label="Necessary"><Mark on={detail.necessary} /></Field>
                                <Field label="Preferences"><Mark on={detail.preferences} /></Field>
                                <Field label="Statistics"><Mark on={detail.statistics} /></Field>
                                <Field label="Marketing"><Mark on={detail.marketing} /></Field>
                            </div>
                        </div>

                        <div className="consent-section">
                            <h3>Purpose-Level Consent</h3>
                            <div className="consent-grid">
                                <Field label="preferences"><Mark on={detail.preferences} /></Field>
                                <Field label="marketing"><Mark on={detail.marketing} /></Field>
                                <Field label="statistics"><Mark on={detail.statistics} /></Field>
                                <Field label="necessary"><Mark on={detail.necessary} /></Field>
                            </div>
                        </div>

                        <div className="consent-section">
                            <h3>Cross-Border Disclosure</h3>
                            <div className="consent-grid">
                                <Field label="Disclosure shown">{detail.disclosureText ? `"${detail.disclosureText}"` : '-'}</Field>
                                <Field label="Settings version">{detail.settingsVersion}</Field>
                                <Field label="Language">{detail.language}</Field>
                            </div>
                        </div>

                        <div className="consent-section">
                            <h3>Location</h3>
                            <div className="consent-grid">
                                <Field label="Country">{detail.country ? `${detail.country}${detail.countryCode ? ` (${detail.countryCode})` : ''}` : '-'}</Field>
                                <Field label="Region / State">{detail.region}</Field>
                                <Field label="City">{detail.city}</Field>
                                <Field label="Timezone">{detail.timezone}</Field>
                            </div>
                        </div>

                        <div className="consent-section">
                            <h3>Device</h3>
                            <div className="consent-grid">
                                <Field label="Device Type">{detail.deviceType}</Field>
                                <Field label="Browser">{detail.browser}</Field>
                                <Field label="OS">{detail.operatingSystem}</Field>
                                <Field label="Language">{detail.language}</Field>
                            </div>
                        </div>

                        <div className="consent-section">
                            <h3>Technical</h3>
                            <div className="consent-grid" style={{ gridTemplateColumns: '1fr' }}>
                                <Field label="IP Address (hashed)"><span className="consent-id">{detail.ipHash}</span></Field>
                                <Field label="Referrer URL">{detail.referrerUrl}</Field>
                                <Field label="Page URL">{detail.pageUrl}</Field>
                                <Field label="User Agent">{detail.userAgent}</Field>
                            </div>
                        </div>
                    </div>
                </div>
            )}
        </section>
    );
}
