import React, { useCallback, useEffect, useRef, useState } from 'react';
import { Link } from 'react-router-dom';
import { Cookie } from 'lucide-react';
import { cookieConsentApi } from '../services/api';
import { getVisitorGeo } from '../utils/visitorGeo';

// Cookie consent banner for the public site.
// The choice is kept in localStorage and recorded on the server (CookieConsent table + history),
// which returns a ConsentId; later changes update that same record.
// Bump CONSENT_VERSION (with the server's CookieConsentConstant.SettingsVersion) to ask again.
const STORAGE_KEY = 'cookieConsent';
const CONSENT_VERSION = 'v1';

const TEXT = {
    en: {
        locale: 'en-US',
        title: 'We use cookies',
        body: 'We use cookies to enhance your browsing experience, serve personalized content, and analyze our traffic. By clicking "Accept All", you consent to our use of cookies.',
        privacy: 'Privacy Policy',
        acceptAll: 'Accept All',
        rejectAll: 'Reject All',
        preferences: 'Preferences',
        prefsTitle: 'Cookie preferences',
        prefsIntro: 'Choose which cookies you allow. You can change this at any time from "Cookie settings" in the footer.',
        save: 'Save preferences',
        alwaysOn: 'Always on',
        categories: {
            necessary: ['Necessary', 'Required for the site to work (security, preferences you set here). Cannot be turned off.'],
            preferences: ['Preferences', 'Remember choices such as theme and language.'],
            statistics: ['Statistics', 'Help us understand how visitors use the site (anonymous traffic analysis).'],
            marketing: ['Marketing', 'Used to show relevant content and measure campaigns.'],
        },
        disclosure: 'Your data may be stored/processed in: India.',
        language: 'Language',
        settings: 'Cookie settings',
    },
    hi: {
        locale: 'hi-IN',
        title: 'हम कुकीज़ का उपयोग करते हैं',
        body: 'हम आपके ब्राउज़िंग अनुभव को बेहतर बनाने, व्यक्तिगत सामग्री दिखाने और ट्रैफ़िक का विश्लेषण करने के लिए कुकीज़ का उपयोग करते हैं। "सभी स्वीकार करें" पर क्लिक करके आप कुकीज़ के उपयोग के लिए सहमति देते हैं।',
        privacy: 'गोपनीयता नीति',
        acceptAll: 'सभी स्वीकार करें',
        rejectAll: 'सभी अस्वीकार करें',
        preferences: 'प्राथमिकताएँ',
        prefsTitle: 'कुकी प्राथमिकताएँ',
        prefsIntro: 'चुनें कि आप कौन-सी कुकीज़ की अनुमति देते हैं। आप इसे कभी भी फ़ुटर में "Cookie settings" से बदल सकते हैं।',
        save: 'प्राथमिकताएँ सहेजें',
        alwaysOn: 'हमेशा चालू',
        categories: {
            necessary: ['आवश्यक', 'साइट के काम करने के लिए ज़रूरी (सुरक्षा, आपकी चुनी सेटिंग्स)। बंद नहीं की जा सकती।'],
            preferences: ['प्राथमिकताएँ', 'थीम और भाषा जैसी पसंद याद रखने के लिए।'],
            statistics: ['सांख्यिकी', 'यह समझने के लिए कि विज़िटर साइट का उपयोग कैसे करते हैं (गुमनाम विश्लेषण)।'],
            marketing: ['मार्केटिंग', 'प्रासंगिक सामग्री दिखाने और अभियानों को मापने के लिए।'],
        },
        disclosure: 'आपका डेटा भारत में संग्रहीत/प्रोसेस किया जा सकता है।',
        language: 'भाषा',
        settings: 'कुकी सेटिंग्स',
    },
};

const readStored = () => {
    try {
        return JSON.parse(localStorage.getItem(STORAGE_KEY) || 'null');
    } catch {
        return null;
    }
};

export default function CookieBanner() {
    const stored = readStored();
    const [visible, setVisible] = useState(() => !stored || stored.version !== CONSENT_VERSION);
    const [showPrefs, setShowPrefs] = useState(false);
    const [lang, setLang] = useState(() => (stored?.lang === 'hi' ? 'hi' : (navigator.language || '').startsWith('hi') ? 'hi' : 'en'));
    const [choices, setChoices] = useState({
        preferences: !!stored?.preferences,
        statistics: !!stored?.statistics,
        marketing: !!stored?.marketing,
    });
    const [saving, setSaving] = useState(false);
    const dialogRef = useRef(null);
    const t = TEXT[lang];

    // "Cookie settings" (footer link or the floating cookie button) reopens the preferences
    useEffect(() => {
        const open = () => setShowPrefs(true);
        window.addEventListener('open-cookie-preferences', open);
        return () => window.removeEventListener('open-cookie-preferences', open);
    }, []);

    // Escape closes the preferences dialog; move focus into it when it opens
    useEffect(() => {
        if (!showPrefs) return;
        dialogRef.current?.focus();
        const onKey = (e) => { if (e.key === 'Escape') setShowPrefs(false); };
        window.addEventListener('keydown', onKey);
        return () => window.removeEventListener('keydown', onKey);
    }, [showPrefs]);

    const save = useCallback(async (action, selected) => {
        if (saving) return;
        setSaving(true);
        const final = action === 'AcceptAll'
            ? { preferences: true, statistics: true, marketing: true }
            : action === 'RejectAll'
                ? { preferences: false, statistics: false, marketing: false }
                : selected;
        const previous = readStored();
        const record = {
            consentId: previous?.consentId || null,
            action,
            ...final,
            version: CONSENT_VERSION,
            lang,
            updatedAt: new Date().toISOString(),
        };

        // Hide straight away; recording on the server is best-effort and must not block the visitor
        localStorage.setItem(STORAGE_KEY, JSON.stringify(record));
        setChoices(final);
        setShowPrefs(false);
        setVisible(false);

        try {
            // Visitor IP + location from the browser lookup (cached; null if it failed)
            const geo = await getVisitorGeo();
            const result = await cookieConsentApi.save({
                consentId: record.consentId,
                action,
                ...final,
                language: t.locale,
                timezone: Intl.DateTimeFormat().resolvedOptions().timeZone || geo?.timezone || null,
                referrerUrl: document.referrer || null,
                pageUrl: window.location.href,
                ip: geo?.ip || null,
                country: geo?.country || null,
                countryCode: geo?.countryCode || null,
                region: geo?.region || null,
                city: geo?.city || null,
            });
            if (result?.statusCode === 200 && result.data?.consentId) {
                localStorage.setItem(STORAGE_KEY, JSON.stringify({ ...record, consentId: result.data.consentId }));
            }
        } catch (err) {
            console.error('Could not record cookie consent:', err);
        } finally {
            setSaving(false);
        }
    }, [saving, lang, t.locale]);

    return (
        <>
            {/* After a choice is made, a small cookie button stays on the page to review/change it */}
            {!visible && !showPrefs && (
                <button
                    type="button"
                    className="cookie-fab"
                    onClick={() => setShowPrefs(true)}
                    title={t.settings}
                    aria-label={t.settings}
                >
                    <Cookie size={22} />
                </button>
            )}

            {visible && (
            <div className="cookie-banner" role="region" aria-label={t.title}>
                <div className="cookie-banner-text">
                    <h2 className="cookie-banner-title">{t.title}</h2>
                    <p>
                        {t.body}{' '}
                        <Link to="/privacy-policy" className="cookie-banner-link">{t.privacy}</Link>
                    </p>
                </div>
                <div className="cookie-banner-side">
                    <select
                        className="cookie-lang"
                        value={lang}
                        onChange={(e) => setLang(e.target.value)}
                        aria-label={t.language}
                    >
                        <option value="en">English</option>
                        <option value="hi">हिन्दी</option>
                    </select>
                    <div className="cookie-banner-actions">
                        <button type="button" className="cookie-btn cookie-btn-primary" onClick={() => save('AcceptAll')} disabled={saving}>{t.acceptAll}</button>
                        <button type="button" className="cookie-btn cookie-btn-outline" onClick={() => save('RejectAll')} disabled={saving}>{t.rejectAll}</button>
                        <button type="button" className="cookie-btn cookie-btn-text" onClick={() => setShowPrefs(true)}>{t.preferences}</button>
                    </div>
                </div>
            </div>
            )}

            {showPrefs && (
                <div className="modal active" onClick={() => setShowPrefs(false)}>
                    <div
                        className="modal-content cookie-prefs"
                        role="dialog"
                        aria-modal="true"
                        aria-labelledby="cookie-prefs-title"
                        tabIndex={-1}
                        ref={dialogRef}
                        onClick={(e) => e.stopPropagation()}
                    >
                        <button type="button" className="close" aria-label="Close" onClick={() => setShowPrefs(false)}>&times;</button>
                        <h2 id="cookie-prefs-title">{t.prefsTitle}</h2>
                        <p className="cookie-prefs-intro">{t.prefsIntro}</p>

                        {['necessary', 'preferences', 'statistics', 'marketing'].map(key => {
                            const [label, desc] = t.categories[key];
                            const locked = key === 'necessary';
                            const checked = locked ? true : choices[key];
                            return (
                                <label className="cookie-category" key={key}>
                                    <span className="cookie-category-text">
                                        <strong>{label}</strong>
                                        <span>{desc}</span>
                                    </span>
                                    {locked ? (
                                        <span className="cookie-always-on">{t.alwaysOn}</span>
                                    ) : (
                                        <input
                                            type="checkbox"
                                            className="cookie-switch"
                                            role="switch"
                                            checked={checked}
                                            onChange={(e) => setChoices(c => ({ ...c, [key]: e.target.checked }))}
                                        />
                                    )}
                                </label>
                            );
                        })}

                        <p className="cookie-disclosure">{t.disclosure}</p>

                        <div className="cookie-prefs-actions">
                            <button type="button" className="cookie-btn cookie-btn-outline" onClick={() => save('Custom', choices)} disabled={saving}>{t.save}</button>
                            <button type="button" className="cookie-btn cookie-btn-primary" onClick={() => save('AcceptAll')} disabled={saving}>{t.acceptAll}</button>
                        </div>
                    </div>
                </div>
            )}
        </>
    );
}
