import React, { useState, useEffect, useRef } from 'react';
import { NavLink, Link } from 'react-router-dom';
import { LayoutDashboard, Briefcase, Key, FileText, LogOut, ChevronDown, Database, User, Mail, Activity, History, HomeIcon, Rocket, ShieldCheck, Users, Terminal, Bell, Cookie } from 'lucide-react';
import BriefcaseIcon from './BriefcaseIcon';

// The sidebar is either fully open or fully hidden; its toggle lives in AdminNavbar so it
// is always reachable. The theme switch also lives in AdminNavbar.
export default function Sidebar({ handleLogout, isOpen, toggleSidebar }) {
    const [isUserDropdownOpen, setIsUserDropdownOpen] = useState(false);
    const dropdownRef = useRef(null);

    // Fetch username from local storage
    const username = localStorage.getItem("username") || "Admin";

    // handleLogout clears the session and redirects to /login itself
    const onLogout = () => handleLogout();

    const handleMenuClick = () => {
        if (window.innerWidth <= 768 && isOpen) {
            toggleSidebar();
        }
    };

    // Close dropdown when clicking outside
    useEffect(() => {
        const handleClickOutside = (event) => {
            if (dropdownRef.current && !dropdownRef.current.contains(event.target)) {
                setIsUserDropdownOpen(false);
            }
        };
        document.addEventListener("mousedown", handleClickOutside);
        return () => document.removeEventListener("mousedown", handleClickOutside);
    }, []);

    return (
        <aside className={`sidebar ${isOpen ? 'open' : 'closed'}`}>
            <div className="sidebar-header">
                <Link to="/admin" className="sidebar-brand" onClick={handleMenuClick} title="Go to Dashboard">
                    <BriefcaseIcon className="sidebar-icon" />
                    <span className="sidebar-brand-text">JobPortal</span>
                </Link>
            </div>

            <ul className="sidebar-menu">
                <li>
                    <NavLink onClick={handleMenuClick} to="/" title="Home" className={({ isActive }) => isActive ? "menu-item active" : "menu-item"}>
                        <HomeIcon size={20} />
                        <span>Home</span>
                    </NavLink>
                </li>
                <li>
                    <NavLink onClick={handleMenuClick} to="/admin" end title="Dashboard" className={({ isActive }) => isActive ? "menu-item active" : "menu-item"}>
                        <LayoutDashboard size={20} />
                        <span>Dashboard</span>
                    </NavLink>
                </li>

                <li>
                    <NavLink onClick={handleMenuClick} to="/admin/notifications" title="Notifications" className={({ isActive }) => isActive ? "menu-item active" : "menu-item"}>
                        <Bell size={20} />
                        <span>Notifications</span>
                    </NavLink>
                </li>

                <li>
                    <NavLink onClick={handleMenuClick} to="/admin/jobs" title="Jobs" className={({ isActive }) => isActive ? "menu-item active" : "menu-item"}>
                        <Briefcase size={20} />
                        <span>Jobs</span>
                    </NavLink>
                </li>

                <li>
                    <NavLink onClick={handleMenuClick} to="/admin/scrapers" title="Job Scrapers" className={({ isActive }) => isActive ? "menu-item active" : "menu-item"}>
                        <Rocket size={20} />
                        <span>Job Scrapers</span>
                    </NavLink>
                </li>

                <li>
                    <NavLink onClick={handleMenuClick} to="/admin/master" title="Master" className={({ isActive }) => isActive ? "menu-item active" : "menu-item"}>
                        <Database size={20} />
                        <span>Master</span>
                    </NavLink>
                </li>

                <li>
                    <NavLink onClick={handleMenuClick} to="/admin/master-details" title="Master Details" className={({ isActive }) => isActive ? "menu-item active" : "menu-item"}>
                        <Database size={20} />
                        <span>Master Details</span>
                    </NavLink>
                </li>

                <li>
                    <NavLink onClick={handleMenuClick} to="/admin/contact-us" title="Contact Us Queries" className={({ isActive }) => isActive ? "menu-item active" : "menu-item"}>
                        <Mail size={20} />
                        <span>Contact Us Queries</span>
                    </NavLink>
                </li>

                <li>
                    <NavLink onClick={handleMenuClick} to="/admin/ip-logs" title="IP Logs" className={({ isActive }) => isActive ? "menu-item active" : "menu-item"}>
                        <Activity size={20} />
                        <span>IP Logs</span>
                    </NavLink>
                </li>

                <li>
                    <NavLink onClick={handleMenuClick} to="/admin/error-logs" title="Error Logs" className={({ isActive }) => isActive ? "menu-item active" : "menu-item"}>
                        <History size={20} />
                        <span>Error Logs</span>
                    </NavLink>
                </li>

                <li>
                    <NavLink onClick={handleMenuClick} to="/admin/cookie-consent" title="Cookie Consent" className={({ isActive }) => isActive ? "menu-item active" : "menu-item"}>
                        <Cookie size={20} />
                        <span>Cookie Consent</span>
                    </NavLink>
                </li>

                <li className="sidebar-section-label">Settings</li>

                <li>
                    <NavLink onClick={handleMenuClick} to="/admin/settings/users" title="Admin" className={({ isActive }) => isActive ? "menu-item active" : "menu-item"}>
                        <Users size={20} />
                        <span>Admin</span>
                    </NavLink>
                </li>

                <li>
                    <NavLink onClick={handleMenuClick} to="/admin/settings/security" title="Two-Factor Auth" className={({ isActive }) => isActive ? "menu-item active" : "menu-item"}>
                        <ShieldCheck size={20} />
                        <span>Two-Factor Auth</span>
                    </NavLink>
                </li>

                <li>
                    <NavLink onClick={handleMenuClick} to="/admin/settings/sql-console" title="SQL Console" className={({ isActive }) => isActive ? "menu-item active" : "menu-item"}>
                        <Terminal size={20} />
                        <span>SQL Console</span>
                    </NavLink>
                </li>

                <li>
                    <NavLink onClick={handleMenuClick} to="/admin/api-docs" title="API Docs (Swagger)" className={({ isActive }) => isActive ? "menu-item active" : "menu-item"}>
                        <FileText size={20} />
                        <span>API Docs (Swagger)</span>
                    </NavLink>
                </li>
            </ul>

            {/* --- USER PROFILE SECTION WITH DROPDOWN --- */}
            <div style={{ position: 'relative' }} ref={dropdownRef}>
                <div
                    className="sidebar-user-profile"
                    onClick={() => setIsUserDropdownOpen(!isUserDropdownOpen)}
                    onKeyDown={(e) => {
                        if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); setIsUserDropdownOpen(!isUserDropdownOpen); }
                        if (e.key === 'Escape') setIsUserDropdownOpen(false);
                    }}
                    role="button"
                    tabIndex={0}
                    aria-haspopup="menu"
                    aria-expanded={isUserDropdownOpen}
                    aria-label="User menu"
                    style={{ cursor: 'pointer', position: 'relative' }}
                    title="User Menu"
                >
                    <div className="user-avatar">
                        <User size={20} strokeWidth={2.5} />
                    </div>
                    <div className="user-info">
                        <span className="welcome-text">Welcome</span>
                        <span className="username-text" title={username}>{username}</span>
                    </div>
                    <ChevronDown size={16} style={{ marginLeft: 'auto', color: 'var(--text-muted)', transform: isUserDropdownOpen ? 'rotate(180deg)' : 'none', transition: 'transform 0.2s' }} />
                </div>

                {isUserDropdownOpen && (
                    <div className="user-dropdown-menu">
                        <button className="dropdown-menu-item" onClick={() => {
                            window.dispatchEvent(new Event('open-change-password'));
                            setIsUserDropdownOpen(false);
                        }}>
                            <Key size={16} />
                            <span>Change Password</span>
                        </button>
                        <button className="dropdown-menu-item logout" onClick={onLogout}>
                            <LogOut size={16} />
                            <span>Logout</span>
                        </button>
                    </div>
                )}
            </div>
        </aside>
    );
}