import React, { useState, useEffect, useRef } from "react";
import { locationApi } from "../services/api";
import { Activity, Eye, Download, Trash2, X } from "lucide-react";
import { exportToExcel } from "../utils/exportUtils";
import Pagination from '../components/Pagination';
import FilterBar, { useDebouncedValue } from '../components/FilterBar';

export default function IpLogsManagement() {
    const [logs, setLogs] = useState([]);
    const [loading, setLoading] = useState(false);
    const [selectedLogs, setSelectedLogs] = useState([]);

    // Modal State
    const [selectedLog, setSelectedLog] = useState(null);

    // Pagination State (Server-side)
    const [currentPage, setCurrentPage] = useState(1);
    const [totalItems, setTotalItems] = useState(0);
    const [pageSize, setPageSize] = useState(20);

    // Filters (server-side; search is debounced so typing doesn't fire a request per key)
    const [search, setSearch] = useState("");
    const debouncedSearch = useDebouncedValue(search.trim());
    const [deviceType, setDeviceType] = useState("");
    // Only the latest request may update the table
    const requestIdRef = useRef(0);

    useEffect(() => {
        fetchLogs(currentPage, pageSize);
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [currentPage, pageSize, debouncedSearch, deviceType]);

    const fetchLogs = async (page, limit) => {
        const requestId = ++requestIdRef.current;
        setLoading(true);
        try {
            const result = await locationApi.getIpLogs(page, limit, debouncedSearch, deviceType);
            if (requestId !== requestIdRef.current) return;
            if (result && result.statusCode === 200 && result.data) {
                setLogs(result.data.items || []);
                setTotalItems(result.data.total || 0);
                setSelectedLogs([]);
            } else {
                setLogs([]);
                setTotalItems(0);
            }
        } catch (error) {
            console.error("Error loading IP logs:", error);
            setLogs([]);
            setTotalItems(0);
        }
        setLoading(false);
    };


    const totalPages = Math.ceil(totalItems / pageSize);

    const handleNext = () => {
        if (currentPage < totalPages) {
            setCurrentPage((prev) => prev + 1);
        }
    };

    const handlePrev = () => {
        if (currentPage > 1) {
            setCurrentPage((prev) => prev - 1);
        }
    };

    const handleExport = async () => {
        try {
            // The API caps a page at 500 rows, so walk every page to export them all
            const all = [];
            for (let page = 1; ; page++) {
                const result = await locationApi.getIpLogs(page, 500, debouncedSearch, deviceType);
                const items = result?.statusCode === 200 ? result.data?.items || [] : [];
                all.push(...items);
                if (items.length < 500 || all.length >= (result.data?.total || 0)) break;
            }
            if (all.length) {
                exportToExcel(all, 'ip-logs');
            }
        } catch (error) {
            console.error("Error exporting IP logs:", error);
        }
    };

    const handleSelectAll = (e) => {
        if (e.target.checked) {
            const allLogIds = logs.map(l => l.id);
            setSelectedLogs(allLogIds);
        } else {
            setSelectedLogs([]);
        }
    };

    const handleSelect = (e, logId) => {
        if (e.target.checked) {
            setSelectedLogs([...selectedLogs, logId]);
        } else {
            setSelectedLogs(selectedLogs.filter(id => id !== logId));
        }
    };

    // Permanent delete of the selected rows (no soft-delete/undo on the server)
    const [deleting, setDeleting] = useState(false);
    const handleDeleteSelected = async () => {
        const count = selectedLogs.length;
        if (!count || deleting) return;
        if (!window.confirm(`Permanently delete ${count} selected IP log${count > 1 ? "s" : ""}? This cannot be undone.`)) return;

        setDeleting(true);
        try {
            const result = await locationApi.deleteIpLogs(selectedLogs);
            if (result?.statusCode !== 200) {
                alert(result?.message || "Failed to delete IP logs.");
                return;
            }
            setSelectedLogs([]);
            // If that emptied a later page, step back one page; otherwise reload this one
            if (count >= logs.length && currentPage > 1) {
                setCurrentPage((prev) => prev - 1);
            } else {
                fetchLogs(currentPage, pageSize);
            }
        } catch (error) {
            console.error("Error deleting IP logs:", error);
            alert("Failed to delete IP logs.");
        } finally {
            setDeleting(false);
        }
    };

    return (
        <section className="container admin-container">
            <div
                className="admin-header"
                style={{
                    display: "flex",
                    justifyContent: "space-between",
                    alignItems: "center",
                    flexWrap: "wrap",
                    gap: "15px",
                }}
            >
                <div className="page-header" style={{ marginBottom: 0 }}>
                    <div className="page-icon">
                        <Activity size={20} />
                    </div>
                    <h2>IP Logs</h2>
                </div>
                <button className="btn-secondary" onClick={handleExport} title="Export to Excel">
                    <Download size={15} />
                    Export
                </button>
            </div>

            <FilterBar
                search={search}
                onSearchChange={(v) => { setSearch(v); setCurrentPage(1); }}
                placeholder="Search IP, country, city, browser or OS..."
                selects={[{
                    key: "deviceType",
                    label: "Device",
                    value: deviceType,
                    onChange: (v) => { setDeviceType(v); setCurrentPage(1); },
                    options: [
                        { value: "", label: "All devices" },
                        { value: "Desktop", label: "Desktop" },
                        { value: "Mobile", label: "Mobile" },
                        { value: "Tablet", label: "Tablet" },
                        { value: "Bot", label: "Bot" },
                    ],
                }]}
                onClear={() => { setSearch(""); setDeviceType(""); setCurrentPage(1); }}
            />

            {selectedLogs.length > 0 && (
                <div className="bulk-actions bulk-bar" role="region" aria-label="Bulk actions">
                    <span className="bulk-count">{selectedLogs.length} selected</span>
                    <button
                        type="button"
                        className="apply-btn btn-danger"
                        onClick={handleDeleteSelected}
                        disabled={deleting}
                    >
                        <Trash2 size={15} />
                        {deleting ? "Deleting..." : "Delete permanently"}
                    </button>
                    <button type="button" className="btn-secondary" onClick={() => setSelectedLogs([])}>
                        <X size={15} /> Clear selection
                    </button>
                </div>
            )}

            <div className="table-wrapper">
                {loading ? (
                    <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>
                ) : (
                    <table>
                        <thead>
                            <tr>
                                <th style={{ width: '50px' }}>
                                    <input
                                        type="checkbox"
                                        checked={selectedLogs.length === logs.length && logs.length > 0}
                                        onChange={handleSelectAll}
                                        style={{ verticalAlign: 'middle' }}
                                    />
                                </th>
                                <th>ID</th>
                                <th>IP Address</th>
                                <th>Country</th>
                                <th>Region</th>
                                <th>City</th>
                                <th>Device</th>
                                <th>Browser</th>
                                <th>OS</th>
                                <th>Machine Name</th>
                                <th>Counter</th>
                                <th className="col-actions">Actions</th>
                            </tr>
                        </thead>
                        <tbody>
                            {logs.length === 0 ? (
                                <tr>
                                    <td colSpan="12" style={{ textAlign: "center" }}>
                                        No IP logs found.
                                    </td>
                                </tr>
                            ) : (
                                logs.map((log) => (
                                    <tr key={log.id} className={selectedLogs.includes(log.id) ? 'selected-row' : ''}>
                                        <td>
                                            <input
                                                type="checkbox"
                                                checked={selectedLogs.includes(log.id)}
                                                onChange={(e) => handleSelect(e, log.id)}
                                                style={{ verticalAlign: 'middle' }}
                                            />
                                        </td>
                                        <td>{log.id}</td>
                                        <td>{log.ip}</td>
                                        <td>{log.country || "-"}</td>
                                        <td>{log.region || "-"}</td>
                                        <td>{log.city || "-"}</td>
                                        <td>
                                            <span className={`status-badge ${log.deviceType === 'Bot' ? 'status-badge-warning' : 'status-badge-muted'}`}>
                                                {log.deviceType || "-"}
                                            </span>
                                        </td>
                                        <td>
                                            <div className="truncate-text" title={log.browser}>
                                                {log.browser || "-"}
                                            </div>
                                        </td>
                                        <td>
                                            <div className="truncate-text" title={log.operatingSystem}>
                                                {log.operatingSystem || "-"}
                                            </div>
                                        </td>
                                        <td>{log.machineName || "-"}</td>
                                        <td>{log.counter}</td>
                                        <td>
                                            <div className="action-buttons">
                                                <button
                                                    className="icon-btn view-btn"
                                                    onClick={() => setSelectedLog(log)}
                                                    title="View Details"
                                                >
                                                    <Eye size={18} />
                                                </button>
                                            </div>
                                        </td>
                                    </tr>
                                ))
                            )}
                        </tbody>
                    </table>
                )}
            </div>

            {/* Pagination Controls */}
            {!loading && totalItems > 0 && (
                <Pagination
                    currentPage={currentPage}
                    pageSize={pageSize}
                    total={totalItems}
                    itemCount={logs.length}
                    onPrev={handlePrev}
                    onNext={handleNext}
                    canNext={currentPage < totalPages}
                    onPageSizeChange={(size) => { setPageSize(size); setCurrentPage(1); }}
                />
            )}

            {/* View Details Modal */}
            {selectedLog && (
                <div className="modal active">
                    <div
                        className="modal-content"
                        style={{ maxWidth: "600px", width: "90%" }}
                    >
                        <button type="button" className="close" aria-label="Close" onClick={() => setSelectedLog(null)} style={{ background: 'none', border: 0, padding: 0 }}>
                            &times;
                        </button>
                        <h2>IP Log Details</h2>
                        <div
                            style={{
                                marginTop: "20px",
                                display: "flex",
                                flexDirection: "column",
                                gap: "15px",
                            }}
                        >
                            <div>
                                <strong>ID:</strong> {selectedLog.id}
                            </div>
                            <div>
                                <strong>IP Address:</strong> {selectedLog.ip}
                            </div>
                            <div>
                                <strong>Country:</strong> {selectedLog.country || "-"}
                            </div>
                            <div>
                                <strong>Region:</strong> {selectedLog.region || "-"}
                            </div>
                            <div>
                                <strong>City:</strong> {selectedLog.city || "-"}
                            </div>
                            <div>
                                <strong>Device Type:</strong> {selectedLog.deviceType || "-"}
                            </div>
                            <div>
                                <strong>Browser:</strong> {selectedLog.browser || "-"}
                            </div>
                            <div>
                                <strong>Operating System:</strong> {selectedLog.operatingSystem || "-"}
                            </div>
                            <div>
                                <strong>User Agent:</strong>
                                <div style={{ background: 'var(--input-bg)', padding: '10px', borderRadius: '5px', wordBreak: 'break-all', marginTop: '5px', fontSize: '13px' }}>
                                    {selectedLog.userAgent || "-"}
                                </div>
                            </div>
                            <div>
                                <strong>Machine Name:</strong> {selectedLog.machineName || "-"}
                            </div>
                            <div>
                                <strong>Counter:</strong> {selectedLog.counter}
                            </div>
                            <div>
                                <strong>Created On:</strong>{" "}
                                {selectedLog.createdOn
                                    ? new Date(selectedLog.createdOn).toLocaleString()
                                    : "-"}
                            </div>
                            <div>
                                <strong>Updated On:</strong>{" "}
                                {selectedLog.updatedOn
                                    ? new Date(selectedLog.updatedOn).toLocaleString()
                                    : "-"}
                            </div>
                            <div>
                                <strong>Platform:</strong> {selectedLog.platform || "-"}
                            </div>
                            <div>
                                <strong>Json:</strong> {selectedLog.json || "-"}
                            </div>
                        </div>
                    </div>
                </div>
            )}
        </section>
    );
}