import React, { useEffect, useState } from 'react';
import { Search, X } from 'lucide-react';

// Returns `value` after it has stopped changing for `delay` ms (for server-side search)
export function useDebouncedValue(value, delay = 400) {
    const [debounced, setDebounced] = useState(value);
    useEffect(() => {
        const timer = setTimeout(() => setDebounced(value), delay);
        return () => clearTimeout(timer);
    }, [value, delay]);
    return debounced;
}

// One filter bar for every admin list page:
//   [🔍 Search…            x]  [Status ▾]  [Type ▾]   Clear filters
// selects: [{ key, label, value, onChange, options: [{ value, label }] }]
// An empty-string option value means "All".
export default function FilterBar({ search, onSearchChange, placeholder = 'Search...', selects = [], onClear }) {
    const hasActiveFilter = !!search || selects.some(s => s.value !== '' && s.value !== undefined && s.value !== null);

    return (
        <div className="filter-bar" role="search">
            {onSearchChange && (
                <div className="filter-search">
                    <Search size={16} className="filter-search-icon" aria-hidden="true" />
                    <input
                        type="text"
                        value={search}
                        onChange={(e) => onSearchChange(e.target.value)}
                        placeholder={placeholder}
                        aria-label={placeholder.replace(/\.+$/, '')}
                        maxLength={100}
                    />
                    {search && (
                        <button type="button" className="filter-search-clear" onClick={() => onSearchChange('')} aria-label="Clear search" title="Clear search">
                            <X size={14} />
                        </button>
                    )}
                </div>
            )}

            {selects.map(s => (
                <select
                    key={s.key}
                    className="filter-select"
                    value={s.value}
                    onChange={(e) => s.onChange(e.target.value)}
                    aria-label={s.label}
                    title={s.label}
                >
                    {s.options.map(o => <option key={o.value} value={o.value}>{o.label}</option>)}
                </select>
            ))}

            {onClear && hasActiveFilter && (
                <button type="button" className="link-btn filter-clear" onClick={onClear}>
                    Clear filters
                </button>
            )}
        </div>
    );
}
